pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream),
    // but we treat small gaps (< 10) as almost certainly dead, and gaps below half the
    // smallest common item as risky.
    if post_residual < 10 {
        score += 500.0; // tiny unusable sliver: worst outcome
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 35 {
        score += 25.0;
    }

    // Reward near-perfect packing (exact or near-exact fills).
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Open-bins pressure: discourage proliferating bins; prefer filling existing ones
    // when the fit is decent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 8.0 * (1.0 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement
    // to enable a perfect follow-up fill.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            // next item fits too: mild reward proportional to tightness of that fit
            let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 40.0 * next_tightness;
        } else {
            // next item cannot use this bin's gap: if gap is small, it's dead space
            if post_residual < next_item_size && post_residual < 10 {
                score += 150.0;
            }
        }
    }

    // Mean-residual coupling: if this bin's residual deviates favorably from the mean,
    // prefer balancing residuals (avoid many half-empty bins).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // New-bin candidate: brand-new empty bin. Only attractive when the item is large
    // (would leave big awkward gaps in an open bin) or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are used only when justified.
        score += 350.0;
        // Large items pair well with a fresh bin (room for complements).
        score -= 200.0 * large_item * large_item;
        // If several bins fit, opening a new one is rarely justified.
        if fitting_bins_count > 1 {
            score += 150.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harder than large residuals.
    // Gaps in (0, 10) are essentially dead (items >= 1 though, so scale by size range).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Dead space: heavily penalize, worse the smaller the gap.
            score += (12.0 - gap) * 4.0;
        } else if gap <= 25.0 {
            // Small gaps are only useful for tiny items; mild penalty.
            score += gap * 0.15;
        } else {
            // Large residuals remain flexible: reward proportionally.
            score -= gap * 0.35;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Prefer bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + 0.5 * progress) * 0.8;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave this bin's post-residual dead, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain
        // and current bins are fragmented (high mean residual spread).
        score = 30.0 - (mean_residual / bin_capacity as f64) * 10.0 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fill is perfect.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Classify post_residual by integer division into dead-space classes.
        // Small leftovers (< 10) are nearly unusable dead space -> penalize hard.
        if post_residual < 10 {
            score += 120.0;
        } else if post_residual <= 20 {
            score += 40.0;
        } else if post_residual <= 40 {
            score += 10.0;
        } else {
            score -= 15.0; // large residual stays reusable
        }

        // Harmonic bonus: post_residual divisible into useful chunk classes.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 25.0;
        }
        if post_residual == half || post_residual == quarter {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 60.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual at all: it is dead for lookahead
            score += 30.0;
        }
    } else {
        // last item: prefer exact fill strongly
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // among open bins or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let tight_fit_exists = mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 10.0;
        if fitting_bins_count == 0 || (item_size as f64 > mean_residual + 25.0 && !tight_fit_exists) {
            score -= 100.0;
        } else {
            score += 150.0; // prefer filling existing bins normally
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Mild pressure to keep the fleet of open bins tight.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Slight nudge toward bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else if fit_ratio < 0.05 {
        score -= 200.0;
    } else if fit_ratio < 0.15 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too; penalize leftover waste after hypothetical chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste.min(60.0);
        } else {
            // Next item does NOT fit here: dead space risk, penalize.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving a residual far below mean means this bin becomes hard to reuse.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score += (0.5 - rel) * 50.0; // bin becomes an outlier of tiny space
        } else if rel > 1.5 {
            score -= (rel - 1.5) * 10.0; // keeping large usable residual is fine
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly so tight fits
    // in existing bins win, but keep it competitive vs. bad fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheap/flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (perfect 2-chain), moderately reward
    // bins that can still host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain: close the bin completely
        } else if post_residual >= next_item_size {
            score -= 25.0; // next item still fits: keep the chain going
        } else {
            // dead space smaller than the next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.6;
        }
    }

    // Penalize leaving tiny unusable slivers in general.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fills relative to the mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large and current
    // bins would leave big dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        let best_alt = if fitting_bins_count > 0 {
            // rough estimate of residual if placed in an existing bin
            (mean_residual - item_f).max(0.0)
        } else {
            100.0
        };
        let dead_alt = best_alt.min(9.0);
        // open a new bin only if every existing fit would strand < 10 units
        score += if fitting_bins_count > 0 && dead_alt >= 1.0 {
            45.0 // existing bins leave usable slivers -> prefer them
        } else {
            -5.0 // no good alternative -> allow a fresh bin
        };
        // prefer opening bins early in the stream (amortization)
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= (1.0 - progress) * 5.0;
        }
    }

    // Mild penalty for bin sprawl when many bins are already open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small for typical future items
    let dead_zone: f64 = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 120.0 - crowd * 10.0;
        // If lookahead item can use the remaining space after placement, soften
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 40.0;
        }
    }

    // Pressure from too many open bins: favor consolidating into existing bins
    score += open_bins_count as f64 * 0.5;

    // Lookahead synergy: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual && post_residual > 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Dead-space classes: post residual in (10, 20) is a classic trap zone
    if post_residual > 10 && post_residual < 20 {
        score += 40.0;
    }

    // Integer-division thresholds on post_residual vs capacity fractions
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    if post_residual > half {
        score -= 25.0; // bin still very usable after placement
    } else if post_residual > quarter {
        score += 5.0;
    }

    // Modulo classes: residuals congruent to small multiples of 10 pack well
    let m = post_residual % 10;
    if m == 0 {
        score -= 20.0;
    } else if m <= 2 {
        score -= 8.0;
    } else {
        score += (m as f64) * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize fresh bins unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (cap - 60.0);
        if crowded || fitting_bins_count == 0 {
            score += 5.0; // still slightly worse than a good existing fit
        } else {
            score += 150.0; // discourage opening new bin when space exists
        }
    }

    // Progression coupling: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post / cap);

    // Prefer bins tighter than the mean (best-fit flavor)
    score += (post - mean_residual).clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for near-perfect fits (small post_residual is already the base score).
    let tightness = 1.0 - post / cap;
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item won't fit here: penalize proportional to wasted potential.
            score += 0.15 * (nxt - post).min(cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving awkward dead space (small but nonzero residuals that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate logic: only attractive when no good open option exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is more acceptable early and when many bins are open / mean residual is low.
        score += 55.0
            - 20.0 * progress
            - 1.5 * (open_bins_count as f64)
            - 0.3 * mean_residual;
        // Never open a new bin when a dedicated last-chance bin exists.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins to reduce bin count pressure.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins whose residual deviates favorably from the mean (tighter than average).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins out (filling them fully).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, softly normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate larger residuals less harshly; late, demand tight fits.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 0.35 * (1.0 - progress) * (pr / cap) * (pr / cap)
           - 0.15 * p2 * (pr / cap)
           + 0.10 * p3 * (pr / cap).sin();

    // Reward near-perfect fits smoothly (quadratic trough at pr == 0)
    score -= 0.6 * (-pr / 12.0) * (-pr / 12.0) * (1.0 - progress);

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n > pr {
            score += 0.25 * ((n - pr) / cap) * (1.0 + progress);
        } else {
            // smooth reward for leaving room usable by next item
            score -= 0.20 * (1.0 - (pr - n) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
