        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win
        score += 30.0;
        // If few bins fit or open-bin residuals are fragmented, encourage a fresh bin
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
        // Early in stream, slightly prefer opening bins (build diverse residual pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Global state: with many open bins, prefer consolidating into existing ones
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins below mean residual (larger-than-average space) for big items
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: late in stream, tighten up — avoid leaving awkward residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 && post_residual < 20 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover residual, with a non-linear (quadratic) waste term
    let mut score = pr + 8.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling: residual's badness grows with stream progress
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Reward tight fits: low post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual deviates from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // mild spread penalty when many bins compete
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving a gap that fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: keep it attractive early, less so late (prefer consolidation)
    if bin_residual == bin_capacity {
        let bias = 6.0 - 12.0 * progress;
        score += bias;
    }

    // Mild penalty for proliferating open bins
    score += 1.5 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls in.
    let item_class = item_size / 10; // 0..=10 coarse harmonic class
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: does next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Pairing quality: how snugly the next item fills the leftover.
        let pair_waste = (post_residual - next_item_size) as f64;
        let pair_bonus = 25.0 * (1.0 - pair_waste / cap);
        // Stronger bonus when item and next item are in complementary classes
        // (e.g. 60+40, 70+30, 50+50 style harmonic complements).
        let complement = ((item_size + next_item_size) as i32 - bin_capacity as i32).abs() as f64;
        score -= pair_bonus + 20.0 * (1.0 - complement / cap);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize leaving residual just above a
        // "dead zone" (residual in (0, next_item_size) is unusable for next).
        if post_residual > 0 {
            score += 12.0;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover space.
    let post_class = post_residual / 10;
    match post_class {
        0 => score -= 15.0,          // nearly full: excellent
        1 => score -= 8.0,           // small leftover, likely fillable
        2 | 3 => score += 3.0,       // awkward mid zone
        4 | 5 => score += 6.0,       // half-empty: mediocre
        _ => score += 2.0,           // large leftover: still reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default penalty so open bins with decent fits win...
        let mut new_bin_score = 35.0;
        // ...but if nothing fits well (post residual would be tiny in every
        // existing bin is unknown; use mean_residual as proxy) or the stream is
        // early with few bins, opening fresh is attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        // If mean residual is small (bins are packed tight), a new bin is good.
        new_bin_score -= 20.0 * (1.0 - mean_residual / cap);
        // Late in the stream, avoid sprawl: penalize new bins more.
        new_bin_score += 15.0 * progress;
        // If many bins are open already, prefer consolidating.
        new_bin_score += (open_bins_count as f64).min(20.0) * 0.5;
        score = new_bin_score;
    }

    // Mild penalty for very large residual gaps that no small item class can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny crumbs are near-perfect fills
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste — punish them quadratically.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect lookahead fit: keep room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that the next item almost fits but misses.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over spreading; with few bins, opening new ones is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += pressure * 0.4 * (0.5 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bin fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0 || (post_residual as f64) > mean_residual;
        score = if poor_fits { 5.0 } else { 60.0 + mean_residual };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight dead space relative to capacity.
    let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
    score += 0.35 * post_residual as f64 * tightness;

    if next_item_size > 0 {
        // Perfect 2-step match: next item exactly fills post_residual -> strong reward.
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit in the leftover: penalize large unusable leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(50.0);
        }
    } else {
        // Last item: closing out bins tightly is best.
        score -= 25.0;
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // above average wastes the "large" residual; prefer bins near/below mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.25 * diff;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 10 {
            score -= 20.0; // near-perfect closure of a bin
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= 60 {
            // Big upcoming item: keep residual space small everywhere; a fresh
            // bin is fine as a buffer but not preferred.
            score += 15.0;
        }
        if fitting_bins_count >= 2 {
            score += 40.0; // plenty of alternatives -> discourage new bin
        }
        if mean_residual < 15.0 && open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 20.0; // all open bins are nearly full -> open fresh bin
        }
    }

    // Early in the stream, be slightly more willing to open bins for structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize post-residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward keeping room for the lookahead item
            let slack_fit = (post_residual - next_item_size) as f64;
            score -= 2.0 * slack_fit / bin_capacity as f64;
        } else {
            // Post-residual too small for next item -> dead space
            let dead = post_residual as f64;
            score += 3.0 + 6.0 * dead / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual != bin_capacity {
        score -= open_pressure * 1.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: only attractive when residuals are large/wasteful
    if bin_residual == bin_capacity {
        let mean_waste = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly by default; discount when open bins are fragmented
        let fragmentation = if fitting_bins_count > 0 {
            1.0 - (item_size as f64 / bin_residual.max(1) as f64)
        } else {
            1.0
        };
        score += 6.0 - 4.0 * mean_waste - 2.0 * fragmentation - 1.5 * (1.0 - progress);
    }

    // Time horizon: late in the stream, be more conservative, fill bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post_frac = post / cap;

    // Base: non-linear waste penalty (quadratic in post residual)
    let mut score = post + 8.0 * post * post_frac;

    // Smooth stream-progress coupling: later in stream, penalize waste more heavily
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: post residual vs mean residual (avoid leaving bins far from the mean)
    let mean_frac = mean_residual / cap;
    score += 4.0 * (post_frac - mean_frac).abs() * (1.0 + progress);

    // Cubic interaction between item size fraction and post residual
    let item_frac = item_size as f64 / cap;
    score -= 6.0 * item_frac * item_frac * item_frac * (cap - post);

    // Lookahead: reward bins whose post residual cannot fit next item (keeps big gaps for big items)
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            score -= 3.0 * (next - post) / cap;
        } else {
            score += 2.0 * (post - next) / cap;
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, scaled by how many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residual classes of capacity/8.
    // Residuals in the lowest class (<= cap/8) are near-perfect fits -> reward strongly.
    let class_width = cap / 8.0;
    let post_class = (post_residual as f64 / class_width).floor() as u32;
    let next_class = if next_item_size > 0 { ((next_item_size as f64) / class_width).floor() as u32 } else { 0 };

    // Reward if next item's class matches post_residual class exactly (perfect future fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual as f64 - next_item_size as f64) / class_width;
        score -= 12.0 * (1.0 - diff.min(1.0));
        // Integer-division exact fit: post_residual divisible relationship
        if post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally
        score += 6.0;
    }

    // Class-based reward: lower post class (tighter fit) is better.
    score -= (7 - post_class.min(7)) as f64 * 3.0;

    // Dead-space penalty: residual in (cap/8, cap/4) with no matching next item is worst zone.
    if post_residual > 12 && post_residual < 25 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item is large (> cap/2), opening fresh may be fine.
        if item_size as f64 > cap / 2.0 {
            score -= 10.0;
        }
    }

    // Progression-aware: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are "dead space". Penalize them hard.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits (small but still "usable" leftovers).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // If the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.8 + 8.0;
    }
    // If next item would be stranded by this placement (fits now but not after), penalize.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (avoid fragmentation); when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(15.0);
    } else {
        // New-bin candidate: neutral base, slightly discouraged unless fit elsewhere is bad.
        score += 5.0 + mean_residual * 0.05;
    }

    // Prefer bins whose residual is close to the item (tight coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // perfect match gets -60, decays with slack
    }

    // Penalize dead space that can never be used by typical items (<= 80)
    let dead = if post_residual > 80 { 0.0 } else if post_residual > 0 && next_item_size > post_residual { post_residual as f64 } else { 0.0 };
    score += 1.5 * dead;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early in stream: slightly favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for near-perfect fits (small post_residual is already the base score).
    let tightness = 1.0 - post / cap;
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item won't fit here: penalize proportional to wasted potential.
            score += 0.15 * (nxt - post).min(cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving awkward dead space (small but nonzero residuals that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate logic: only attractive when no good open option exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is more acceptable early and when many bins are open / mean residual is low.
        score += 55.0
            - 20.0 * progress
            - 1.5 * (open_bins_count as f64)
            - 0.3 * mean_residual;
        // Never open a new bin when a dedicated last-chance bin exists.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins to reduce bin count pressure.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins whose residual deviates favorably from the mean (tighter than average).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins out (filling them fully).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress * 0.8);

    let mut score = pr + 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize post residuals that are small but unusable relative to next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 + 6.0 * (nx - pr) / cap;
        } else {
            score -= 5.0 * (1.0 - (pr - nx).min(cap) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when this bin deviates from the mean residual (fragmentation).
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: make it moderately attractive only early or for big items.
    if bin_residual == bin_capacity {
        let big = (item_size as f64 / cap) > 0.6;
        let discount = if big { 15.0 } else { 3.0 };
        score -= discount * (1.0 - progress);
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "resonant"
    // classes (small, re-usable slivers) are penalized; mid-range leftovers that
    // match common item sizes are rewarded.
    let cap = bin_capacity as f64;

    // Reward tight fits strongly (near-zero post residual).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic class: post_residual bucketed by capacity fractions (1/8 steps).
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 0..7
    match class {
        0 => score -= 6.0,   // 0..12.5: nearly full, good
        1 => score += 4.0,   // 12.5..25: awkward dead zone
        2 => score -= 2.0,   // 25..37.5: fits medium items
        3 => score += 1.0,   // 37.5..50: mediocre
        4 => score -= 3.0,   // 50..62.5: fits half-capacity items
        _ => {}              // large residuals: neutral (score already high)
    }

    // Integer-division threshold: leftover that can hold a common item class
    // (multiples of 10) is valuable.
    if post_residual >= 10 && (post_residual % 10) <= 3 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // proportional reward for how well next item fits
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            if fit_ratio > 0.7 {
                score -= 8.0 * fit_ratio;
            }
        } else {
            // next item cannot fit here: slight penalty if we're wasting a good bin
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when all open bins are crowded or the
    // item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        let late = step_index as f64 / total_items.max(1) as f64;
        if crowded {
            score -= 10.0;
        } else {
            score += 12.0; // discourage opening new bins when open bins are roomy
        }
        if late > 0.9 {
            score += 5.0; // late stream: consolidate, avoid new bins
        }
    }

    // Mild pressure against spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // Small tie-break favoring bins whose residual is close to mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream),
    // but we treat small gaps (< 10) as almost certainly dead, and gaps below half the
    // smallest common item as risky.
    if post_residual < 10 {
        score += 500.0; // tiny unusable sliver: worst outcome
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 35 {
        score += 25.0;
    }

    // Reward near-perfect packing (exact or near-exact fills).
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Open-bins pressure: discourage proliferating bins; prefer filling existing ones
    // when the fit is decent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 8.0 * (1.0 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement
    // to enable a perfect follow-up fill.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            // next item fits too: mild reward proportional to tightness of that fit
            let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 40.0 * next_tightness;
        } else {
            // next item cannot use this bin's gap: if gap is small, it's dead space
            if post_residual < next_item_size && post_residual < 10 {
                score += 150.0;
            }
        }
    }

    // Mean-residual coupling: if this bin's residual deviates favorably from the mean,
    // prefer balancing residuals (avoid many half-empty bins).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // New-bin candidate: brand-new empty bin. Only attractive when the item is large
    // (would leave big awkward gaps in an open bin) or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are used only when justified.
        score += 350.0;
        // Large items pair well with a fresh bin (room for complements).
        score -= 200.0 * large_item * large_item;
        // If several bins fit, opening a new one is rarely justified.
        if fitting_bins_count > 1 {
            score += 150.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step chain: this item leaves exactly the space
    // the next item needs (residual becomes zero after both).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits but leaves some slack; mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space harder,
            // scaled by how close the leftover is to being useless.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }

        // Bonus if the chain leaves exactly zero residual (item + next == capacity).
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is already close to the mean (balanced packing),
    // penalize outliers that would strand space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it enables a perfect chain.
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if perfect_chain {
            score -= 20.0;
        } else {
            score += 18.0;
            // Late in the stream, opening new bins is cheaper than leaving fragments.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (1.0 - progress);
        }
    }

    // Small penalty per open bin to gently discourage fragmentation growth.
    score += 0.05 * open_bins_count as f64;

    // Reward extremely tight fits of the current item itself.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear term
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for perfect chain fit
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // cheaper to open a new bin late in the stream or when open bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 45.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // good idea to keep big space for big follow-up
        }
    }

    // Prefer bins with residual far from mean (best-fit style targeting)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Penalize spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize waste, with non-linear (quadratic/cubic) coupling to stream progress.
    // Late in the stream, residual waste is penalized more aggressively (convex growth).
    let mut score = pr * (1.0 + 1.5 * progress * progress) + 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth tight-fit reward: item filling most of the bin is favored, stronger late.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio * (1.0 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily (smooth bell).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let bell = (-gap * gap / 180.0).exp();
        score -= 30.0 * bell * (1.0 + progress);
        // Penalize leaving a residual just barely too small for the next item (dead space).
        if (next_item_size as f64) > pr {
            let miss = ((next_item_size as f64 - pr) / cap).min(1.0);
            score += 20.0 * miss * miss * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favored to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    }

    // Mild penalty when this bin's residual deviates from mean (favor consolidation).
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize mildly early, strongly when a decent fit exists late.
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit preference (smaller post_residual is better).
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that no future item
    // (sizes 1..=100) can ever fill is pure waste. Classify by modulo bands.
    let pr = post_residual;
    if pr > 0 {
        // Dead space in (0, small] is the worst: nearly nothing fits later.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 12.0;
        } else if pr < 30 {
            score += 5.0;
        }
        // Perfect fit: strongly reward.
        if pr == 0 {
            score -= 30.0;
        }
        // Harmonic "resonant" residuals: multiples of 10 leave room for
        // common size classes (10/20/50 etc.); mildly reward them.
        if pr % 10 == 0 && pr >= 10 {
            score -= 3.0;
        }
        // Odd residuals are less likely to be reusable exactly.
        if pr % 2 == 1 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead (k=2): reward if the next item exactly fills post_residual,
    // penalize if next item would be blocked by a near-full bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3; // next item also fits
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when no open bin offers a decent fit. Estimate fit
    // quality via mean residual of open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Opening a new bin: cost grows with number of open bins and progress.
        score += 15.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if open bins are nearly full on average, new bin is reasonable.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    } else {
        // Prefer bins that are tighter than average (fill full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly unusable
    // for items >= 10, so heavily penalize them.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64) / 13.0;
    }
    if post_residual >= 13 && post_residual < 20 {
        score += 6.0;
    }

    // Reward very tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further
    // (prefer filling existing bins), but leave room for the new-bin candidate.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64).ln() * 2.0;
    } else {
        // New empty bin: penalize moderately so it only wins when fits are bad.
        score += 8.0 + 0.05 * open_bins_count as f64;
    }

    // Lookahead: if next item would fit into this bin's post_residual,
    // reward the placement (keeps gaps usable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the fullest bins first keeps others flexible).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.1;

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // unusable gap for the lookahead item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // usable remainder: mild reward scaled by how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.3 * (1.0 - slack / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fill
        score += 0.0;
    }

    // Reward bins that are already relatively full (small residual relative to mean)
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer placing into existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open or early in stream
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for leaving very small unusable fragments (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold typical items
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: penalize proportionally
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with residual below mean (consolidate large holes)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be picky (favor best-fit); late, reduce new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize more when many open bins and high progress
        score += 60.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if current bin would leave awkward residual, new bin becomes attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
    } else if open_bins_count > 0 {
        // Slight bonus for using existing bins as stream progresses
        score -= 5.0 * progress;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping.
    let mut score = post * (1.0 + post_norm * post_norm);

    // Smooth progress coupling: later in the stream, tighten tolerance for wasted space.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += post_norm * tightness * cap * 0.5;

    // Reward filling bins nearly completely (smooth exponential reward).
    score -= (1.0 - post_norm).exp() * cap * 0.3;

    // Penalize bins that are far from the mean residual (avoid fragmentation outliers).
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * 0.4;

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= (1.0 - gap).exp() * cap * 0.25;
        } else {
            score += (nxt - post) / cap * cap * 0.15;
        }
    }

    // New-bin candidate: mildly penalize opening new bins early; allow later when residuals are tight.
    if bin_residual == bin_capacity {
        let early_penalty = (1.0 - progress) * cap * 0.8;
        score += cap * 0.2 + early_penalty;
    }

    // Slight penalty proportional to number of open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Quarters / eighths harmonic classes: reward residuals near nice fractions
    let eighth = (pr as u32 % (bin_capacity / 8).max(1)) as f64;
    score -= 2.0 * (1.0 - eighth / (bin_capacity / 8).max(1) as f64);

    // Integer division thresholds on post_residual
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual < 10 {
        score -= 20.0; // nearly dead space, good
    } else if post_residual < 30 {
        score += 5.0; // awkward mid gap
    }

    // Modulo classes of post_residual (harmonic buckets of 10)
    let bucket = (post_residual % 10) as f64;
    score -= 1.5 * (bucket / 10.0);

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fit_gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - fit_gap as f64 / cap);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = 60.0 * (1.0 - pressure) + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // opening fresh bin is fine when nothing else fits well
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin accommodates lookahead comfortably
        }
    }

    // Stream progression: later in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (frac - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (min item size 1, but practical waste zone < 12).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 25.0; // heavy penalty for tiny gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item can exactly fill the leftover,
    // this is a chained perfect fit -> big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 55.0;
        } else if slack_after_next < 12 {
            score += (12 - slack_after_next) as f64 * 10.0; // next item creates dead space
        } else {
            score -= 8.0; // bin remains usable after next item
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 12 {
            score += 40.0; // but not if it creates dead space
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> tolerate spreading.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: opening fresh is only attractive when
    // this bin's fit would leave a large unusable gap. Empty bin has
    // post_residual = capacity - item_size (large), so baseline favors it
    // on big gaps; add a mild tax so consolidation wins ties.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mild drift: later in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual.min(20) as f64);

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of next item into post_residual is ideal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 60.0; // reward bins that can host the next item
        score -= (slack_after_next as f64) * 0.5; // prefer tight two-item packing
        if slack_after_next == 0 {
            score -= 40.0; // perfect 2-item closure
        }
        // If the next item fills this bin exactly, and other bins exist, big bonus.
        if slack_after_next == 0 && open_bins_count > 1 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize relative to how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.4;
        if post_residual < 10 {
            score += 15.0; // dead space below min item size is wasted
        }
    }

    // Compare against mean residual: bins with residual far below mean are "tight"
    // and should be filled first to consolidate space.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Progress-aware conservatism: early in stream, tolerate opening bins more;
    // later, avoid proliferation of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Penalize very small leftover fragments generally.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual, non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, keeping this
    // residual is valuable; if not, the residual is likely dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Residual cannot host the next item; penalize more if the gap is small
            // (near-miss wasted space) unless residual is tiny anyway.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (1.0 - gap / 80.0).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // existing bins are crowded (low mean residual) or many bins already fit
    // the item poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If open bins are nearly full on average, a new bin is reasonable.
        score -= 20.0 * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);
        // Early in the stream, prefer consolidating into few bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // If item is large relative to capacity, a fresh bin keeps flexibility.
        score -= 10.0 * (item_size as f64) / (bin_capacity as f64);
    } else {
        // Prefer placing into bins whose residual is close to the item size
        // (best-fit flavor) but avoid over-fragmenting when many bins exist.
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
        // Slight preference to fill bins with larger residuals first when
        // many open bins exist (bin consolidation pressure).
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect / near-perfect fits strongly.
    let fill_ratio = 1.0 - post / cap;
    score -= 18.0 * fill_ratio * fill_ratio * fill_ratio;

    // Exact fit: massive bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Smooth non-linear interaction: waste penalized more as stream progresses.
    let norm_post = post / cap;
    let waste_penalty = norm_post * norm_post * (1.0 + 3.0 * progress);
    score += 8.0 * waste_penalty;

    // Lookahead: reward if next item fits into the post residual (chaining),
    // scaled by how close the chain is (smooth coupling).
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 + 12.0 * tight * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that nothing upcoming can use, worse late.
        score += 6.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Slight preference for bins below mean residual early (balance), above late.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (2.0 - 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals that fall into "usable" harmonic classes (multiples of small divisors)
    // are more likely to be filled by future items -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class by post_residual mod small moduli: reward low remainders (alignable space).
    let mod3 = post_residual % 3;
    let mod5 = post_residual % 5;
    let mod10 = post_residual % 10;
    score -= (3 - mod3) as f64 * 0.4;      // divisible-by-3 residuals are harmonically useful
    score -= (5 - mod5) as f64 * 0.6;      // divisible-by-5 residuals align with 10-multiples
    score -= (10 - mod10) as f64 * 1.2;    // multiples of 10 are the best future targets

    // Integer-division threshold classes on post_residual (quarters of capacity).
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 25.0; // dead space: nearly-full bin, residual too small to matter much
    } else if post_residual <= bin_capacity / 2 {
        score -= 8.0;  // sweet spot: leaves room for a mid-size item
    }

    // Coupling with lookahead: if next item fits exactly in post_residual (harmonic match), strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how cleanly next item divides the leftover
            if post_residual % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
            score -= (20.0 - slack.min(20.0)) * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted alignment
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline cost so it is only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
        // but if no open bin can even be a decent host (large dead-space risk), allow opening
        if pr < 10.0 && next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, prefer tighter packing (harsher dead-space penalty).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler target.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - bin_res).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are "dead space" -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still host a meaningful next item,
    // especially if the lookahead item fits exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // lookahead won't fit here: mild penalty for stranded capacity
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // existing bins can still absorb items; encourage consolidation.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate mildly so it only wins when open bins
    // would create dead space; scale pressure with stream progress.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins whose residual is near the mean (avoid leaving outliers).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, mildly discourage unless it's a great moment.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Encourage new bin only when it enables a near-perfect pairing with the next item.
        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 <= 12.0 {
            score -= 30.0;
        } else {
            score += 15.0 + 0.05 * open_bins_count as f64;
        }
        return score;
    }

    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Perfect 2-step lookahead match: next item exactly fills the remainder.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if pr > nx {
            // Next item still fits afterwards: reward tight leftover gap.
            let gap = pr - nx;
            score -= 25.0 * (1.0 - gap / 40.0).max(0.0);
        } else {
            // Next item won't fit here afterwards: penalize dead space relative to next size.
            score += 8.0 + 0.5 * (nx - pr).min(40.0);
        }
    }

    // Reward leaving small residuals overall (tight packing), relative to mean residual.
    score -= 0.3 * (mean_residual - pr).max(-50.0).min(50.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward: subtract heavily as post_residual shrinks.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it, else item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty for wasting a scarce residual elsewhere.
    if fitting_bins_count > 2 && bin_residual != bin_capacity {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Lookahead: reward leaving space that exactly accommodates the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 20.0; // this bin becomes perfectly reusable
        } else if gap > 0 && gap <= 10 {
            score -= 8.0; // near-reusable
        } else if gap < 0 && gap >= -5 {
            score += 5.0; // next item barely won't fit here: dead space risk
        }
        // Penalize large unusable leftovers relative to the smallest useful item (1).
        if post_residual > 0 && post_residual < 10 {
            score += 4.0; // sliver waste
        }
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin is cheap early, expensive late.
        score += 15.0 + 25.0 * progress;
        // If existing bins are crowded (small mean residual), a new bin is reasonable.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        // If this is the only fitting option besides the new bin, prefer the open bin.
        if fitting_bins_count >= 1 {
            score += 12.0;
        }
        // Many open bins already: discourage fragmentation.
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Slight preference to keep bins balanced: avoid dumping into the emptiest bin.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Dead-space penalty grows with stream progress (less time to recover residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: residual waste penalized more as stream advances.
    let quad = pr_norm * pr_norm;
    score += 40.0 * quad * (0.5 + progress);

    // Cubic interaction: strongly discourage large residuals late in the stream.
    score += 25.0 * quad * pr_norm * progress;

    // Reward filling bins deeply (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap) * (1.0 - progress * 0.3);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty grows with progress.
        score += 5.0 * progress;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, slightly
    // penalized early (prefer reusing bins), less penalized when open bins
    // are fragmented (high mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 20.0 + 30.0 * fragmentation * progress + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes get strong rewards.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes via integer division on capacity fractions:
    // residual buckets: [0..=10), [10..=25), [25..=50), [50..=75), [75..=100]
    let class = post_residual / 13; // modulo-style bucketing
    score -= match class {
        0 => 60.0,          // tiny dead space, very desirable
        1 => 25.0,
        2 => 5.0,
        3 => -10.0,         // half-empty bins are wasteful
        _ => -25.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (5, 10, 20) are "usable" classes.
    if post_residual % 10 == 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Coupling with next item: if the next item fits exactly into the post
    // residual, strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a remainder; penalize by remainder class
            let rem = post_residual - next_item_size as f64;
            score -= 40.0 - rem.min(40.0);
        } else {
            // next item won't fit here: mild penalty proportional to waste
            score += (next_item_size as f64 - post).min(30.0);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual for empty bin == capacity - item). Penalize opening
    // a new bin unless its post residual is in a good harmonic class.
    if bin_residual == bin_capacity {
        let new_class = post_residual / 13;
        let base = 90.0 + open_bins_count as f64 * 5.0;
        score += base - if new_class == 0 { 70.0 } else if post_residual % 10 == 0 { 40.0 } else { 0.0 };
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., unusually full bin) is good; steer toward tighter bins.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res - mean_residual) * 0.5;
    }

    // Slight preference late in the stream to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Strict dead-space avoidance: residuals in the "unusable" gap
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fit
        score -= 50.0;
    } else if post_residual <= 10 {
        // dead zone: residual too small to ever be useful
        score += 40.0;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // If this is the ONLY bin that can fit the item, strongly prefer it
    // over opening a new bin (last-chance pressure).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and mildly discourage spreading into bins with large residuals.
    let pressure = open_bins_count as f64;
    if is_new_bin {
        score += 6.0 * pressure.sqrt();
        // Exception: late in the stream with a very tight fit elsewhere,
        // a fresh bin may be fine; slightly relax when progress is high.
        score -= 8.0 * progress;
    } else {
        score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item would exactly fit the post-residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits after this placement: mild reward
        score -= 3.0;
    }

    // Prefer bins whose residual is below average (consolidate waste),
    // unless the fit is tight.
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more dead space; mild reward proportional to fill
            score -= 50.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use the residual: penalize proportionally to wasted capacity
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize leaving large unusable gaps (below minimum item size 1 => any residual ok,
    // but gaps smaller than typical items are dead weight)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer opening a new bin early in the stream when existing bins are poor fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin baseline: neutral residual (100) adjusted by progress;
        // late in stream, prefer using open bins more
        score = 100.0 + 40.0 * (1.0 - progress) - 20.0 * progress;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 500.0;
        }
        if fitting_bins_count == 1 {
            // never open a new bin when this is the only fitting bin
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: squared waste penalizes poor fits super-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if the next item is large and this placement leaves a useless gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            let gap_excess = next_item_size as f64 - post_residual as f64;
            score += 0.10 * gap_excess.min(60.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a bin opening just for this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding factor: when many bins are open, consolidate into fuller bins;
    // when few bins are open, spreading is cheaper.
    let crowding = (open_bins_count as f64).ln().max(0.5);
    score += 2.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced) unless a tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative about opening new bins
    // (favor filling); late in the stream, allow more freedom since remaining
    // items are few.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64 - 0.5).abs();

    // New-bin candidate: opening a fresh bin is attractive when the item is large
    // and no good fit exists, but wasteful when open bins have plenty of room.
    if bin_residual == bin_capacity {
        let fullness = item_size as f64 / bin_capacity as f64;
        let open_room = mean_residual / bin_capacity as f64;
        score -= 8.0 * fullness;                       // large items like fresh bins
        score += 45.0 * open_room.max(0.0);            // penalize ignoring roomy bins
        if fitting_bins_count == 0 {
            score -= 50.0;                             // forced: must open
        }
        // Late stream: opening bins for leftovers is fine.
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, larger residuals are mildly acceptable; late in the stream,
    // leaving residual space is increasingly costly (quadratic penalty).
    let progress_coupling = progress * (post / cap) * (post / cap) * cap;
    score += 0.5 * progress_coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize new bins, more strongly as the stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using an existing bin, extra when it's the only fitting one.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 20.0 + 15.0 * progress;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < 0.5 {
        score -= 15.0;
    } else if next_item_size > post && next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 0.1 * ((next_item_size as f64 - post) / cap) * cap * 0.1;
    }

    // Deviation from mean residual: prefer bins whose residual after placement
    // is close to the mean, keeping flexibility spread evenly (smooth coupling).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.1;

    // Slight penalty for very large item-to-residual mismatch (dead space creation).
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 3.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "usable"
    // residue classes (multiples of 10) are more likely to host future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill fraction (non-linearly).
    score -= 40.0 * fill_frac * fill_frac;

    // Modulo-10 harmonic class of post_residual: exact multiples of 10 are
    // "harmonic" leftovers that match common item sizes; reward them.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.8;

    // Integer-division thresholds on post_residual: leftover buckets.
    let bucket = post_residual / 10; // 0..=10
    match bucket {
        0 => score -= 5.0,          // near-perfect fit
        1 => score -= 3.0,          // small usable leftover
        2 | 3 => score += 2.0,      // awkward mid leftover
        4 | 5 => score += 4.0,      // half-empty bin, mild penalty
        _ => score += 1.0,          // large leftover, still reusable
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else {
            // Next item cannot follow here; penalize if it would leave this
            // bin nearly empty anyway.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins when mean residual is low.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * (mean_residual / cap) * 4.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when no open bin offers a decent fit (post_residual small).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 12.0;
        // But if the current item is large (harmonic class of item_size),
        // starting fresh can be good: reward proportionally.
        let item_class = (item_size % 10) as f64;
        score -= 8.0 * (item_size as f64 / cap) - item_class * 0.3;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize tiny dead space that wastes capacity without being harmonic.
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste -> heavy penalty.
    if post_residual < 10 {
