    // Open-bin pressure: with many open bins, avoid opening new ones;
    // favor packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - 0.5 * progress);

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would not fit in post_residual but would fit in a fresh bin,
    // penalize slightly when post_residual is dead space for the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: an empty bin starts with a high base cost so it is
    // only chosen when existing bins fit poorly (large dead space).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // But if no tight option exists (many open bins with big residuals),
        // relax slightly to allow consolidation.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // Mild penalty for deviating from mean residual (keeps bin states uniform).
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

