    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the leftover space: mild reward proportional to how well it matches
        let match_ratio = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * match_ratio;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space growth
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average leftover is good (bin well-utilized)
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable fragments (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only prefer opening a new bin when existing bins leave
    // very fragmented space and item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized normally; reward only if existing residuals are tiny
        score = 60.0 - 40.0 * fragmentation + 10.0 * progress;
        if item_size > 60 && mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
    }

