    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit into post_residual,
    // but soften when the remaining stream is short.
    let progress = step_index as f64 / total_items as f64;
    if next_item_size > 0 {
        if next_item_size > post_residual {
            let horizon = 1.0 - progress;
            score += 6.0 * horizon;
        } else {
            // Reward bins that can still host the next item too.
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual everywhere) or the item
    // is large and would leave a big gap.
    if bin_residual == bin_capacity {
        let mean_gap = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Baseline penalty for opening a new bin; overcome only if existing
        // fits are bad.
        score += 15.0;
        if post_residual > item_size as f64 * 0.9 {
            // item is large; new bin keeps flexibility
            score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        }
        if mean_gap < 12.0 && open_bins_count > 0 {
            // open bins are nearly full anyway; new bin is fine
            score -= 18.0;
        }
        // Late in the stream, avoid proliferating bins with little use.
        if progress > 0.85 {
            score += 20.0 * progress;
        }
    } else {
        // Small bonus for reusing bins as they get fuller (encourage compaction).
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fullness;
    }

    // Mild penalty for leaving awkward mid-range gaps that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones harder.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - post / cap; // 0..1, near 1 for perfect fit
    score -= 45.0 * tightness * tightness * tightness;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals are less valuable (less time to fill them),
    // so penalize leftover space progressively.
    let decay = progress * progress;
    score += 25.0 * decay * (post / cap) * (post / cap);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_tight = 1.0 - ((post - nxt) / cap).abs();
            score -= 20.0 * next_tight * next_tight;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 8.0 * ((nxt - post) / cap);
        }
    }

    // Prefer bins whose residual is close to the mean (keeps bin population balanced),
    // unless this placement is exceptionally tight.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for opening a new bin when many bins are open but few fit,
    // encouraging consolidation; conversely, opening a fresh bin early is cheap.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 120.0; // never open new bin when a sole fitting bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

