    }

    // Integer-division thresholds: residual bucketed by fifths of capacity
    let fifth = bin_capacity / 5;
    let bucket = pr / fifth;
    score -= bucket as f64 * 3.0;

    // Coupling with lookahead item: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; residual class must still be generically useful
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current item leaves bad residual
    if bin_residual == bin_capacity {
        score += 25.0;
        if pr >= 10 && fitting_bins_count >= 1 {
            score += 90.0; // an open bin leaves a reusable class; prefer it
        }
        if fitting_bins_count == 1 {
            score -= 70.0; // no real alternative
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's already cramped — prefer filling it
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: late in stream, tighten packing (prefer tight fits more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - pr) as f64 * 0.2;

    // Modulo-10 harmonic texture on post_residual
    let m = pr % 10;
    score -= (m as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item (<= 10, or <= next item) are
    // effectively unusable -> heavy penalty.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0;
    }
    // Gap too small for the lookahead item: moderate penalty (wasted for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small relative dead space).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage consolidating when few bins are open.
    score += 0.6 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this bin's residual is very small relative to the item).
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.2;
        if poor_fit_everywhere {
            score -= 15.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mean residual coupling: bins far below mean residual are "loose";
    // prefer bins closer to the mean to keep residual distribution compact.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact lookahead match: post residual exactly equals next item size -> perfect 2-step packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small slack -> strong bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // slack 0 => -40, larger slack decays bonus
    }
    // If next item cannot fit in post residual, penalize proportionally to the gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to mean residual (below-mean waste is good).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize leaving tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: prefer it only when all open residuals are large (waste would be small anyway)
    // and this is not a last-chance situation.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && mean_residual < item_size as f64 + next_item_size as f64 {
            score -= 30.0; // open bins too full to chain two items -> open a fresh bin
        }
    }

    // Late in the stream, consolidate: favor existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Candidate for opening a fresh bin: only attractive if the item is large
        // or no good open-bin option exists. Penalize opening new bins when
        // many open bins could fit the item.
        let mut nb = post_residual as f64;
        if fitting_bins_count > 0 {
            nb += 40.0 + 12.0 * (fitting_bins_count as f64).ln();
        }
        // Late in the stream, opening new bins is wasteful.
        nb += 30.0 * progress;
        // Large items leave less residual; slightly favor new bins for them.
        nb -= (item_size as f64 - 50.0) * 0.15;
        return nb;
    }

    // --- Open bin scoring ---
    // Tight fit reward: squared post-residual normalized, small residuals get
    // disproportionately favored.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tight * 60.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward;
    // if post_residual is nonzero but too small for the next item, penalize
    // (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills
            let fill = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * fill;
        } else {
            // dead space for the next item: penalize more when residual is tiny
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 15.0 * (1.0 - waste.min(1.0));
        }
    } else {
        // Last item: just prefer the tightest fit anywhere.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Global state coupling: if the mean residual across open bins is low
    // (bins nearly full), prefer packing into existing bins.
    if mean_residual < 20.0 {
        score -= 8.0;
    } else if mean_residual > 50.0 {
        score += 6.0;
    }

    // Small early-stream tie-break: keep bins balanced early, exploit later.
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin's residual (1.0 = perfect fit)
    let tightness = 1.0 - (post_residual as f64) / (bin_residual.max(1) as f64);

    // Reward tight fits with a smooth non-linear coupling to progress
    score -= tightness * tightness * (cap * 0.5) * (0.6 + 0.8 * t);

    // Penalize large dead space non-linearly (quartic-ish growth)
    let dead = post_residual as f64 / cap;
    score += dead * dead * dead * cap * 0.35;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.9;
    }

    // New-bin candidate: prefer opening a new bin only when the item fits poorly
    // everywhere else; otherwise penalize wasting a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        // Penalize new bin unless the item is large (fills it well)
        score += cap * (1.2 - fill * fill * 1.8);
        // Early in the stream, opening new bins is cheap (keeps flexibility)
        score -= (1.0 - t) * cap * 0.25;
    }

    // Lookahead: if next item fits perfectly in the post residual, reward this placement
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= (1.0 - gap / cap).max(0.0) * cap * 0.3 * t;
        // If next item won't fit in post residual, mild penalty for leaving awkward space
        if next_item_size as f64 > post_residual as f64 {
            score += (next_item_size as f64 - post_residual as f64) / cap * cap * 0.15;
        }
    }

    // Coupling with mean residual: discourage placing into bins that deviate
    // strongly from the mean residual (keeps bin states homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.2;

    // Slight preference to fill existing bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in low classes (small leftovers)
    // are "dead space" -> penalize; exact/near-zero fits are gold.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class by integer division of capacity into harmonic fractions
    let class = (pr / (c / 8.0)).floor() as i32; // 0..8 harmonic class
    let class_penalty: [f64; 9] = [-60.0, -40.0, -20.0, 0.0, 10.0, 25.0, 40.0, 55.0, 70.0];
    score += class_penalty[class.min(8).max(0) as usize];

    // Perfect fit: exact zero residual is heavily rewarded
    if post_residual == 0 {
        score -= 200.0;
    }
    // Near-perfect fits (residual < smallest plausible item) rewarded
    else if post_residual < 5 {
        score -= 120.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of common
    // item-size classes (e.g. multiples of 10, 20, 25) are more likely to be
    // filled by future items -> reward them.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 15.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 10.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next item decides quality
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: slight penalty for stranding capacity
            let wasted = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += wasted * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new
    // bin unless fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if no open bin can fit at all, new bin is fine
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // early in stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Best-fit flavor: tighter fit relative to mean residual is favored
    score -= (mean_residual - pr).max(0.0) * 0.5;

    // Mild preference for fuller bins when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual <= 10 {
        // Unusable dead space: heavy penalty proportional to tightness of fit
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 25 {
        // Marginal zone: moderate penalty
        score += (25 - post_residual) as f64 * 1.5;
    } else {
        // Large residual is flexible: mild reward for keeping usable space
        score -= 2.0;
    }

    // Reward tight fits relative to item size
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize adding bins when many are open
    score += open_bins_count as f64 * 0.8;

    // Prefer bins below mean residual (consolidate space)
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover: penalize more if leftover is small
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // New-bin candidate: make it attractive only when fits are poor or few bins fit
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5 || (post_residual < 10 && post_residual >= min_item);
        if poor_fit || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 20.0 + open_bins_count as f64 * 1.5;
        }
    }

    // Slight late-stream conservatism: keep residuals usable toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: residuals too small for the smallest item (1) are less
    // problematic, but very small residuals relative to capacity are wasted.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // 2-step lookahead: if the next item fits exactly or well in the leftover,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap * 0.3;
        if gap == 0.0 {
            score -= 200.0; // exact 2-chain match
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover won't serve the next item; mild penalty scaled by wasted fraction
        score += residual_frac * 30.0;
    }

    // Prefer tightest fit relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when placements
    // into open bins are poor (their scores stay above this baseline).
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Mild preference for filling more-full bins first.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: how well the item fills the residual
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for small dead space (wasted slivers)
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
        // Reward high fit ratio (item consumes most of residual)
        score -= fit_ratio * 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64 / bin_capacity as f64) * 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space that the next item cannot use
        let waste = post_residual as f64 - (next_item_size as f64 * 0.0);
        score += waste * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit even more
        score += fitting_bins_count as f64 * 2.0;
    }

    // Global state: many open bins with small residuals -> prefer filling existing bins
    let avg_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
    if avg_res > 0.0 {
        // Encourage placements that bring this bin's residual below the mean (consolidation)
        if (post_residual as f64) < avg_res {
            score -= 12.0 * (avg_res - post_residual as f64) / bin_capacity as f64;
        } else {
            score += 8.0 * (post_residual as f64 - avg_res) / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Early in the stream, opening bins is cheaper (build a portfolio of bins)
        score -= (1.0 - progress) * 30.0;
        // If many bins can fit, discourage opening a new one
        score += fitting_bins_count as f64 * 10.0;
        // If next item is large, a fresh bin is more valuable
        score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Late-stream urgency: close out bins rather than spreading items
    score += progress * 10.0;

    // Slight preference for bins with larger residuals when fits are equal
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late, punish wasted residual strongly.
    let coupling = pr_norm * pr_norm * (0.5 + 2.5 * progress * progress);
    score += 40.0 * coupling;

    // Reward large item fill fraction, smoothed polynomial in item size.
    score -= 30.0 * item_norm * item_norm * (1.0 - progress * 0.5);

    // Penalize leaving residual close to but not exactly matching next item (dead space).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 15.0 * gap_norm * (1.0 - gap_norm) * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: neutral baseline scaled by open bins and mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 5.0 * open_bins_count as f64 * (0.3 + 0.7 * progress)
            - mean_residual * (1.0 - progress);
    }

    // Small smooth tie-breaker toward fuller bins relative to mean residual.
    score -= 0.05 * (mean_residual - pr) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does it fall into?
    // Bands of 10 (item sizes are multiples-ish of 10 in classic streams).
    let band = post_residual / 10;
    let exact_fit = post_residual == 0;
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;

    // Reward exact closure strongly.
    if exact_fit {
        score -= 60.0;
    } else if next_fits {
        // If the lookahead also fits, this bin chains nicely.
        let slack_after_next = post_residual - next_item_size;
        score -= 8.0 + slack_after_next as f64 * 0.5;
    } else {
        // Dead space: post_residual too small for the next item.
        // Penalize proportionally to how wasted it is, scaled by band.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste * (1.0 + band as f64 * 0.15);
    }

    // Harmonic / modulo structure on post_residual: residuals that are
    // "nice" multiples of common item sizes are more reusable.
    let reusable = (post_residual % 10 == 0 && post_residual >= 20)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable {
        score -= 6.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Tiny unusable sliver.
        score += 15.0;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 25; // 0..4
    score += match class {
        0 => 12.0, // 0-24: nearly dead unless exact
        1 => 4.0,  // 25-49: marginal
        2 => -2.0, // 50-74: good
        _ => -5.0, // 75+: very reusable
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless open bins are congested
    // (low mean residual) or this is a big item late in the stream.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * congestion - 15.0 * big_item * (0.5 + progress);
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            // next item won't fit in the remainder of a fresh bin either; mild bonus
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Early stream: be conservative, keep bins open; late stream: close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest plausible item
    // and cannot even fit the lookahead item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(bin_capacity)) {
        // gap smaller than next item (or tiny in general) -> dead space
        score += 25.0 + (bin_capacity as f64 - post_residual as f64) * 0.1;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item either -> likely dead space
        score += 12.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0;
    } else {
        // perfect fill: strong reward
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing them
    // (avoid opening new bins); when few bins are open, new-bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 2.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make the empty bin mildly unattractive unless the
    // current bin would leave a large dead gap.
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.05;
    }

    // Slight preference for bins with residual close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 120.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 5.0;
        } else {
            // Penalize residuals that are awkward relative to the lookahead item.
            score += diff * 0.6;
        }
        // Bonus if placing here AND the next item also fits afterwards (chain fit).
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste, slight reward for tight fit.
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (unless it would leave huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual > 40 {
            score += 15.0; // but not if it creates a big unusable hole
        }
    }

    // Penalize very large post-residuals (wasted capacity), nonlinearly.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.8;
    }

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Early in the stream, be slightly more willing to keep bins tight;
    // late in the stream, prefer closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Many open bins: mild pressure to fill existing ones rather than spread.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);

    // Reward near-perfect fills strongly (waste-driven core)
    score -= 40.0 * (1.0 - tight_fit).powi(3);

    // Penalize unusable dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item can pair into the post-residual (perfect chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64) / 50.0);
        } else {
            // next item cannot use leftover: mild penalty scaled by leftover size
            score += 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer fullest bins (best-fit flavor) among many open bins
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Global pressure: when many bins are open relative to progress, conserve; when few, pack tight
    let pressure = open_bins_count as f64 / (1.0 + t * total_items as f64 / 10.0);
    score += 0.05 * pressure * post_residual as f64;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good home
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev.max(0.0);

    // New-bin candidate control: default slight penalty so we prefer reusing bins,
    // but drop the penalty when the item fits badly everywhere (large post_residual elsewhere)
    if is_new_bin {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheap and preserves flexibility
        if t < 0.2 {
            score -= 8.0;
        }
    }

    // Small time-horizon modulation: late in stream, squeeze hard
    score -= 5.0 * t * (1.0 - tight_fit);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit).
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    let progress_coupling = tightness * tightness * (0.5 + progress);
    score -= 18.0 * progress_coupling * (item / cap);

    // Penalize residual that is unusable for the lookahead item (dead space), smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        // Smoothly penalize leaving residual just below the next item's size.
        let gap = (nx - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * (1.0 - fits_next) * (0.4 + 0.6 * progress);
        // Reward leaving residual that exactly accommodates the next item.
        score -= 8.0 * fits_next * (1.0 - (pr - nx).abs() / cap) * (pr - nx).abs() / cap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty scaling with number of open bins to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (pr / cap);

    // Discard bins whose residual is far from mean residual (fragmentation), smooth quadratic.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: neutral baseline with slight early-stream openness, late-stream resistance.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "friendly"
    // to common item sizes (multiples of 10, and small values) are valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Class A: residual divisible by 10 -> pairs well with typical sizes
    if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Class B: harmonic thresholds via integer division
    // post_residual < 10 is dead space for the stated size range
    if pr < 10 && pr > 0 {
        score += 25.0;
    }
    // residual in [10, 20) : can host only tiny items
    if pr >= 10 && pr < 20 {
        score += 6.0;
    }
    // residual >= 50 : still very usable, keep it but don't hoard
    if pr >= 50 {
        score -= 8.0;
    }

    // Coupling with lookahead: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item also fits here -> strong chaining reward
            score -= 20.0;
            // exact chain: post_residual == next_item_size
            if next_item_size == pr {
                score -= 30.0;
            }
            // harmonic match: next item and current item tile the bin nicely
            if (item_size + next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit after this placement
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 10.0 * open_bins_count as f64;
        // early in stream: opening bins is cheap
        score -= 30.0 * (1.0 - progress);
        // if item leaves a harmonic-friendly residual in a fresh bin, mild bonus
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 5.0;
        }
        // crowded state: discourage opening more bins
        score += 8.0 * open_bins_count as f64 * progress;
    }

    // Prefer bins tighter than average (waste-avoidance)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins overall
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual < 10 {
        // Perfectly full or near-full bins are ideal -> strong reward.
        score -= 60.0;
    } else {
        // Usable gap: reward proportionally to how well it can host future items.
        score -= 5.0;
        // If the lookahead item fits exactly in the post residual, big reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            // Lookahead cannot use this gap: penalize proportionally to waste.
            score += (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Reward tight fits (small post_residual relative to capacity) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize leaving gaps that no future item (10..100) can reasonably use:
    // gaps in [1, 9] are dead; gaps slightly above small items are fine.
    if post_residual >= 1 && post_residual <= 9 {
        score += 50.0; // dead space penalty (beyond the -60 reward, net strongly positive)
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far below mean residual wastes capacity.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when no open bin
    // offers a good fit (all fits are poor). Give it a mild bonus so it wins
    // when open-bin scores are inflated by dead-space penalties.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // But if the item is large and would leave a small unusable gap, discourage.
        if post_residual < 10 {
            score += 45.0;
        }
        // If many bins already fit the item, prefer reusing one.
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Slight progression-aware nudge: early in the stream, keep bins open
    // (favor reuse); late, prefer closing bins out tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already rewarded by base).

    // 2-step lookahead: strong reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> big bonus.
        if gap == 0.0 {
            score -= 45.0;
        } else {
            // Penalize post_residuals that the next item cannot use efficiently.
            score += gap * 0.35;
        }
        // Extra reward if next item fits exactly and this bin's fit was also decent.
        if gap == 0.0 && post_residual + item_size <= bin_capacity {
            score -= 10.0;
        }
        // If next item would fit into post_residual, mildly reward leaving usable space.
        if next_item_size <= post_residual && gap > 0.0 {
            score -= 6.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "almost full";
    // filling them is good (fewer wasted partial bins).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        // post_residual below mean: this bin is tighter than average -> reward closing it out.
        score -= dev * 0.25;
    } else {
        // post_residual above mean: leaves a loose bin; slight penalty scaled by deviation.
        score += (-dev) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity - item_size.
    // Make the new-bin option expensive unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Discount if open bins are fragmented (high mean residual but poor fits):
        // if mean residual is large and this is a large item, a fresh bin may be better.
        let frag = mean_residual - item_size as f64;
        if frag > 20.0 {
            score -= (frag - 20.0).min(40.0) * 1.2;
        }
        // Early in stream, opening bins is cheaper (build diversity of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, so subtract a bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 {
        let waste_threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < waste_threshold {
            score -= 8.0; // residual too small for lookahead item: dead space
        } else {
            // residual usable by next item: reward
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        // New bin has perfect residual (bin_capacity - item_size); encourage when
        // existing bins fit poorly (post_residual large relative to capacity).
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit {
            score -= 12.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - fit_ratio);
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Many open bins: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual is near the mean (keep spread balanced).
    let bin_res_f = bin_residual as f64;
    let dev = (bin_res_f - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling fuller bins (smaller residual before placement).
    score += 0.1 * bin_res_f / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: penalize mid-range residuals more as stream progresses
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0; // hump-shaped, peaks at norm_pr=2/3
    score += progress * poly * 30.0;

    // Reward tight fits increasingly over time
    score -= progress * (1.0 - norm_pr) * (1.0 - norm_pr) * 40.0;

    // Dead-space penalty for large residuals when few fitting bins exist
    let scarcity = 1.0 / fitting_bins_count as f64;
    score += scarcity * norm_pr * norm_pr * 20.0;

    // Lookahead: if next item fits post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 10.0 * (1.0 - (next_item_size as f64 / pr).min(1.0));
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Mean residual coupling: penalize bins far from the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 15.0;

    // Slight penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 2.0 + open_bins_count as f64 * 0.5;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    // Classes: 0 (perfect/<=5), 1 (tiny <=10), 2 (small <=20), 3 (medium <=35), 4 (large <=50), 5 (huge >50)
    let class = if post_residual <= 5 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 35 { 3 }
        else if post_residual <= 50 { 4 }
        else { 5 };
    score -= match class {
        0 => 60.0,
        1 => 40.0,
        2 => 22.0,
        3 => 8.0,
        4 => 0.0,
        _ => -6.0, // huge leftover is actually good (still reusable)
    };

    // Exact-fill bonus via modulo: post_residual divisible by common item sizes (10/20/25/50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    } else {
        score -= 70.0; // perfect closure
    }

    // Dead-space penalty: residual too small for the smallest plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; penalize wasting a reusable bin
            score += 5.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it attractive only when current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // fresh bin: neutral baseline, slightly penalized so tight fits win
        score = 55.0 + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pair large items into fresh bins
        }
    }

    // Late-stream consolidation: as stream progresses, prefer closing bins with small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 10 {
        score -= 10.0 * progress;
    }

    // Prefer filling bins whose residual is below the mean (tight bins)
    score -= 3.0 * (mean_residual - post_residual as f64).max(0.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A post_residual gap is "dead" if it cannot hold even the smallest plausible
    // future item (use 10 as the minimum gap threshold; 0 is perfect).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space, worst outcome
        } else if post_residual < 20 {
            score += 25.0; // near-dead, only tiny items can use it
        } else if post_residual < 30 {
            score += 8.0;  // marginal usability
        } else {
            // Usable gap: mild reward proportional to how well future items fit
            score -= 5.0;
        }
    } else {
        score -= 40.0; // perfect fill strongly preferred
    }

    // Bonus for gaps that can accommodate the lookahead item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack.min(40.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // gap cannot fit the next item: it will likely become dead space
        score += 10.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately expensive so we only open when
    // existing fits are truly poor (dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
    } else {
        // Tight fit reward: filling a bin nearly exactly
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 20.0;
        } else if fill_ratio > 0.7 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // consolidating into them rather than leaving many large residuals.
    if bin_residual != bin_capacity && (mean_residual - post_residual as f64) > 0.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Proximity reward: closer post_residual to next item is better
            score -= 40.0 / (1.0 + diff / 10.0);
        }
        // Penalize if next item cannot fit in the residual (dead space for next step)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize small post_residual (unusable dead space), scaled by item size
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize slightly unless residual is very small
        score += 5.0 + 5.0 * progress;
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Prefer bins with less residual among equals (tighter packing)
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals that can never host typical items.
    if post_residual < 10 {
        score -= 6.0; // near-perfect closure is excellent
    } else if post_residual <= 25 {
        score -= 2.0 * (25.0 - post_residual as f64) / 15.0;
    } else if post_residual > 50 {
        score += 0.05 * (post_residual as f64 - 50.0); // large useless gap
    }

    // Lookahead: check if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: this placement enables the next item here.
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * chain_tightness;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 0.3;
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Empty bin gets a baseline cost that grows
    // with the number of open bins (consolidation pressure) and shrinks
    // late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 0.4 * open_bins_count as f64 - 3.0 * progress;
        // If next item is huge, a fresh bin may be strategic.
        if next_item_size > 70 {
            score -= 6.0;
        }
    }

    // Global state coupling: when mean residual is large, prefer bins that
    // reduce fragmentation (below-average residual targets).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 0.5;
        }
    }

    // Early stream: slightly favor opening bins to build a diverse pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 && bin_residual < bin_capacity {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, non-linearly coupled with stream progress:
    // late in the stream, small residuals become more valuable (tighter packing).
    let pr_norm = pr / cap;
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= t * (1.0 - pr_norm) * (1.0 - pr_norm) * 12.0;

    // Penalize large dead space super-linearly, weighted by progress.
    score += t * pr_norm * pr_norm * 15.0;

    // Reward bins whose residual matches the next item (lookahead fit).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let match_q = 1.0 / (1.0 + diff * diff / 50.0);
        score -= match_q * (4.0 + 6.0 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 10.0 * progress;
    }

    // Slight pressure to prefer fuller bins relative to the fleet mean.
    score += (pr - mean_residual) * (0.3 + 0.4 * progress);

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward residuals that are exact multiples of small harmonic units (10, 20, 25, 50)
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Penalize awkward residues in 1..10 range (dead space)
        if pr < 10 { score += 12.0; }
    } else {
        score -= 10.0; // perfect fit
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // 0..10 capacity-fraction decile
    match class {
        0 => score += 8.0,          // tiny leftover: nearly wasted bin
        1 => score += 2.0,
        2 | 3 => score -= 2.0,      // sweet spot: fits mid-size items
        4 | 5 => score -= 4.0,
        6 | 7 => score -= 1.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits the post residual exactly or harmonically, reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 8.0; // next item tiles the remainder perfectly
            } else {
                score -= 2.0;
            }
        } else {
            score += 3.0; // next item won't fit here; residual likely stranded
        }
        // penalize when next item nearly fits but leaves sliver
        if next_item_size > pr && next_item_size - pr <= 5 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline modulated by state
    if bin_residual == bin_capacity {
        score = 100.0
            - 4.0 * (open_bins_count as f64).ln().max(0.0)
            + 20.0 * progress
            - (mean_residual / bin_capacity as f64) * 10.0;
        // open a new bin if existing bins are crowded
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
    }

    // Mild tie-break toward fuller bins
    score -= (bin_residual as f64 / bin_capacity as f64) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A tiny leftover gap (below the smallest plausible item) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver: heavy penalty
    } else if post_residual < 25 {
        // small-but-maybe-usable gap: moderate nonlinear penalty
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit reward: subtract strongly for exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 15 {
        score -= 20.0; // near-perfect fit still attractive
    }

    // --- Open-bins pressure ---
    // With many open bins, strongly prefer filling an existing bin over
    // leaving it idle; scale the fit reward by bin count.
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * bin_pressure;
    } else {
        // New-bin candidate: base cost plus pressure so it only wins when
        // existing fits are genuinely bad.
        score += 25.0 + 6.0 * bin_pressure;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // --- Last-chance bin: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item would fit into the post residual, this placement
    // chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits the leftover, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size / 2 {
        score -= 4.0;
    }

    // --- Mean residual coupling ---
    // If this bin's residual is far below the mean, it is an outlier bin
    // worth topping up (its space is least useful elsewhere).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.1;
    }

    // Prefer the tightest fit among candidates: smaller item-to-residual waste.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step match: huge reward
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post residual: moderate reward, scaled by tightness
        else if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Next item cannot fit: penalize wasted residual relative to next item
        else {
            score += 15.0 + (nxt - post);
        }

        // Chain bonus: residual also matches item+next exactly (perfect pair)
        if post_residual == next_item_size && post_residual as f64 <= mean_residual {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins with residual near/below mean
    // (concentrate filling in fuller bins, keep large-residual bins flexible)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless residual situation is bad
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few bins fit or lookahead mismatch is severe
        let pressure = if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 { 0.0 } else { 30.0 };
        score += 35.0 - pressure - 2.0 * open_bins_count as f64;
    }

    // Mild stream-progression discount: later in stream, prefer consolidating
    if total_items > 0 {
        score -= 5.0 * (step_index as f64 / total_items as f64) * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Exact-fit jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.05 * next_item_size as f64;
        } else {
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Relative fit within the bin: prefer filling larger fraction of residual.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill_frac;

    // Time horizon: early in the stream, be conservative (favor new bins less waste);
    // late in the stream, pack aggressively into open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins as stream progresses,
        // and when many bins are open.
        score += 5.0 + 25.0 * t + 1.5 * open_bins_count as f64;
        // But reward opening a new bin when mean residual is large (bad fits everywhere).
        score -= 0.05 * mean_residual;
    } else {
        // Existing bin: late-stream aggression.
        score -= 8.0 * t;
        // Slight penalty if this bin's residual is far from the mean (imbalance).
        score += 0.03 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild congestion bonus: with many open bins, prefer existing bins.
    score -= 0.2 * open_bins_count as f64 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear penalty on residual, amplified as stream progresses.
    let norm_pr = pr / cap;
    score += 2.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits (small residual) with a saturating non-linear term.
    let tight = (-norm_pr * 6.0).exp();
    score -= 8.0 * tight * (0.4 + 0.6 * progress);

    // Lookahead coupling: bonus if next item fits the post-residual well.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs() as f64;
        let fit_quality = (-gap / 20.0).exp();
        score -= 6.0 * fit_quality * (0.5 + progress);
        // Penalize residual that is too small to ever be useful for next item.
        if pr < ns {
            score += 3.0 * (1.0 - pr / ns.max(1.0) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // Penalize scarce fitting options mildly (competition among bins).
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    let dev = (mean_residual - pr) / cap;
    score -= 4.0 * dev * (0.3 + 0.7 * progress);

    // New-bin candidate: encourage opening a new bin early, discourage late,
    // and only when residual of this bin would be wasteful.
    if bin_residual == bin_capacity {
        let waste = norm_pr; // = 1.0 for empty bin, so use item size instead
        let _ = waste;
        let fill = item_size as f64 / cap;
        score = cap * (1.0 - fill) + 10.0 * progress * cap - 5.0 * (1.0 - progress) * cap;
        if fitting_bins_count <= 1 {
            score -= 15.0; // no good alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/8 granularity). Small post_residual classes
    // are highly usable dead space -> reward (subtract).
    let eighth = bin_capacity as f64 / 8.0;
    let pr = post_residual as f64;
    let class = (pr / eighth).floor().min(7.0); // 0..7 harmonic class

    // Class-based reward: lower classes (tighter fits) get bigger discounts.
    score -= (8.0 - class) * 3.0;

    // Perfect-fit bonus: residual exactly 0, or matching a harmonic divisor.
    if post_residual == 0 {
        score -= 60.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
        score -= 15.0; // residual splits capacity evenly -> reusable
    }

    // Small residuals that are dead space: penalize if below typical small item size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / eighth.max(1.0)).max(0.0);
        } else {
            // next item cannot use this bin's leftover; penalize proportional to waste
            score += 0.15 * pr;
        }
    }

    // Last-chance logic: only this bin fits -> reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-slightly-high unless current bins are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Progress-based mild pressure: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer filling bins that are already relatively full (small residual vs mean).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Integer-division threshold: post_residual in upper half of capacity is wasteful.
    if post_residual > bin_capacity / 2 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are fine,
    // but gaps in the "unusable band" (1..=9 for typical min sizes, keep generic) are wasted.
    // Penalize gaps that no realistic future item can use (very small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64; // worst for gap of 1
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many alternatives: slight penalty so best-fit competition dominates.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(8.0);
    }

    // Open-bins pressure: when many bins are open, discourage spreading; prefer filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, reduced if open bins are nearly full / few fit.
        let mut nb = 25.0 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            nb -= 60.0; // no open bin fits: must open
        }
        // If lookahead item is large and this item is small, opening may waste capacity.
        if next_item_size > 0 {
            let wasted = (bin_capacity - item_size) as f64;
            if wasted < next_item_size as f64 {
                nb -= 20.0; // residual would be unusable for next item anyway
            } else {
                nb += 8.0 * (wasted / 100.0);
            }
        }
        score += nb;
    }

    // Slight reward for bins whose residual is far below mean (already well-packed).
    score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead space penalty is super-linear (waste granularity matters).
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item size (chained perfect fits).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits exactly or near-exactly: big reward.
            score -= 40.0 / (1.0 + gap);
        } else {
            // Next item would not fit here: mild penalty proportional to overflow.
            score += 0.15 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post-residual stays close to
    // the mean residual (keeps the bin population homogeneous and reusable).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a valuable resource.
    // Penalize it so it is only chosen when open bins fit badly,
    // but soften the penalty late in the stream when waste matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
        // If the next item fits perfectly in a fresh bin, opening is attractive.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 50.0;
        }
    }

    // Slight preference to fill fuller bins first (best-fit flavor),
    // scaled by how many bins are competing.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill * (1.0 + open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Penalize large dead space proportionally to how much of the bin it wastes.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 120.0;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Prefer tighter fits among many candidates.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Global state: many open bins with high mean residual -> prefer using
    // existing bins over opening new ones.
    if open_bins_count > 2 && mean_residual > 0.0 {
        score -= 15.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be conservative (slightly favor new
    // bins when fits are poor); late in the stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 50.0 * progress * tightness;
    score += 30.0 * (1.0 - progress) * waste_ratio;

    // New-bin candidate shaping: empty bin has no tightness advantage; make it
    // attractive only when the item is large relative to capacity and no
    // obvious good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, non-linearly shaped by stream progress.
    let x = pr / cap;
    let t = progress;

    // Polynomial coupling: residual cost grows super-linearly as the stream progresses,
    // since late-stage dead space is harder to fill.
    let poly = x * (1.0 + 2.0 * t) - 1.5 * t * x * x + 0.5 * t * t * x * x * x;

    let mut score = pr * (1.0 + poly);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (cap - pr) * 0.3 * (1.0 + t);

    // Penalize leaving residual that is just below the next item (wasted potential),
    // with a smooth quadratic interaction with progress.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        if pr < next_item_size as f64 {
            score += 8.0 * (1.0 - t) * (next_item_size as f64 - pr) / cap;
        } else {
            score += 2.0 * t * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + t);
    }

    // Mild penalty for opening a new bin when many bins are open with slack.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 + 5.0 * t;
        // But if mean residual is large, new bin is less bad.
        score -= mean_residual / cap * 2.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidation of slack),
    // smoothly weighted by progress.
    score += 0.5 * t * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Tight-fit reward: cubic decay of residual fraction
    score -= 10.0 * (1.0 - pr / cap).powi(3) * cap;

    // Harmonic class penalty: residual modulo classes (dead-space taxonomy)
    let cls = post_residual % 10;
    score += cls as f64 * 0.6;

    // Integer-division threshold: residuals in [1,9] are nearly worthless
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }
    // Sweet-spot classes: residuals 25..=50 can host mid-size future items
    if post_residual >= 25 && post_residual <= 50 {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0;
            // extra reward if next item nearly fills the leftover exactly
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 5.0;
            }
        } else {
            score += 8.0; // stranded residual vs known next item
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 6.0 + 0.04 * mean_residual;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 3.0; // fresh bin keeps room for the big next item
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open first bin
        }
    }

    // Mild preference for already-busy bins (consolidation)
    score += 0.015 * bin_residual as f64;

    // Stream-phase modulation of class thresholds
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 2.0 * ((post_residual % 25) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals below the minimum item size (1..=100 unknown, assume small threshold)
    // are "dead space": penalize super-linearly as they approach unusability.
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
    score -= (1.0 - fit_ratio) * 6.0;

    // --- Open bins pressure: discourage proliferation of open bins ---
    score += open_bins_count as f64 * 1.5;

    // --- Last-chance bonus: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Lookahead: if the next item fits the post-residual, reward leaving that gap ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < dead_threshold {
        score += 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early on, but costly once many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // If existing bins fit poorly (high mean residual wasted anyway), new bin is attractive.
        if mean_residual > 30.0 {
            score -= 15.0;
        }
        // If no other bin fits, this call is the fallback: make it reasonable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // --- Mean residual coupling: prefer bins whose residual is below average (tighter bins) ---
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 200.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover space; penalize proportionally
        score += 0.3 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Penalize creating dead space relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 120.0;
        if post_residual as f64 > mean_residual + 0.5 * item_size as f64 {
            score -= 60.0; // fresh bin is attractive when open bins are fragmented
        }
    }

    // Slight preference for tighter bins overall
    score += 0.2 * (bin_capacity - bin_residual) as f64 * -0.1;

    // Early stream: be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste-minimization core).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Dead-space penalty: small residuals that few items can use are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
            // Bonus proportional to how snugly the next item nests.
            let slack = post_residual - next_item_size;
            score -= (10.0 - slack.min(10) as f64) * 2.0;
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += (gap.min(40) as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are bad.
    if bin_residual == bin_capacity {
        // Neutral baseline; penalize mildly so tight fits in existing bins win.
        score += 15.0;
        // Early in the stream, opening bins is cheap and useful for flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If many open bins are nearly full, a fresh bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Prefer fuller bins: residual before placement relative to capacity.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 50.0 * fill_ratio;

    // Global state coupling: when many bins are open, tighten packing;
    // when few are open, allow more spread.
    let openness = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * openness;

    // Mean-residual anchoring: bins deviating far above mean residual are
    // less attractive targets (keep homogeneous residual pool).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0);

    // Late-stream pressure: as the stream ends, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fill_ratio;

    // Avoid wasting a huge bin on a tiny item when better options exist.
    if item_size < 20 && bin_residual > 80 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are tolerable; late, they become costly.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Smooth cubic interaction: large residuals penalized increasingly over time.
    score += 8.0 * progress * pr_norm * pr_norm * pr_norm * cap;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition scaling: more alternatives -> slightly less urgency.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Penalize creating residual too small for the lookahead item.
            score += 4.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Prefer bins below mean residual (tighter bins) with smooth coupling.
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate handling: an empty bin has large post_residual; the
    // progress-coupled terms already penalize it, but add a smooth barrier
    // that weakens late in the stream (opening new bins late is wasteful).
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Integer division thresholds: residuals partitioned into harmonic bands
        let band = pr / 10; // 0..=9 harmonic class
        // Dead space penalty grows super-linearly for small unusable residuals
        if pr < 10 {
            score += 40.0; // nearly unusable sliver
        } else if pr <= 20 {
            score += 5.0;
        } else {
            // larger residuals are more reusable; mild discount per band
            score -= band as f64 * 2.0;
        }
        // Modulo-arithmetic coupling: residuals that are multiples of common item
        // sizes (10, 20, 25, 50) are "harmonic" and more likely to be reused.
        let harmonic = (pr % 10 == 0) as i32 + (pr % 20 == 0) as i32
            + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
        score -= harmonic as f64 * 6.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 30.0 + 0.3 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to mismatch
        score += 0.15 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // and the current item is large (would leave a fragmented residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count == 0
            || (item_size as f64 > 0.5 * bin_capacity as f64 && mean_residual < item_size as f64 * 1.2);
        if poor_fits || (large_item && crowded > 3.0) {
            score -= 150.0 + 20.0 * progress;
        } else {
            score += 250.0; // prefer existing bins otherwise
        }
    }

    // Mild preference for tightest existing bins via mean residual contrast
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // (small gaps) are heavily penalized with a non-linear blow-up.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        let depth = dead_threshold - post_residual as f64;
        score += 40.0 + depth * 8.0; // unusable sliver penalty
    }

    // Reward tight fits (post_residual near zero but still "perfect-ish").
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 20.0; // highly reusable gap (items >= 10 exist)
    }

    // Reward bins whose residual becomes exactly next_item_size (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0; // keeps future options alive
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // but if the fit leaves a big dead gap, soften the discount
        if post_residual > 50 {
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: penalize mildly unless open bins are scarce or fit is awful.
        score += 8.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 {
            let best_possible_gap = post_residual.min(10) as f64;
            // if some open bin achieves near-perfect fit, discourage new bin
            score += 12.0 - best_possible_gap;
        }
    }

    // Mean-residual coupling: bins far below mean residual are better targets
    // (they absorb space where slack is abundant), bins above mean are risky.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Mild reward for using bins with large residual early (first-fit-like),
    // stronger late in the stream when closing bins matters.
    if bin_residual < bin_capacity {
        score -= (bin_residual as f64) * 0.05 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item also fits into the
    // post residual, this placement chains nicely -> reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= 60.0 - chain_waste as f64 * 1.5;
        // Perfect two-item chain (bin fully consumed by item + next item)
        if chain_waste == 0 {
            score -= 400.0;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit here after placement: the leftover space
        // is likely dead unless tiny. Penalize proportionally.
        score += (post_residual as f64) * 0.8;
        // Especially bad if leftover is large but too small for the next item.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "tight"; using them further is efficient.
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
        if post_residual <= 10 {
            score -= 100.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer keeping items in open bins; only allow the new bin when the
    // item is huge relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Large items (>= 60) open bins early so future small items can fill.
        if item_size >= 60 {
            score -= 40.0;
        }
        // If many open bins exist with big mean residual, opening new bins
        // is wasteful.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score += 60.0;
        }
    }

    // Early-stream: encourage moderate fragmentation tolerance early,
    // tightness later (residuals harder to fill as stream ends).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post-residuals non-linearly.
    if post_residual > 0 {
        score -= 8.0 / post_residual as f64;
    } else {
        score -= 12.0; // perfect fit bonus
    }

    // Penalize large dead space relative to capacity (waste).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item nearly fits (small gap), slight bonus for chain packing.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 3.0; // dead space too small to be useful, but blocks next item
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If no other bin fits well (this is the only fitting bin), opening new is fine.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins that will end mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // If mean residual across open bins is high, reusing open bins is easy.
        if mean_residual > item_size as f64 + 5.0 {
            score += 8.0;
        }
    }

    // Slight preference for bins with residuals closest to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, softly normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate larger residuals less harshly; late, demand tight fits.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 0.35 * (1.0 - progress) * (pr / cap) * (pr / cap)
           - 0.15 * p2 * (pr / cap)
           + 0.10 * p3 * (pr / cap).sin();

    // Reward near-perfect fits smoothly (quadratic trough at pr == 0)
    score -= 0.6 * (-pr / 12.0) * (-pr / 12.0) * (1.0 - progress);

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n > pr {
            score += 0.25 * ((n - pr) / cap) * (1.0 + progress);
        } else {
            // smooth reward for leaving room usable by next item
            score -= 0.20 * (1.0 - (pr - n) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * (1.0 + 0.5 * progress);
    }

    // Mean-residual context: when open bins are generally loose, mildly prefer tightening them
    score += 0.05 * (mean_residual / cap) * (pr / cap) * open_bins_count as f64;

    // New-bin candidate baseline: keep it slightly unattractive unless residuals are hopeless
    if bin_residual == bin_capacity {
        score += 0.4 + 0.3 * (1.0 - progress) - 0.2 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near 0 are "perfect" fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit -> massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space is bad (wasted slivers): penalize residues 1..=5.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    }

    // Harmonic class via integer division: classify residual into capacity deciles.
    let decile = post_residual / 10; // 0..=10
    let decile_penalty = match decile {
        0 => 0.0,          // near-perfect fit region
        1 => 8.0,          // 10-19 residual: mostly dead space for big items
        2 => 2.0,          // 20-29: can host small items
        3 => 5.0,
        4 => 1.0,          // 40-49: hosts mid items
        5 => 3.0,
        6 => 0.5,          // 60-69: versatile
        7 => 2.5,
        8 => 0.0,          // 80-89: hosts most small items
        _ => 0.0,
    };
    score += decile_penalty;

    // Modulo harmonic: residuals that are multiples of common item sizes are reusable.
    let reusable = (post_residual % 10 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // How tightly the next item fits: leftover after next placement.
            let post2 = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (post2 as f64) / cap);
            if post2 <= 5 {
                score -= 15.0; // chain of near-perfect fits
            }
        } else {
            // Next item won't fit here: penalize leaving large residuals anyway.
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // (avoid opening a new bin) unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin starts with a mild opening cost so we
    // only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if next item is huge and this item is small, a fresh bin is fine.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 30.0;
        }
    }

    // Prefer filling bins whose residual is far below the mean (tight packing pressure).
    score -= 0.3 * (mean_residual - pr).max(0.0);

    // Slight preference for bins that are already well used.
    let used_frac = (bin_capacity.saturating_sub(bin_residual)) as f64 / cap;
    score -= 10.0 * used_frac;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += 0.02 * (open_bins_count as f64) * pr * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // mid gaps (10..30) moderately penalized since fewer item sizes can use them.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // dead space, item wasted
    } else if post_residual < 30 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits: post_residual close to 0 relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Lookahead: if the next item can use the post-residual gap, reward leaving it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // gap likely unusable by next item
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a poor
    // consolidation target; if above mean, it's roomy and attractive.
    let bin_residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.15 * (bin_residual_f - mean_residual);
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins would leave large dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and open bins.
        score += 45.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        if item_size >= 90 {
            score -= 30.0; // huge items: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (next_leftover as f64) / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize leaving awkward small residuals.
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.3 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless residuals
    // across open bins are large (poor global fit landscape).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let base_penalty = 25.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln().max(1.0) * 10.0
        };
        // If mean residual is small, open bins are already tight -> new bin ok.
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += base_penalty + scarcity_bonus - 20.0 * mean_tight;
        // Early in the stream, allow new bins more freely.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (bin-count pressure): prefer consolidating.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual close to item size (minimal waste ratio).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += 10.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its polynomial couplings with stream progress
    let p = post / cap_f;
    let p2 = p * p;
    let p3 = p2 * p;

    // Base: wasted space, slightly discounted as stream progresses
    let mut score = post * (0.9 + 0.2 * progress);

    // Non-linear dead-space penalty: small residuals are increasingly bad
    score += cap_f * (p2 * (1.5 - progress) - p3 * (0.8 + 0.6 * progress));

    // Tight fits rewarded more strongly later in the stream
    let tightness = (item_size as f64) / cap_f;
    score -= tightness * cap_f * (0.5 + 0.9 * progress);

    // Lookahead: reward leaving space exactly matching next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_err = (post - nx) / cap_f;
        score -= cap_f * (-match_err * match_err) * (1.2 - 0.5 * progress);
        score += match_err.abs() * cap_f * 0.4;
    }

    // Last-chance bin before opening a new one: strong pull
    if fitting_bins_count == 1 {
        score -= cap_f * (0.6 + 0.8 * progress);
    }

    // Prefer bins whose residual deviates from the mean (consolidate slack)
    let dev = (post - mean_residual) / cap_f;
    score += dev * dev * cap_f * (0.3 + 0.5 * progress);

    // Mild penalty for spreading across many open bins early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: penalize opening unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        let fragment = (post / cap_f) * (post / cap_f);
        score += cap_f * (1.5 - 1.2 * fragment) * (0.4 + 0.6 * progress);
        if fitting_bins_count <= 1 {
            score -= cap_f * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class logic: classify post_residual into residue classes mod 10 ----
    // Residuals that are "wasted" (small, non-reusable dead space) get penalized.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows as residual shrinks below reusable threshold (next item min size ~1..10)
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0; // tiny unusable slivers are very bad
    } else {
        // Harmonic weighting: residuals divisible by 5 or 10 are "aligned" and reusable
        let alignment = if class == 0 { 0.0 } else if class == 5 { 1.5 } else { 3.0 };
        score += alignment;
    }

    // ---- Exact fit reward ----
    if pr == 0 {
        score -= 50.0;
    }

    // ---- Lookahead coupling: does next item fit in post_residual? ----
    if next_item_size > 0 && pr >= next_item_size {
        // Chain-friendly placement: reward proportional to leftover after next item
        score -= 15.0 + (pr - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize mildly, stronger if residual is small
        score += (next_item_size.saturating_sub(pr)) as f64 * 0.3;
    }

    // ---- Last-chance bin: if this is the only bin that fits, strongly prefer it ----
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few open bins fit, or stream is early,
        // or mean residual across open bins is high (existing bins are roomy anyway).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = bin_capacity as f64
            - 25.0 * (1.0 - progress)
            - (mean_residual / bin_capacity as f64) * 20.0
            - if fitting_bins_count <= 2 { 30.0 } else { 0.0 };
        // Harmonic class of item: large items (>=50) prefer fresh bins
        let bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        score = score.min(new_bin_score - bonus);
    }

    // ---- Congestion modulation: many open bins -> prefer tightening existing ones ----
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (or below next_item_size) are effectively unusable.
    if post_residual < item_size.min(10) {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * next_item_size as f64;
    }

    // Reward near-perfect fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure on number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when existing residuals are already fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (0.4 + 0.6 * (1.0 - progress));
    score += 0.35 * open_pressure;

    // If this bin's residual deviates badly from the mean, penalize.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: neutral baseline; open a new bin only if fits elsewhere
    // would leave large dead space.
    if bin_residual == bin_capacity {
        score -= 4.0 + 0.1 * mean_residual;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // pair fits nicely in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward leaving exactly next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // reward leftover big enough for next item, scaled by tightness of the match
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit in this residual: penalize proportionally to the shortfall
        let shortfall = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.5 * shortfall;
    }

    // Zero residual (perfect closure) is always excellent
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals below typical small-item size are hard to reuse
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins that are already tight (low residual)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, mildly prefer tighter fits (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: only attractive when no open bin gives a good fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual <= 20;
        if good_fit_exists {
            score += 30.0; // discourage opening new bin when a tight fit exists
        } else {
            score -= 5.0; // encourage fresh bin when fits are poor
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual (dead space grows superlinearly).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills remaining space
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving large but awkward residuals
            let gap = (next_item_size as f64 - post_residual as f64).abs();
            score += 0.08 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is penalized mildly so we prefer reusing
    // open bins with decent fits, but if all open-bin fits are terrible (large post_residual),
    // the quadratic dead-space penalty above makes the fresh bin competitive.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.02 * open_bins_count as f64;
    }

    // Global state: when mean residual across open bins is small (bins nearly full),
    // encourage opening fresh capacity instead of fragmenting scarce space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity && (mean_residual as u32) < item_size {
        score -= 4.0 * (1.0 - progress);
    }

    // Prefer filling bins with smaller residuals first (best-fit coupling).
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual, weighted by stream progress
    let norm_pr = pr / cap;
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Perfect fit bonus (smooth, near-zero residual)
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize leaving a residual that fits next item too loosely,
    // reward leaving residual that exactly accommodates next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score += 6.0 * (gap / cap) * (gap / cap);
            score -= 5.0 * (1.0 - gap / cap).max(0.0);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so existing bins preferred, but relax
    // penalty late in stream when many bins are open (avoid bin hoarding)
    if bin_residual == bin_capacity {
        let base = 10.0 + 8.0 * (1.0 - progress);
        let spread = (open_bins_count as f64).ln().max(0.0);
        score += base + 2.0 * spread;
    }

    // Mean-residual context: if this bin's residual deviates strongly below mean,
    // it's a scarce large gap -> discourage wasting it on a small item
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = resid / mean_residual;
        score += 4.0 * (ratio - 1.0) * (ratio - 1.0) * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "nice" fractions of capacity
    // (multiples of 10/20/25) are reusable by future items; odd tiny residuals are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class_bonus: f64 = if pr % 25 == 0 {
            45.0
        } else if pr % 20 == 0 {
            38.0
        } else if pr % 10 == 0 {
            30.0
        } else if pr % 5 == 0 {
            18.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead-space penalty: residuals too small for the smallest plausible item (1..100 unknown,
        // assume >= 10 typical) are nearly worthless.
        if pr < 10 {
            score += 55.0 * (1.0 - pr as f64 / 10.0);
        }

        // Lookahead coupling: reward residuals that can host the next item exactly or closely.
        if next_item_size > 0 && next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 25.0 - (slack as f64).min(25.0);
            if slack == 0 {
                score -= 15.0; // next item fits perfectly afterward
            }
        } else if next_item_size > 0 && next_item_size > pr {
            score += 8.0; // this bin dies for the next item
        }

        // Fractional residual ratio: prefer bins whose residual stays a "coarse" fraction.
        let ratio = pr as f64 / cap;
        if ratio < 0.1 {
            score += 20.0; // thin sliver
        } else if ratio >= 0.25 {
            score -= 10.0 * ratio; // roomy residual is valuable
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 70.0;
        // Early in stream, allow more new bins; late, discourage strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Prefer filling fuller bins (small residual before placement) when alternatives exist.
    if !is_new {
        score -= 12.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Mild penalty when many bins are open and this placement leaves mean residual far from ours.
    if open_bins_count > 3 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful future item are heavily penalized.
    let dead_threshold = 10.0; // smallest item class baseline
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else {
        // Prefer tight fits: nonlinear reward for small-but-usable gaps.
        let pr = post_residual as f64;
        score -= 25.0 * (-pr / 20.0).exp();
    }

    // Penalize leaving a gap that exactly fails to fit the lookahead item
    // (wasted potential), reward gaps that fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr < ni {
            score += 0.6 * (ni - pr);
        } else {
            score -= 0.4 * (1.0 - (pr - ni) / 40.0).abs();
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely tight; encourage closing out nearly-full bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (post_residual as f64);
    }

    // Slight stream-phase adaptation: later in the stream, be stricter
    // about wasting space (fewer chances to recover).
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 0.5 + 0.5 * progress;

    // Perfect match with the lookahead item: strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: mild reward scaled by how much slack remains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
        } else {
            // Next item won't fit: penalize proportionally to the shortfall, worse early.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall * (1.5 - progress);
        }
    }

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Compare against mean residual across open bins.
    if post_residual as f64 > mean_residual * 1.25 {
        score += 3.0; // leaving this bin much emptier than average is wasteful
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 3.0; // compacting this bin is good
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && next_item_size > post_residual && post_residual < 10 && fitting_bins_count <= 2;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly reward leaving usable space
            score -= 3.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward leftovers
            score += 4.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity - item_size
    // relative to a fresh placement; discourage opening a new bin unless the current
    // item is large and existing residuals are small.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 6.0;
        // but if item is large and mean residual can't help future items, allow it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.5 && pressure < 0.3 {
            score -= 10.0 * (1.0 - progress);
        }
        // late in the stream, prefer closing out existing bins
        if progress > 0.8 {
            score += 5.0;
        }
    }

    // Time horizon: early on, keep bins flexible (moderate residuals); late,
    // greedily fill bins as tightly as possible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very large post_residual when many bins are open (fragmentation).
    if open_bins_count > 4 && post_residual as f64 > mean_residual * 1.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr) + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling: waste matters more as the stream progresses
    score *= 1.0 + 0.5 * progress * progress;

    // Reward tight fits smoothly (low post residual relative to item)
    score -= 12.0 * (item / cap) * (1.0 - norm_pr).powi(3);

    // Lookahead: reward if next item can fit in post residual (smooth affinity)
    if next > 0.0 {
        let gap = (pr - next).abs();
        score += 0.15 * gap;
        if next <= pr {
            score -= 6.0 * (next / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open relative to stream progress
    score += 0.8 * (open_bins_count as f64) * (0.3 + 0.7 * progress) / (1.0 + (mean_residual / cap).max(0.0));

    // Discard new-bin candidate slightly unless current residual is small
    if bin_residual == bin_capacity {
        score += 4.0 + 30.0 * (item / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarter-class of the post residual (harmonic fractions of capacity).
    let quarter = (post_residual * 4 / bin_capacity) as f64;
    score += quarter * 3.0;

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item sizes; odd/prime residuals create dead space.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 2.0;
    }

    // Perfect-fit harmonic: residual exactly matches next item size.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Next item fits into post residual: strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual {
        // Next item won't fit; dead space penalty scaled by wasted capacity class.
        let waste_class = ((post_residual as f64) / 20.0).floor();
        score += waste_class * 2.5;
    }

    // Integer-division threshold: small post residual (< 1/8 capacity) is
    // essentially closed; reward sealing bins tightly.
    if post_residual < bin_capacity / 8 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // But if mean residual is small (open bins nearly full), new bin is fine.
        score -= (mean_residual / cap) * 10.0;
    }

    // Progress coupling: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // only fits smallest items
        } else if post_residual <= 30 {
            score += 8.0;
        } else {
            score -= 10.0; // roomy leftover is valuable
        }
    } else {
        score -= 40.0; // perfect fill: best possible outcome
    }

    // Reward tight fits (wasted fraction of the bin).
    score += (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 30.0; // open bins nearly full -> fresh bin is fine
        } else {
            score += 45.0 + pressure * 40.0; // keep using existing space
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving almost nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Two-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward two-item chains that keep residual small.
            score -= (next_item_size as f64) * 0.5;
            if next_post <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item cannot follow: penalize proportionally to wasted lookahead potential.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residuals that are too small to ever fit typical items (dead space),
    // but not when we already rewarded a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 250.0 - 200.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity && item_size + next_item_size == bin_capacity {
            score -= 400.0; // reserve fresh bin for a perfect pair
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
    }

    // Prefer bins with residuals below the mean (tighter bins get packed first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Early in the stream, be slightly more conservative with open bins
    // (plenty of stream left to exploit good fits later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward minimal post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize creating dead space it can't use.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + crowding * 2.0 - progress * 8.0;
        // If a fitting open bin exists with decent room, discourage new bin.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // If next item is huge relative to residual, a fresh bin may be fine.
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mild time-varying exploration pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    // Prefer bins whose residual deviates from mean (keep a spread of sizes).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post residual, with non-linear (quadratic) sharpening.
    let mut score = pr * (1.0 + pr / (2.0 * cap)) - it * 0.05;

    // Smooth progress coupling: later in the stream, waste is costlier.
    let progress_weight = 0.35 * progress * progress;
    score += progress_weight * pr;

    // Tight-fit bonus: non-linear reward when item fills a large fraction of residual.
    let fill = it / bin_residual.max(1) as f64;
    score -= 6.0 * fill * fill * (1.0 - progress * 0.5);

    // Lookahead synergy: reward if next item can use post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let synergy = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 4.0 * synergy * synergy;
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize dead space smoothly.
        score += 2.0 * (pr / cap) * (pr / cap);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Many open bins: discourage fragmenting space further unless fit is very tight.
    let ob = open_bins_count as f64;
    score += 0.4 * (ob.ln() + 1.0) * (pr / cap) * (1.0 - fill);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    // Brand-new empty bin candidate: only attractive when residuals are mostly unusable.
    if bin_residual == bin_capacity {
        let usable = (mean_residual / cap).max(0.0);
        score = 25.0 + 20.0 * (1.0 - progress) - 15.0 * usable * usable;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space (capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Class bins by which future item sizes could still use the leftover.
    // Items in [1,100]; a residual r is "usable" if next_item_size <= r.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward keeping residuals that remain "harmonically compatible"
    // with the lookahead item: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // sets up a perfect fit next step
        } else if post_residual >= next_item_size {
            // leftover can still host the next item: mild reward scaled by slack
            score -= (10.0 + 40.0 * (1.0 - (post_residual - next_item_size) as f64 / cap)) * (1.0 - progress);
        } else {
            // leftover too small for next item: penalize dead space
            score += 15.0 + 25.0 * frac;
        }
    }

    // Modulo / integer-division classes on post_residual:
    // residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are more likely reusable later.
    let reusable_class = (post_residual % 10 == 0) as i32
        + (post_residual % 20 == 0) as i32
        + (post_residual % 25 == 0) as i32
        + (post_residual % 50 == 0) as i32;
    score -= 8.0 * reusable_class as f64;

    // Penalize tiny unusable slivers (dead space < 10)
    if post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted early in the stream
        let open_cost = 120.0 * (0.5 + 0.5 * progress) + 5.0 * open_bins_count as f64;
        score += open_cost;
        // opening is good if the current placement would strand lots of space
        if post_residual < item_size / 2 {
            score -= 60.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 100.0; // perfect fit: strongly reward
    } else if post_residual <= item_size {
        score -= 15.0; // gap could still hold a similar item
    }

    // Penalize large-but-awkward leftovers relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.05 && frac < 0.25 {
        score += 20.0 * (0.25 - frac);
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But allow new bin if this item would leave big dead space everywhere.
        if post_residual as f64 > mean_residual * 0.5 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Prefer bins where the next item would also fit snugly
        score += lookahead_gap * 0.5;

        // Bonus if next item fits exactly into the post-residual
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize if next item cannot fit here (chain break risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize large dead space that small items cannot fill later
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable slivers
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // Only attractive if item is large relative to capacity or no good fit exists
        score += 30.0 + (item_size as f64) * 0.5;
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 150.0; // existing bin fits well; strongly discourage new bin
        }
    }

    // Late in stream: consolidate, avoid fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving a large awkward gap: dead space below small-item threshold.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small gap is fine
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // mid gap is awkward
    }

    // Lookahead: if next item fits into post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward if next item fits nearly perfectly.
            let chain_gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't chain; penalize large leftover more.
            score += 0.08 * post_residual as f64;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when
    // existing bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early when plenty of fitting bins exist.
        score += 18.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 14.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If item is huge relative to capacity, new bin is less bad.
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        // If open bins are nearly full on average, new bin less penalized.
        score -= 0.15 * mean_residual;
    }

    // Global state: many open bins -> encourage filling existing ones harder.
    if open_bins_count > 2 {
        let crowding = mean_residual / bin_capacity as f64;
        score += 5.0 * crowding;
        score -= 0.05 * open_bins_count as f64 * fit_ratio;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: favor small post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize residuals more (waste matters more)
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward perfect-ish fits (tiny post residual) with smooth exponential bonus
    if norm_pr < 0.12 {
        score -= 8.0 * (1.0 - norm_pr / 0.12).powi(2);
    }

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && nx > pr {
            let unusable = (nx - pr) / cap;
            score += 4.0 * unusable * (1.0 + progress);
        } else if nx <= pr {
            // next item fits: reward, stronger if post_residual remains tight
            let tight = 1.0 - norm_pr;
            score -= 2.5 * (nx / cap) * tight;
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mild preference for tighter ones
        score += 1.0 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // New-bin candidate: prefer opening fresh bin only when residuals across bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        // open new bin if mean residual is small (existing bins nearly full)
        score = 12.0 - 10.0 * fragmentation + 5.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 4.0; // no other choice anyway
        }
    }

    // Mild penalty for proliferating open bins when residuals are large
    if open_bins_count > 2 {
        score += 0.3 * (open_bins_count as f64).ln() * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularity (10) are "harmonic" and more reusable.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Penalize non-harmonic dead space proportionally to its awkwardness.
        score += (post_residual % 10) as f64 * 0.8;
    }

    // Integer-division thresholds: small post-residuals are near-perfect fits.
    let class = post_residual / 10;
    match class {
        0 => score -= 20.0,          // residual < 10 : almost sealed
        1 => score -= 12.0,          // 10..19 : can host a small item
        2 => score -= 6.0,           // 20..29
        3 => score -= 2.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64 * 0.15).min(6.0);
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // next item won't fit here: mild penalty scaled by overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += over as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: opening a bin wastes capacity when mean
    // residual across open bins is still healthy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual / bin_capacity as f64;
        score += 30.0 + 40.0 * waste - 10.0 * progress;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Tight-fit bonus: exact fill leaves zero waste.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (they are "denser", better to fill them first).
    score += ((bin_residual as f64 - mean_residual) * 0.05).clamp(-4.0, 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Items are 1..=100, so a residual below ~10 is
    // almost certainly dead space.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_threshold {
        score += (dead_threshold - pr + 1.0) * 8.0; // smaller gap => worse
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw
    // post_residual: reward small relative slack.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.5 * (post_residual as f64).min(40.0);
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 0.3;
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        score += open_pressure + 5.0;
        // Opening a new bin is acceptable only if it enables a near-perfect
        // placement of the next item too (lookahead pairing).
        if next_item_size > 0 {
            let pair_fit = (item_size + next_item_size) as f64;
            if (bin_capacity as f64 - pair_fit).abs() <= 5.0 {
                score -= 20.0;
            }
        }
    } else {
        score -= open_pressure * 0.5;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.2 + 0.8 * progress);

    // Prefer bins below mean residual (filling emptier bins keeps tight ones
    // for smaller future items).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical items (below min useful)
    let min_useful = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead: reward if next item fits into post residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // bonus if next item exactly fills the bin afterwards
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to wasted chain potential
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // allow new bin late in stream when residuals are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 45.0 * progress;
        }
    }

    // Prefer bins below mean residual (leave large bins for larger items)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early on, be conservative (favor spreading); later, pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: prefer tight fits; polynomial in post_residual.
    let mut score = fit_frac * fit_frac * (3.0 - 2.0 * fit_frac) * cap * 0.5 + pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let wave = (progress * std::f64::consts::PI).sin();
    score += pr * (0.3 + 0.4 * wave * wave) * (1.0 - progress);

    // Penalize dead space relative to mean residual, scaled by progress.
    score += (pr - mean_residual).abs() * (0.2 + 0.5 * progress * progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_frac);
    }

    // Lookahead: reward residual that fits next item smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let match_term = 1.0 / (1.0 + gap * gap / 100.0);
        score -= 10.0 * match_term;
    } else {
        score -= 5.0;
    }

    // Mild penalty for spreading across many open bins, decaying with progress.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only for large items / poor fits.
    if bin_residual == bin_capacity {
        score = pr + 15.0 - 8.0 * (item_size as f64 / cap) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, and small leftovers) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: heavily reward.
        score -= 1000.0;
    } else if pr % 10 == 0 && pr >= 10 {
        // Leftover is a clean multiple of 10 -> likely reusable by future items.
        score -= 30.0 + pr as f64 * 0.2;
    } else {
        // Awkward leftover: penalize small dead space.
        score += (10 - (pr % 10)) as f64 * 1.5;
    }

    // Very small post-residuals (<10) are dead space given min item size 1..100,
    // but tiny leftovers under 5 are almost useless: penalize.
    if pr > 0 && pr < 5 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // this is a perfect chain fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            // Next item leaves a clean multiple-of-10 residue again.
            score -= 60.0;
        } else if pr < next_item_size {
            // Bin cannot host the lookahead item: mild penalty scaled by deficit.
            score += ((next_item_size - pr) as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default mild penalty so that decent existing fits win.
        score += 40.0;
        // But if existing bins are badly fragmented (high mean residual waste
        // relative to capacity) and many bins are open, opening fresh is fine.
        let frag = mean_residual / bin_capacity as f64;
        if frag < 0.25 && open_bins_count > 2 {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 30.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual).
    score += (bin_residual as f64) * 0.15;

    // Slight preference for bins below the mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small for typical future items
    let dead_zone: f64 = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 120.0 - crowd * 10.0;
        // If lookahead item can use the remaining space after placement, soften
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 40.0;
        }
    }

    // Pressure from too many open bins: favor consolidating into existing bins
    score += open_bins_count as f64 * 0.5;

    // Lookahead synergy: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual && post_residual > 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: place item here strongly favored
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a new residual; prefer minimal leftover after chaining
            let chain_residual = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_residual * 0.5;
        } else {
            // Next item cannot fit here: penalize, worse when post_residual is small dead space
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 20.0 * (1.0 - waste);
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small unusable residuals (< 10 min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early stream: be slightly more willing to open new bins (keep options open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it early, penalize it late
        score += 10.0 - 25.0 * progress;
        // But if next item pairs perfectly with current item in a fresh bin, favor it
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // chain fit quality
            let chain = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; scales with number of open bins able to fit.
        score += 8.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            // If open bins can fit, only open new bin when item is large relative to capacity
            // (leaves little waste in a fresh bin).
            let big = item_size as f64 / bin_capacity as f64;
            if big > 0.85 {
                score -= 10.0 * (big - 0.85) / 0.15;
            }
        }
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Global residual pressure: if mean residual is high, prefer filling existing bins
    // rather than fragmenting space.
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Prefer bins whose residual is close to item size (best-fit style) with coupling.
    let waste = (bin_residual - item_size) as f64;
    score += 0.3 * (waste / bin_capacity as f64) * waste.sqrt();

    // Mild preference for bins that are already somewhat full (avoid spreading).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + t * t);
    score -= 40.0 * poly;
    // penalize dead space that grows with progress
    score += (norm_pr * norm_pr * norm_pr) * cap * (0.3 + 0.7 * t);
    // reward tight fits more strongly as stream advances
    score -= item_size as f64 / cap * (1.0 + 2.0 * t);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t);
    }
    // lookahead coupling: reward leaving room for next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - t);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }
    // pull toward mean residual to keep bins balanced
    score += 0.15 * (pr - mean_residual) * (1.0 + t);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let q = bin_capacity / 4; // 25
    let residue = post_residual % q;
    let class = post_residual / q; // 0..4

    // Dead-space penalty: residuals too small for typical items (1..100 unknown)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    // Harmonic sweet spots: residuals divisible into small chunks are reusable
    if residue == 0 && post_residual > 0 {
        score -= 12.0; // exact harmonic class boundary
    } else if residue <= 5 && post_residual > 10 {
        score -= 6.0;
    } else if residue >= q - 5 {
        score -= 4.0; // near-boundary, still divisible-ish
    } else {
        score += residue as f64 * 0.35; // penalize awkward middles
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.25 * next_item_size as f64; // chain placement possible
        } else {
            score += 8.0; // next item will need another bin
        }
        // Harmonic match: next item divides post_residual exactly
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 9.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin if all open bins are crowded
    if bin_residual == bin_capacity {
        score = 100.0 + open_bins_count as f64 * 0.1;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        } else if mean_residual >= item_size as f64 * 1.6 {
            score += 20.0; // open bins are roomy enough, discourage new bin
        }
    }

    // Late-stream consolidation: tighten bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling fuller bins (lower post_residual) more strongly mid-stream
    score += 0.15 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste. Penalize hard, with extra severity for tiny slivers.
    let dead_threshold = 1u32;
    if post_residual < dead_threshold.max(next_item_size.min(10)) {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // guaranteed dead space under minimum item size
    } else if post_residual < 20 {
        score += 18.0; // risky gap: only very small items can use it
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Reward bins whose residual is exactly consumed to a useful next gap:
    // if next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap that the lookahead cannot use but could have fit now.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let obp = open_bins_count as f64;
    score += 0.35 * obp * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, allow new bins more freely; late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far above the mean residual (outliers of waste).
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * obp * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong bonus.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch scaled by relative deviation.
            score += diff * 0.35;
            // If next item fits exactly in current residual (before placement), mild reward.
            if next_item_size <= bin_residual && post_residual < next_item_size {
                score += 2.0; // consumed the space next item wanted
            }
        }
        // If post_residual is too small to ever be useful (below min item size 1..100 typical),
        // penalize dead space more heavily.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    } else {
        // Last item: minimize residual waste.
        score += 5.0;
    }

    // Compare against mean residual: prefer bins that end below mean (tightened packing).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild reward for filling larger fraction of bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Early stream: be slightly more conservative (favor tight fits), later: just minimize residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no small item could use (post_residual < 10).
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward; if it
    // would be wasted, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.15;
        }
    }

    // New-bin candidate handling: make new bins attractive when the item is large
    // relative to residuals, or when open bins are congested.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score -= 12.0 * congestion + 15.0 * progress * (item_size as f64 / bin_capacity as f64);
        // Discourage opening new bins when plenty of bins fit the item.
        score += fitting_bins_count as f64 * 9.0;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps capacity distribution uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Mild preference for filling larger-residual bins early in the stream,
    // tighter bins later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64) * 6.0
           + progress * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter fits matter more
    let progress_coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward near-perfect fits smoothly (small post residual + large fill)
    score -= 2.0 * fill * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).max(0.0) / cap;
        let waste = 1.0 - usable;
        score += 0.6 * waste * waste * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Smooth mean-residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: neutral baseline with slight smooth preference late in stream
    if bin_residual == bin_capacity {
        score = 1.2 + 0.5 * progress - 0.4 * fill * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= 3.0 * item_size as f64;

    // Harmonic class of post_residual: dead space in low residues is worse
    let class = post_residual / 10;
    let class_penalty = match class {
        0 => 40.0,          // 0..9 : nearly perfect fit
        1 => 12.0,          // 10..19: small gap, likely fillable
        2 => 20.0,
        3 => 28.0,
        4 => 34.0,
        5 => 38.0,
        6 => 42.0,
        7 => 46.0,
        8 => 50.0,
        _ => 55.0,          // large waste
    };
    score += class_penalty;

    // Reward when next item exactly fills the post residual (harmonic pairing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score += (gap as f64) * 0.3;
        }
    }

    // Penalize opening a new bin when fitting bins exist, unless this bin is bad
    if bin_residual == bin_capacity {
        score += 15.0 * (fitting_bins_count.max(1) as f64);
        if next_item_size > 0 && next_item_size > item_size {
            // reserve space logic: new bin fine if next item is big
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (more filled bins get priority)
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Small item into large residual: discourage wasting big space
    if item_size <= 20 && post_residual >= 60 {
        score += 25.0;
    }

    // Late stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size ~10) are heavily penalized.
    if post_residual > 0 {
        let dead = 10u32.saturating_sub(post_residual) as f64;
        score += dead * 12.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small residuals that could still fit a known next item are fine;
    // otherwise small leftovers get a non-linear penalty.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        let gap = (post_residual as f64).powf(2.0) / (bin_capacity as f64);
        score += gap * 0.6;
    }

    // Reward using the bin whose residual is closest above the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 8.0;

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity and thus high
    // tightness penalty already; reinforce it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins below mean residual (use up laggard space) mildly.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post-residual (chainable placement).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that no plausible item (>=1) can use well: tiny residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins whose residual is above average
    // (they have room to spare) and penalize draining below-average bins.
    let cap = bin_capacity as f64;
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no good fits exist.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / cap) > 0.5 || fitting_bins_count <= 1;
        if poor_fit {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Late in the stream: consolidate, avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight preference for tighter fits overall.
    score += 0.1 * (post_residual as f64 / cap) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 2.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
        // Exact match with lookahead is a jackpot.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer bins with smaller residual (best-fit flavor).
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    // or state suggests waste elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        // New bin attractive when item barely fits any open bin or many bins already open.
        score += 5.0 - 6.0 * fit_quality + 0.3 * open_bins_count as f64 - 2.0 * progress;
        // If mean residual is large, prefer reusing open bins.
        score += 0.05 * mean_residual;
    } else {
        // Mild penalty for spreading across too many bins.
        score += 0.02 * open_bins_count as f64;
        // Prefer bins whose residual deviates from mean (consolidate extremes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Dynamic time horizon: early in stream, be conservative (keep bins balanced);
    // late in stream, aggressively fill whatever fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tightness;

    // Small bonus for perfectly full bins.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let itemn = item_size as f64 / cap;
    let mut score = prn;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 0.6 * prn * prn * (1.0 - t);
    score += 0.9 * prn * prn * prn * t;

    // Tight fits are desirable; reward small post-residual quadratically
    score -= 0.5 * (1.0 - prn) * (1.0 - prn);

    // Dead space penalty: residuals too small for typical items
    if pr > 0.0 && pr < 10.0 {
        score += 2.0 * (10.0 - pr as f64) / 10.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 0.7 * (nx / cap) * (1.0 - prn);
        } else {
            score += 0.4 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Mean residual interaction: prefer bins deviating from mean early, near mean late
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev * (0.5 + t);

    // Mild pressure to consolidate into fewer bins as open bins grow
    score += 0.05 * (open_bins_count as f64).ln() * prn;

    // New-bin candidate: penalize slightly so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * itemn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Dead-space classes: post residual in (10, 20) is a classic trap zone
    if post_residual > 10 && post_residual < 20 {
        score += 40.0;
    }

    // Integer-division thresholds on post_residual vs capacity fractions
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    if post_residual > half {
        score -= 25.0; // bin still very usable after placement
    } else if post_residual > quarter {
        score += 5.0;
    }

    // Modulo classes: residuals congruent to small multiples of 10 pack well
    let m = post_residual % 10;
    if m == 0 {
        score -= 20.0;
    } else if m <= 2 {
        score -= 8.0;
    } else {
        score += (m as f64) * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize fresh bins unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (cap - 60.0);
        if crowded || fitting_bins_count == 0 {
            score += 5.0; // still slightly worse than a good existing fit
        } else {
            score += 150.0; // discourage opening new bin when space exists
        }
    }

    // Progression coupling: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post / cap);

    // Prefer bins tighter than the mean (best-fit flavor)
    score += (post - mean_residual).clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
