pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact 2-step lookahead match
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if post_residual >= next_item_size {
            score -= 20.0 - 0.5 * diff.min(40.0); // next item still fits after this
        } else {
            // next item won't fit: penalize proportionally to wasted lookahead
            score += 5.0 + 0.3 * diff.min(80.0);
        }
    } else {
        // last item: just minimize leftover
        score -= 10.0;
    }

    // Prefer bins whose residual is already small (tight packing)
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Penalize residuals far below the mean (fragmented bins)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // mild reward for being below mean residual
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual == 0 { 0.0 } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 10.0 * (post_residual as f64) };
        // base cost of a fresh bin, scaled by how wasteful it is
        score += 55.0 + pressure + poor_fits;
        // opening a bin is more acceptable early in the stream
        score -= 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for opening fewer bins overall when many are open
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly: penalize post_residual quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Reward near-perfect packing (post_residual very small).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Dead-space penalty: large post_residual is only tolerable if a known
    // future item (lookahead) can fill it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // Lookahead item fits this leftover: excellent pairing.
            score -= 20.0;
        } else if post_residual < next_item_size {
            // Leftover too small for the next item: dead space risk.
            score += 8.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slightly prefer fuller bins early (consolidation), allow spreading later.
    score += mean_residual * 0.1 * (1.0 - progress);

    // New-bin candidate: default penalty so it is chosen only when all open
    // bins fit poorly; relax penalty when many bins are open and stream is late
    // (spreading residual capacity can help future items).
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 {
            // If the next item is large, a fresh bin is more attractive.
            penalty -= (next_item_size as f64 - 50.0).max(0.0) * 0.3;
        }
        if open_bins_count > 3 {
            penalty += 5.0; // too many open bins already; discourage more
        }
        score += penalty.max(5.0);
    }

    // Mild bonus for using bins with moderate residual (avoid hoarding big gaps).
    if !is_new_bin && bin_residual > 60 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: residual value decays non-linearly with stream progress.
    // Late in the stream, leftover space is more likely to become permanent waste.
    let decay = (1.0 + progress).powf(1.5);
    score += (post / cap) * (post * 0.35) / decay;

    // Smooth reward for tight fits: penalize large post_residual quadratically,
    // but only when it is genuinely large relative to capacity.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize near-empty-but-not-full placements (wasting a nearly fresh bin).
    let fill = item_size as f64 / cap;
    if fill < 0.35 {
        score += 20.0 * (0.35 - fill) * (0.35 - fill);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    // and when open bins exist that could absorb the item.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            (open_bins_count as f64).ln() + 1.0
        } else {
            0.0
        };
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
            // new bin can also host the next item: soften penalty
            6.0
        } else {
            0.0
        };
        score += 15.0 + open_pressure * 5.0 * (1.0 - progress) - lookahead_bonus;
    } else {
        // Reward bins whose residual aligns with the next item (chaining fits).
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap).max(0.0);
        }
        // Penalize bins far from mean residual (fragmentation avoidance).
        score += 0.05 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 buckets create
    // "compatibility classes" of leftover space.
    let post_class = post_residual % 10;
    // Penalize residuals in awkward classes (small, hard-to-fill slivers)
    let awkward = (post_class > 0 && post_class <= 3) as f64;
    score += awkward * 12.0;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Integer-division threshold: how many size-10 "slots" remain
    let slots = post_residual / 10;
    score -= slots as f64 * 3.0;

    // Harmonic coupling with next item (lookahead k=2):
    // if next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_class = next_item_size % 10;
            // same harmonic class => likely compatible pair
            if nxt_class == post_class && post_residual > 0 {
                score -= 8.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot use this residual: penalize wasted space
            score += (next_item_size - post_residual).min(post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless the item is huge relative to capacity or mean residual is high.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * frac;
        if mean_residual < item_size as f64 && next_item_size > post_residual {
            score -= 20.0; // open bins are too full -> new bin is fine
        }
    }

    // Progress-aware tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight penalty proportional to how full this bin already is relative
    // to mean residual (balance load across bins when residuals are similar)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps left after placement.
    let dead_zone = 20.0f64;
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < dead_zone {
            // small gaps are almost unusable -> heavy penalty
            score += (dead_zone - gap) * (dead_zone - gap) * 0.35;
        } else {
            // larger residuals are more reusable; mild reward for tight fits
            score -= 6.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // next item won't fit here -> mild penalty, especially if gap is tiny
        score += 4.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize proportionally to open bin count
        score += 18.0 + 2.5 * open_bins_count as f64;
        // but if no open bin fits, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // last-chance bin gets a strong reward to avoid wasting its capacity
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // prefer bins with tighter residual (best-fit coupling)
        score += 0.15 * (bin_residual as f64 - post_residual as f64).abs();
    }

    // Stream progression: early on, be conservative about new bins; later, allow tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if current bin's residual is far below mean, it's a good filler
    score -= 0.10 * (mean_residual - bin_residual as f64).abs().min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + pair_waste);
        } else {
            // next item won't fit here: penalize leaving medium dead space
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (concentrating usage into tight bins), penalize high-residual bins
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when nothing else fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        // late in stream, opening new bins is fine (no future to plan)
        if next_item_size == 0 {
            score -= 30.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize leaving residuals in the "awkward" zone (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear boost.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize bins whose residual was already small relative to mean residual
    // (i.e., we are consuming a scarce resource).
    let residual_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += 10.0 * residual_ratio;

    // Last-chance bin: strongly favor using it, otherwise item forces a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // Mild penalty when many bins compete: prefer spreading load.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Dead space for the known next item; penalize proportionally.
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, opening new bins is cheap since no future to plan for.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus time-varying discount.
        let mut new_bin_cost = 25.0;
        new_bin_cost -= 20.0 * progress;
        // Opening a new bin is more attractive when open bins are on average full.
        new_bin_cost -= 15.0 * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);
        // Avoid opening new bins when the item would fit well elsewhere.
        if post_residual < 20 { new_bin_cost += 10.0; }
        score += new_bin_cost;
    } else {
        // Filling existing bins: reward slightly more as stream progresses.
        score -= 5.0 * progress;
        // Prefer choosing bins below mean residual (keep some bins roomy for future big items).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Coupling: large items should prefer bins with large residual to avoid fragmentation.
    let item_frac = (item_size as f64) / (bin_capacity as f64);
    if item_frac > 0.5 {
        score += 8.0 * (1.0 - residual_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * progress);
    // Penalize very small dead space (unusable slivers) smoothly
    let sliver = (norm_pr * (1.0 - norm_pr)).powi(2) * cap * 0.5;
    // Reward tight fits (low post_residual) more strongly late in the stream
    let tightness = -norm_pr * norm_pr * (1.0 + progress) * cap;
    // Last-chance bonus: avoid opening new bins unnecessarily
    let last_chance = if fitting_bins_count == 1 { -15.0 * (1.0 - progress) } else { 0.0 };
    // Lookahead: reward bins that leave room for the next item
    let look = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt { -6.0 * (1.0 - (pr - nxt) / cap) } else { 4.0 * (1.0 - pr / cap) }
    } else { 0.0 };
    // Mild penalty for many open bins relative to stream
    let spread = open_bins_count as f64 * 0.05 * (0.5 + progress);
    // Deviation from mean residual: prefer near-mean bins (balance)
    let dev = ((pr - mean_residual) / cap).abs() * 10.0;
    // New-bin candidate: neutral-ish baseline with smooth progress scaling
    let new_bin = if bin_residual == bin_capacity { 20.0 + 30.0 * (1.0 - progress) } else { 0.0 };
    base + sliver + tightness + last_chance + look + spread + dev + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class 0: perfect fit -> strong reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows for residuals that can't hold small items.
        let small = if pr < 10 { 0 } else { 1 };
        if small == 0 {
            score += 50.0; // residual < min item: total dead space
        }
        // Harmonic residue classes: residuals divisible by 10/20/25 are more reusable.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Integer-division thresholds: half-full and quarter-full residuals are valuable.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr >= half { score -= 12.0; }
        else if pr >= quarter { score -= 4.0; }
        else { score += 6.0; } // small awkward residual penalty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
            // Harmonic match: next item leaves another class-0 or round residual.
            let pr2 = pr - next_item_size;
            if pr2 == 0 { score -= 30.0; }
            else if pr2 % 10 == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here: slight penalty proportional to overflow gap.
            score += (next_item_size - pr).min(50) as f64 * 0.3;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 20.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly so we
    // prefer reusing open bins unless they are truly bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are pure waste. Penalize hard in the "unusable gap" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Bonus if this bin could host BOTH the current leftover idea and next item.
        if bin_residual >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how well existing bins fit,
        // plus a mild progress-scaled penalty.
        score += 15.0 + open_pressure + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // If the current item would leave a large usable residual in a fresh bin
        // while existing bins are nearly full (high mean residual is good), be lenient.
        if post_residual >= 40 && mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward when its residual is below the mean (tight bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Reward large fill fraction of this bin.
        score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
