    } else if next_item_size > post_residual && post_residual < next_item_size {
        // dead space that cannot host the next item
        score += 15.0;
    }

    // Last-chance bin bonus: avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
