        score += 120.0 - 40.0 * progress;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 30.0; // fresh bin useful for larger next item
        }
    }

    // Global state: many open bins -> prefer packing tightly into existing ones
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins close to mean (balanced packing)
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Small residuals are fragile; slight extra penalty scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
