pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize waste more.
    let coupling = 1.0 + progress * (2.0 - progress);
    score += 12.0 * norm_pr * norm_pr * coupling;

    // Dead-space penalty: residuals too small for typical future items.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild preference among multiple candidates by fit quality.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving a residual that fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let slack = pr as f64 - nxt;
            score -= 8.0 * (1.0 - (slack / cap).min(1.0));
        } else {
            // Penalize if post-residual cannot host next item, scaled by closeness.
            let gap = nxt - pr as f64;
            score += 0.15 * gap;
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Relative-to-mean residual: favor bins already below mean residual (tighter).
    score += 0.3 * ((pr - mean_residual) / cap);

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin fits well; smooth via interaction with progress.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap * (0.9 + 0.1 * progress) - 6.0 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which "slot" of capacity does the leftover fall into?
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // 0..1

    // Integer-division thresholds: classify post_residual into harmonic bands
    let band = post_residual / (bin_capacity / 4).max(1); // 0..4 harmonic class
    match band {
        0 => score -= 8.0,          // near-perfect fit: strong reward
        1 => score -= 3.0,          // good leftover class
        2 => { /* neutral */ }
        _ => score += 4.0,          // large dead space penalty
    }

    // Modulo arithmetic on residual: residuals divisible by common item classes (10/20/25/50) are reusable
    let r = post_residual;
    if r == 0 { score -= 12.0; }
    else if r % 10 == 0 { score -= 4.0; }
    else if r % 5 == 0 { score -= 2.0; }
    else { score += 1.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // next item won't fit here: penalize leaving moderately-sized dead space
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: baseline score so it only wins when open bins are bad fits
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + mean_residual * 0.3 + (open_bins_count as f64);
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    // Slight stream-progression damping: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Fractional nonlinearity: reward residuals that are small fractions of capacity
    score += (frac * frac) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

