        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward filling bins with large residuals (tight coupling to post_residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post residual but could fit another bin's residual,
    // mildly penalize blocking a good fit.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: make an empty bin attractive only when the item
