    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        // Large items open fresh bins cheaply; small items should use existing space.
        let penalty = 20.0 - big_item * 25.0;
        score += penalty.max(-5.0);
        // If many bins are open and item is small, discourage new bins more.
        if open_bins_count > 3 && big_item < 0.5 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
