    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But allow new bin early in stream or when next item is large
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
    }

    // Slight stream-progression adaptation: be more conservative (keep bins open) later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals non-linearly (dead space grows quadratically).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for a "combo" fit leaving little room after next item too.
            let combo = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - combo / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally to waste.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // End of stream: just minimize waste.
        score -= 10.0;
    }

    // Time horizon: early in stream, favor opening new bins for large items
    // (keeps small residuals for later small items); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item = item_size as f64 / bin_capacity as f64;
        let early_bonus = (1.0 - progress) * 30.0 * large_item;
        let late_penalty = progress * 45.0;
        score += late_penalty - early_bonus;
        // Never open a new bin if a decent fit exists elsewhere.
        if fill_ratio > 0.6 {
            score += 50.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit behavior),
        // modulated by global mean residual.
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * diff;
        if (bin_residual as f64) < mean_residual {
            score -= 5.0; // prefer tighter-than-average bins
        }
    }

    // Mild pressure to reduce open bin count when many bins are open.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by a progress-dependent factor.
    // Early on, waste is cheap (bins plentiful); late, waste is costly.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score *= waste_weight;

    // Non-linear fit-quality term: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    // Penalize large post-residuals non-linearly (dead space that likely never gets used).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead * (0.3 + progress);

    // Lookahead coupling: reward bins whose post-residual matches the next item size smoothly.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let norm_gap = gap / bin_capacity as f64;
        score += 6.0 * norm_gap * norm_gap - 4.0 / (1.0 + norm_gap * 10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - dead);
    }

    // Coupling with mean residual: bins far from the mean residual are slightly penalized
    // (keeps residuals homogeneous, improving future packing), smooth quadratic.
    let dev = post_residual as f64 - mean_residual;
    score += 0.02 * dev * dev / (1.0 + open_bins_count as f64);

    // New-bin candidate handling: an empty bin has no sunk cost; make it attractive
    // when post-residual of existing bins would be very wasteful, but not too early.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score = 30.0 + 25.0 * (1.0 - progress) - 20.0 * scarcity * dead.min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fill is perfect.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Classify post_residual by integer division into dead-space classes.
        // Small leftovers (< 10) are nearly unusable dead space -> penalize hard.
        if post_residual < 10 {
            score += 120.0;
        } else if post_residual <= 20 {
            score += 40.0;
        } else if post_residual <= 40 {
            score += 10.0;
        } else {
            score -= 15.0; // large residual stays reusable
        }

        // Harmonic bonus: post_residual divisible into useful chunk classes.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 25.0;
        }
        if post_residual == half || post_residual == quarter {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 60.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual at all: it is dead for lookahead
            score += 30.0;
        }
    } else {
        // last item: prefer exact fill strongly
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // among open bins or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let tight_fit_exists = mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 10.0;
        if fitting_bins_count == 0 || (item_size as f64 > mean_residual + 25.0 && !tight_fit_exists) {
            score -= 100.0;
        } else {
            score += 150.0; // prefer filling existing bins normally
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Mild pressure to keep the fleet of open bins tight.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Slight nudge toward bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for typical
    // future items are "dead space". Penalize them heavily, non-linearly.
    let dead_threshold = 10.0_f64; // smallest possible item size
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // unusable gap: hard penalty
    } else {
        // Quadratic penalty on small-but-usable residuals to prefer tight fits.
        let r = post_residual as f64;
        score += (r / bin_capacity as f64).powi(2) * 30.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 2.0 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap blocks the known next item
    }

    // Open-bin pressure: discourage spreading into many bins when few fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // last-chance bin: strongly favor using it
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_r / bin_capacity as f64;
        score += 5.0 + 40.0 * pressure * (1.0 - 0.5 * progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild penalty for very loose fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    if post_residual == 0 {
        score -= 200.0; // perfect closure
    } else {
        // Fractional waste penalty, superlinear in waste.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste_frac * waste_frac;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fits afterwards
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
        } else {
            // next item would NOT fit in this bin's leftover: mild penalty
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current fits are all poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; make it unattractive by default,
        // but attractive if the item is large and would leave a clean residual
        // matching the next item.
        score = 90.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0 * (1.0 - (bin_capacity - item_size - next_item_size) as f64 / bin_capacity as f64);
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin anyway
        }
    }

    // Slight preference early in the stream to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: leaving residual that next item could use is good,
    // but leaving residual *just barely* unusable by next item is bad.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0 * (1.0 - (next_item_size - post_residual) as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // or this item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = (mean_residual / bin_capacity as f64).max(0.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 30.0 + 20.0 * crowding + 15.0 * progress;
        // If the item fits snugly in a fresh bin, that's fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            new_bin_score -= 25.0;
        }
        // If many bins fit the item, prefer reusing one.
        if fitting_bins_count > 2 {
            new_bin_score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        score = score.max(0.0) + new_bin_score;
        return score;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if (bin_residual as f64) > mean_residual * 1.5 {
        score -= 5.0;
    } else if (bin_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    // Slight preference for filling older bins (first-fit bias) as stream progresses.
    score += 3.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth progress-dependent weighting: later in stream, waste matters more
    let w = 1.0 + 0.8 * progress * progress + 0.4 * progress * x;

    // Quartic penalty for small dead space, softened early in the stream
    let dead = (-x).max(0.0);
    let dead_penalty = (1.0 - x).powi(4) * (1.0 + 2.0 * progress);

    score = score * w + dead_penalty * cap * 0.5;

    // Reward tight fits: perfect fill bonus scaled by progress
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // smooth bonus inversely proportional to post residual
        score -= (item_size as f64) / (1.0 + x * 4.0) * 0.3;
    }

    // Last-chance bin: strong penalty unless the fit is very tight
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - x;
        score += 8.0 * (1.0 - tightness) * (1.0 - progress);
    }

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 2.0; // next item still fits, good
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (1.0 + progress);
        }
    }

    // Mean residual coupling: avoid bins far from the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: mild preference for opening fresh bins early,
    // stronger resistance late in the stream
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) - 3.0 * progress;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that are "awkward" classes: small but nonzero leftovers
    // are dead space; large residuals are reusable. Use harmonic-style buckets.
    if post_residual == 0 {
        score -= 60.0; // perfect fit — strongly reward
    } else if post_residual <= 10 {
        score += 25.0; // tiny dead space class — heavily penalize
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else if post_residual <= 50 {
        score -= 6.0; // half-bin class — good reuse potential
    } else {
        score -= 10.0; // large residual class — very reusable
    }

    // Modulo arithmetic on post_residual: residuals that align with common
    // item-size classes (multiples of 10/20) are more likely to be filled.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= (next_left as f64) * 0.15; // chain keeps residual small
            if next_left == 0 {
                score -= 20.0;
            }
            // harmonic class match: next item size divisible into residual
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item won't fit here — residual likely stranded
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (score already lower for small post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // (capacity - item). Only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 15.0;
        // early in stream, opening bins is cheap; late, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 12.0;
        }
        // if many open bins already, discourage another
        score += (open_bins_count as f64) * 1.5;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // already tight — reward finishing it off.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    // Small overall tightness bonus relative to capacity
    score += frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize moderate dead space that likely cannot host future items
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.6;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins less attractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Progress-scaled tightening: as stream advances, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (perfect 2-chain), moderately reward
    // bins that can still host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain: close the bin completely
        } else if post_residual >= next_item_size {
            score -= 25.0; // next item still fits: keep the chain going
        } else {
            // dead space smaller than the next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.6;
        }
    }

    // Penalize leaving tiny unusable slivers in general.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fills relative to the mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large and current
    // bins would leave big dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        let best_alt = if fitting_bins_count > 0 {
            // rough estimate of residual if placed in an existing bin
            (mean_residual - item_f).max(0.0)
        } else {
            100.0
        };
        let dead_alt = best_alt.min(9.0);
        // open a new bin only if every existing fit would strand < 10 units
        score += if fitting_bins_count > 0 && dead_alt >= 1.0 {
            45.0 // existing bins leave usable slivers -> prefer them
        } else {
            -5.0 // no good alternative -> allow a fresh bin
        };
        // prefer opening bins early in the stream (amortization)
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= (1.0 - progress) * 5.0;
        }
    }

    // Mild penalty for bin sprawl when many bins are already open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    } else {
        // Last item: pure best-fit, no lookahead needed.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: make fresh bins attractive only when existing
    // fits are poor or the stream is early (amortize future capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap-ish; late stream: penalize new bins.
        score += 20.0 + 40.0 * progress;
        // If many bins are open already, discourage fragmentation.
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, definitely avoid a new bin.
        score += 0.4 * mean_residual;
        // Small items can go anywhere; new bin wasteful for them.
        if item_size <= 20 {
            score += 30.0;
        }
    } else {
        // Reward filling bins that are already partially used.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Mild global pressure: when many bins are open, prefer consolidating.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Time-horizon term: late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // Prefer bins whose residual is below mean (they're the "smaller" bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Non-linear coupling of post_residual with stream progress:
    // early stream: tolerate larger post residuals (flexibility matters);
    // late stream: penalize leftover space more aggressively (waste matters).
    let pr_norm = post_residual as f64 / cap;
    score += 20.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);
    score -= 8.0 * pr_norm * (1.0 - progress);

    // Lookahead synergy: reward when post_residual can still host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let synergy = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * synergy;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless it clearly beats reusing
    // (e.g., item is huge and would leave tiny dead space, or late stream with many bins).
    if bin_residual == bin_capacity {
        let huge = item_size as f64 / cap;
        score += 10.0 - 14.0 * huge * huge - 6.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities (5, 10) are more reusable; penalize awkward residues.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 12.0;
        } else if r % 5 == 0 {
            score -= 6.0;
        } else {
            score += (r % 5) as f64 * 2.5;
        }
    }

    // Perfect closure: item exactly fills the bin -> strongly reward.
    if r == 0 {
        score -= 50.0;
    }

    // Tight fit: item leaves very little waste.
    if r <= 5 && r > 0 {
        score -= 20.0;
    }

    // Coupling with next item: reward if next item fits into post-residual
    // (chained placement), penalize if next item would need a fresh bin.
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 15.0;
            // Harmonic bonus: next item exactly divides the residual
            if r % next_item_size == 0 {
                score -= 10.0;
            }
        } else if next_item_size > r {
            score += (next_item_size - r) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless the item is
    // huge relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Integer-division threshold: bins whose residual after placement falls in
    // a "dead zone" (1..=9 with awkward residue) are penalized.
    if r >= 1 && r <= 9 && r % 5 != 0 {
        score += 8.0;
    }

    // Progress-aware: later in the stream, prefer consolidating into fewer
    // bins (slightly favor existing bins over opening new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual deviates favorably from
    // the mean (smaller), reward it.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: gaps too small for any plausible future item (<=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-ish gaps that can only host tiny items: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Prefer bins whose residual was tight to begin with (best-fit core).
    score += (bin_residual as f64) * 0.05;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty to encourage spreading consolidation elsewhere.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage opening yet another.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if new_bin {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the next item fits the leftover of this item in the fresh bin, soften.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Late in the stream, tighten up: prefer minimal waste even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Deviation from mean residual: bins far above mean have more usable room; slight reward.
    score -= (bin_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> chain fit
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this residual
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight packing relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Progress pressure: late in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits via a non-linear shrink of post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;  // awkward gap
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't chain here; mildly penalize leaving a large unusable remainder.
            let waste = post_residual as f64;
            score += 0.05 * waste;
        }
        // Strong reward if next item exactly consumes the remainder.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item in stream: prefer fullest packing.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual < 15 {
            score -= 8.0; // nearly perfect fill, take it
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables
    // a much better long-run configuration.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Large items justify fresh bins; small items should use existing space.
        if item_size >= 50 {
            score -= 14.0;
        }
        if item_size <= 20 {
            score += 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If existing bins are crowded (low mean residual), a new bin is more reasonable.
        score -= 0.15 * mean_residual;
        // If very few bins fit the item, opening a new bin is acceptable.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    } else {
        // Existing-bin placements: mildly reward using crowded bins to consolidate.
        let crowding = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * crowding;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins aggressively.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 3.0;
    }

    // Small time-varying tie-breaker to diversify exploration across the stream.
    let phase = ((step_index as f64) * 0.37).sin();
    score += 0.8 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Quadratic post-residual shaping: heavily penalize large leftover space,
    // but tiny residuals (<~10) are nearly perfect — smooth quartic bowl.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward near-perfect fills (small post residual) with a smooth exponential discount
    score -= 25.0 * (-pr / 8.0).exp();

    // Fit ratio coupling: item filling the bin tightly is good
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bin: strong bonus so we don't waste the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild competition pressure: more candidates -> less urgency per bin
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-slack / 10.0).exp();
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / 40.0).min(1.0);
        }
    }

    // Mean residual interaction: prefer placing into bins with residual near the item
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / 50.0).min(1.0);

    // Open-bin pressure: many open bins -> favor consolidation into existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Late-stream: closing bins tightly matters more
    score -= 10.0 * progress * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: keep it neutral-ish, only open when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin slightly, scaled by how well existing bins could fit.
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 + post_residual as f64 * 0.3 };
        return pressure + (post_residual as f64);
    }

    // Tight-fit reward: quadratic discount for small post_residual.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powi(2) * 0.01;

    // Dead-space penalty: residual too small for the next item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else if post_residual == next_item_size {
            // Perfect pairing: the next item exactly seals this bin.
            score -= 15.0;
        } else {
            // Harmonic class: post_residual divisible into chunks matching next item.
            let class = post_residual / next_item_size.max(1);
            if class >= 2 {
                score -= 3.0 + class as f64;
            }
        }
    }

    // Harmonic residue classes on post_residual (mod 10 buckets).
    let m = post_residual % 10;
    score += match m {
        0 => -6.0,               // round residual, highly reusable
        1..=4 => -2.0,           // small slivers still usable for tiny items
        5..=8 => 0.0,
        _ => 4.0,                // 9: worst class, nearly sealed
    };

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Late in stream, consolidate: prefer bins below mean residual (well-used bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 4.0 * progress;
    } else {
        score += 2.0 * progress;
    }

    // Penalize spreading across many open bins slightly.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    let is_new_bin = bin_residual == bin_capacity;

    // --- Perfect fit: overwhelming reward ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Strict dead-space avoidance: small nonzero gaps are likely unusable ---
    // Penalize gaps in (0, 10] proportionally to how dead they are, so that
    // leaving a tiny unusable残 gap ranks worse than leaving a usable gap >= 11,
    // while still ranking better than squashing into a very large residual.
    let dead_max: u32 = 10;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max + 1 - post_residual) as f64 * 4.0;
    }

    // --- Lookahead (k=2): shape the gap for the next item ---
    if next_item_size > 0 {
        let nis = next_item_size as f64;
        if pr >= nis {
            if post_residual as u32 == next_item_size {
                score -= 300.0; // gap exactly hosts the next item
            } else {
                // mild reward: gap remains usable by the upcoming item
                score -= 20.0 * (1.0 - (pr - nis) / cap);
            }
        } else if post_residual > 0 {
            // gap too small even for the next item: dead for at least one step
            score += 15.0;
        }
    }

    // --- Last-chance open bin: strongly avoid opening a new bin ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 60.0;
    }

    // --- Fullness alignment: prefer filling bins that are already fuller than average ---
    score += 0.05 * (bin_residual as f64 - mean_residual);

    if is_new_bin {
        // New-bin candidate: penalize when consolidation into open bins is preferable.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += 25.0
               + 3.0 * open_bins_count as f64
               + 0.20 * mean_residual
               + 20.0 * progress;
        // No open bin can fit: opening a new bin is the only sane choice.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Open-bin pressure: when many bins are open, favor consuming existing space
        // (uniform shift across open bins; tips the balance against the new-bin candidate).
        score -= (open_bins_count as f64) * (item_size as f64 / cap) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
