pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: post_residual smaller than
    // the minimum plausible item size (1) is fine, but residuals that are
    // awkwardly small relative to the item distribution waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward placing the item here if the next item
    // would fit in the resulting post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // encourage consolidating into existing bins rather than spreading.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 4.0;
    }

    // Time horizon: early in the stream, be more liberal about opening
    // bins (favor tight fits anywhere); late in the stream, prefer
    // filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - tightness);

    // Penalty proportional to number of open bins: discourage bin sprawl.
    score += 0.35 * open_bins_count as f64;

    // Reward using large residual bins for large items (harmonic pairing).
    if item_size >= bin_capacity / 2 && bin_residual >= bin_capacity / 2 {
        score -= 8.0;
    }

    // Slight preference for bins whose residual is a clean multiple
    // of common item sizes (divisibility heuristic).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: reward tight fits more strongly as stream progresses.
    let tight = (1.0 - x) * (1.0 - x); // quadratic tightness
    score -= tight * cap * (0.35 + 0.65 * t);

    // Cubic penalty for awkward mid-range dead space (neither tight nor roomy).
    let awkward = 4.0 * x * (1.0 - x);
    score += awkward * 6.0 * (0.5 + 0.5 * t);

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (nx / cap)) * (1.0 + t);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mildly discourage bin proliferation early; allow more bins later.
    score += (open_bins_count as f64) * (1.5 - 2.0 * t);

    // Nudge toward bins whose residual is below average (consolidation).
    score += ((pr - mean_residual) / cap) * 10.0;

    // New-bin candidate handling: penalize slightly early, reward when existing fits are bad.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 12.0 * (1.0 - t);
        // If item is large relative to capacity, opening fresh is more attractive.
        score -= (item_size as f64 / cap) * 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste in residue classes of 10
    let harmonic = post_residual % 10;
    // Penalize dead space in awkward residue classes (1..9 minus nice halves)
    let awkward = match harmonic {
        0 => 0.0,
        5 => 2.0,
        _ => 6.0,
    };
    score += awkward * (post_residual as f64 / bin_capacity as f64);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving space exactly matching the next item (harmonic pairing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // post-residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Many fitting bins: prefer tighter ones, mild pressure
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Prefer bins with residual below mean (tighter bins) when post fit is decent
    if (post_residual as f64) <= mean_residual {
        score -= 5.0;
    }

    // Integer-division thresholds: bins whose residual after placement lies in
    // [0,20] are "sealed" zones — good; larger leftovers get graded penalty
    let zone = post_residual / 20; // 0..=4
    score += zone as f64 * 3.0;

    // Slight preference for filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: baseline penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for typical future items (unusable small gaps).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // hard penalty for tiny dead space
    } else if (post_residual as f64) < 25.0 {
        score += 20.0 * (25.0 - post_residual as f64) / 13.0; // graded penalty
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * 10.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + pressure;
        // If no other bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using existing bins, scaled by pressure.
        score -= pressure * 0.5;
        // Last-chance bin: strongly prefer using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Slight preference to keep mean residual balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect pairing with the next item: huge reward
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward tightness of the two-step packing
            let tightness = 1.0 - (pr - nx) / bin_capacity as f64;
            score -= 10.0 + 25.0 * tightness;
        } else {
            // Next item will not fit here; penalize proportionally to overshoot
            score += 0.6 * (nx - pr);
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual deviates
    // favorably from the fleet mean (keep large residuals consolidated) ---
    score += 0.15 * (mean_residual - post_residual as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate: penalize opening a bin when open bins could fit,
    // unless we are early in the stream (building a pool is cheap then) ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 0.6 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that can never hold the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 12.0 + 0.25 * post_residual as f64;
        } else {
            // Reward bins whose leftover can exactly host the lookahead item.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (-slack / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual as u32 >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but allow it late in the stream or when residual fragmentation is high.
    if bin_residual == bin_capacity {
        score += 25.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        if fragmentation > 0.4 || progress > 0.8 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin is good for a large follow-up item
        }
    }

    // Prefer filling bins with larger residuals when many bins are open.
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    // Slight preference for bins close to the mean residual (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time-horizon coupling: early on, be frugal with new bins; late, accept waste.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr * (1.0 + 0.8 * t * norm_pr + 0.5 * norm_pr * norm_pr);

    let mut score = base;

    // Reward tight fits: small post_residual relative to capacity.
    score -= 12.0 * (1.0 - norm_pr) * norm_pr;

    // Penalize dead space that next item cannot use (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap;
        } else {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - t);
    }

    // Slight preference for consolidating when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: neutral-ish baseline, mildly penalized early.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - t) + 2.0;
    }

    // Damp with mean residual context: prefer bins near the mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // multiples / near-multiples of common item size classes.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: post_residual is an exact multiple of small item classes (10,20,25,50)
    let class_hits: i64 = {
        let mut h = 0;
        for m in [10i64, 20, 25, 50] {
            if post % m == 0 && post > 0 { h += 1; }
        }
        h
    };
    score -= 6.0 * class_hits as f64;

    // Class B: post_residual is very small -> dead space penalty
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Integer division threshold: post_residual in low half of capacity
    if post < cap / 2 {
        score += 8.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx <= post {
            if post - nx < 10 {
                score -= 20.0; // perfect two-item packing
            } else {
                score -= 10.0; // next item fits well
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
        // modulo harmony: post_residual and next_item_size share a divisor class
        if nx > 0 && post % nx == 0 {
            score -= 8.0;
        }
    } else {
        // last item: just minimize leftover
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling existing bins over opening new ones when stream is late
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 + 10.0 * progress;
    } else {
        // new-bin candidate: penalize unless open bins are congested
        score += 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Tightness reward: small relative waste
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // tiny leftover gap is worst
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderately awkward gap
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Open-bin pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a near-full future fill
    // or current open bins are mostly full; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 15.0; // new bin can serve the lookahead item well
        }
        if post_residual == 0 {
            score -= 10.0; // item exactly fills a fresh bin
        }
    }

    // Lookahead coupling: prefer leaving gaps that still fit the next item.
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 && post_residual > 0 {
            score += 6.0; // dead space for the known next item
        } else if (post_residual as u64) >= next_item_size as u64 {
            score -= 4.0;
        }
    }

    // Slight late-stream conservatism: keep residual usable as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // this bin will remain useful -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // Extra reward when next item fits *exactly* after this placement.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover space: penalize proportionally to waste.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste;
    }

    // Penalize residuals that no typical small item could use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: bins with more room than average are
    // better targets for large items; tighter-than-average bins are
    // good for small items.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so that
    // decent fits into existing bins are preferred, but good fits
    // (already rewarded above) will still beat opening a new bin only
    // if the existing-bin fit is genuinely tight.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Opening a new bin is more attractive early when few bins exist
        // (keeps future flexibility), less so late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
    }

    // Mild preference for keeping the number of open bins stable.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual gets extra discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that no plausible item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: penalize proportionally to wasted potential
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base mild penalty so tight fits in existing bins win.
        score += 14.0;
        // But if item is huge and mean residual is small (bins nearly full),
        // opening fresh is fine.
        score -= 20.0 * big_item * (1.0 - mean_residual / bin_capacity as f64).min(1.0);
        // Late in the stream, avoid opening unnecessary bins.
        score += 10.0 * progress;
        let _ = fragmentation;
    }

    // Mild preference for bins below mean residual (balance across bins).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Slight penalty per open bin to discourage sprawl.
    score += 0.5 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: tight fit reward, quadratic in post_residual.
    let mut score = pr * pr / cap + pr * (1.0 - fit_frac);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, squeeze harder; early, be lenient.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr;

    // Reward filling bins relative to mean residual (smooth exponential coupling).
    score -= (mean_residual - pr) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    } else {
        score -= (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - pr / cap) * (nxt / cap) * 15.0;
        } else {
            score += (nxt - pr) * 0.15 * (1.0 + progress);
        }
    }

    // Penalize opening a new bin (empty-bin candidate), more so as stream progresses.
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress + 2.0 * (open_bins_count as f64);
        // But allow a new bin if item is huge and would leave tiny dead space elsewhere.
        score -= fit_frac * fit_frac * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "usable" sizes
    // (items are 1..=100, so residual >= 10 is reusable; small slivers are dead space)
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 150.0; // dead-space penalty: nothing can ever fit
    }

    // Class of residual by divisibility structure — residuals divisible by
    // common item sizes are more reusable
    if r >= 10 {
        if r % 10 == 0 { score -= 40.0; }
        else if r % 5 == 0 { score -= 20.0; }
        else if r % 3 == 0 { score -= 10.0; }
        else { score += 10.0; } // awkward residue class
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if r >= next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 25.0; // leaves a sliver smaller than next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when fit would be terrible
    if bin_residual == bin_capacity {
        if post_residual < 10 && post_residual > 0 {
            score -= 120.0; // opening new bin beats creating dead space
        } else {
            score += 60.0; // default: prefer existing bins
        }
    }

    // Waste fraction term: penalize relative waste non-linearly
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 80.0 * waste_frac * waste_frac;

    // Late in stream: tighten packing, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    // Many open bins with high mean residual: favor bins below mean (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let dead = (post_residual as f64).powf(2.2) / 60.0;
        score += dead;
        // If the leftover gap is too small for the lookahead item, it's likely dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead synergy: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open-bin pressure is high.
        score += 8.0 + open_bins_count as f64 * 1.5 + progress * 5.0;
        // But if mean residual across open bins is very low, opening is less bad.
        score -= mean_residual * 0.15;
    } else {
        // Favor tighter bins (smaller residual before placement) mildly.
        score += bin_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0;
        } else if post_residual as f64 >= next {
            score -= 60.0 * (1.0 - ((post_residual as f64 - next) / bin_capacity as f64));
        } else {
            // Next item cannot fit here: penalize proportionally to wasted lookahead.
            score += 25.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize the brand-new empty bin candidate unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 150.0 - 100.0 * tightness;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor bins where the item nearly fills the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize tiny unusable leftovers (dead space), more so early in the stream
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - t);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward;
    // if the next item would fit this bin but not the residual, penalize waste.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // choosing this bin blocks a better fit for the next item
            score += 10.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin is penalized mildly,
    // unless existing bins are fragmented (high mean residual spread) or late stream.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 18.0 - 10.0 * t - (open_bins_count as f64).min(10.0) * 0.5 - fragmentation * 0.3;
        // Never open a new bin when a perfect fit exists elsewhere is handled by
        // their large negative bonuses; keep new-bin score anchored near post_residual.
        score += item_size as f64 * 0.1;
    }

    // Mild preference to fill bins with larger residuals when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Global balance: nudge toward bins below mean residual to even out fragmentation
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger later in the stream
    score -= (item_size as f64 / cap).powi(2) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * waste * (0.5 + progress);
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= 5.0 * (mean_residual - pr) / cap;

    // Mild penalty for spreading across many open bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) / (total_items as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that no plausible item (1..=100) can fill well.
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else {
        // Harmonic classes: post_residual divisible by common item sizes
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        if post_residual % 50 == 0 {
            score -= 5.0;
        }
        // Awkward mid-range residual (prime-ish, hard to fill)
        let awkward = post_residual % 7 == 3 || post_residual % 11 == 5;
        if awkward {
            score += 3.0;
        }
    }

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // Harmonic match: residual exactly fits next item in class steps
            if post_residual == next_item_size {
                score -= 6.0;
            } else if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        // Prefer new bin when mean residual is small (open bins nearly full)
        score += 20.0 * (1.0 - fragmentation);
        if fragmentation > 0.5 {
            score -= 10.0;
        }
        if progress > 0.8 {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 2.0;
        }
    }

    // Mild preference for tight fits relative to capacity fractions
    let fill_fraction = (bin_capacity - post_residual) as f64 / cap;
    if fill_fraction >= 0.9 {
        score -= 5.0;
    } else if fill_fraction >= 0.7 {
        score -= 2.0;
    }

    // Penalize leaving residual far from mean (keeps bin pool balanced)
    score += (pr - mean_residual).abs() * 0.05;

    // Scale by open bins count: with many open bins, prefer consolidation
    if open_bins_count > 5 {
        score += 0.3 * open_bins_count as f64 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
