    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins with below-average residual (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: mildly penalize so it is chosen only when
    // existing placements are poor (dead space dominates).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly reward filling the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item would fit.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * next_fit;
        } else {
            // Next item cannot use this residual; penalize wasted potential,
            // scaled by how much dead space would be stranded.
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // If next item could have fit this bin's residual but won't fit after,
            // mild penalty for poor sequencing.
            if next_item_size <= bin_residual {
                score += 50.0;
            }
        }
    } else {
        // Last item: strongly prefer exact/near-exact fits.
        score -= 500.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // prefer placing into tight bins (small residual) to consolidate.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large relative to capacity (poor fit elsewhere is unlikely to
    // matter) or when no tight alternative exists.
    if bin_residual == bin_capacity {
        // Base preference against opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 - 150.0 * progress;
        // Large items leave large residuals in a new bin, which is useful.
        score -= 0.8 * item_size as f64;
        // If many bins fit the item, opening a new one is wasteful.
        score += 20.0 * fitting_bins_count as f64;
    } else {
        // Prefer bins whose post-residual remains reusable (>= 10).
        if post_residual >= 10 && post_residual < 10 + item_size.min(50) {
            score -= 30.0;
        }
        // Penalize creating very small dead space (< 10, unusable for min size).
        if post_residual > 0 && post_residual < 10 {
            score += 120.0;
        }
    }

    // Mild preference for fewer open bins: distributing across many bins
    // fragments capacity; favor bins that reduce fragmentation pressure.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize large dead space left behind (waste), non-linearly.
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).powf(1.35);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item would use leftover
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * nl;
        } else {
            // next item cannot use the leftover: penalize large leftovers a bit
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating into existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 {
        let consolidation = (mean_residual / bin_capacity as f64) * (0.5 + 0.5 * progress);
        score -= 30.0 * consolidation;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are poor fits or the item is large relative to available space.
    if bin_residual == bin_capacity {
        // baseline score is full capacity; add penalty so a good existing fit beats it,
        // but subtract when few fitting bins exist or item is large.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            score += 60.0;
        }
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (low post_residual), non-linearly amplified.
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized progressively harder (convex ramp).
    let prog_term = pr * (progress - 0.5 * progress * progress) * 1.6;
    score += prog_term;

    // Reward near-full fills with a smooth saturating bonus.
    let fill = it / br.max(1.0);
    score -= 12.0 * fill * fill * (1.0 - fill * 0.5);

    // Penalize leaving residuals that match neither the next item nor typical sizes.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.35 * gap * (1.0 + progress);
        // Smooth bonus if this placement leaves exactly the next item's space.
        score -= 6.0 * (1.0 - (gap / cap).min(1.0));
    } else {
        // Last item: strongly favor minimizing final waste.
        score += pr * 1.5;
    }

    // Last-chance bin: strong smooth discount so unique fits are used.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // Mild crowding penalty when many bins compete.
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Deviation from mean residual: prefer bins that keep residual distribution healthy.
    score += 0.25 * (pr - mean_residual).abs();

    // New-bin candidate: keep it competitive only when open bins fit poorly.
    if br == cap {
        score += 8.0 + 20.0 * (1.0 - progress) - 4.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size as f64 <= cap - it {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
