    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // base penalty so open bins are usually preferred
        score += 5.0 + mean_residual * 0.3;
        // open new bin when mean residual is high (fragmentation) or end of stream
        if mean_residual > cap * 0.5 {
            score -= mean_residual * 0.4;
        }
        if progress > 0.9 {
            score -= 8.0;
        }
        // small next item: fresh bin can host both
        if next_item_size > 0 && next_item_size <= 20 && item_size <= 50 {
            score -= 10.0;
        }
    }

    // Scale by capacity fraction: large waste fraction penalized super-linearly
    score += frac * frac * 10.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Quantized class tiebreaker: prefer bins whose residual class matches item's class
    let item_class = item_size / 10;
    if pr_class == item_class {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harder than large residuals.
    // Gaps in (0, 10) are essentially dead (items >= 1 though, so scale by size range).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Dead space: heavily penalize, worse the smaller the gap.
            score += (12.0 - gap) * 4.0;
        } else if gap <= 25.0 {
            // Small gaps are only useful for tiny items; mild penalty.
            score += gap * 0.15;
        } else {
            // Large residuals remain flexible: reward proportionally.
            score -= gap * 0.35;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Prefer bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + 0.5 * progress) * 0.8;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave this bin's post-residual dead, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain
        // and current bins are fragmented (high mean residual spread).
        score = 30.0 - (mean_residual / bin_capacity as f64) * 10.0 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    // Reward post_residual that exactly matches the next item's size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when post_residual == next_item_size (perfect 2-step chain).
        score -= 40.0 * (1.0 - lookahead_gap / 100.0).max(0.0);
        // Extra bonus for exact match.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving more space than the next item can consume (wasted dead space).
        if post_residual > next_item_size {
            score += 0.25 * (post_residual - next_item_size) as f64;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.1 * post_residual as f64;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Penalize tiny unusable residuals (dead space) unless next item fits it.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64;
        // But if next item is huge and post_residual of a fresh bin matches it, allow it.
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: tighten packing, favor fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual smaller than the smallest
    // possible future item (1) is fine, but small-but-nonzero leftovers are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Perfect-fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large waste) or few bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_capacity - item_size) as f64 > mean_residual + 5.0;
        let base_penalty = 35.0 + 0.5 * open_bins_count as f64;
        if poor_fit {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += base_penalty;
        }
    } else {
        // Mild preference for filling bins with larger residuals when many are open.
        score += 0.03 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let t = progress * std::f64::consts::PI;
    let wave = (t.sin()).powi(2);
    let coupling = prn * prn * (1.0 + 0.8 * wave) * (1.0 + 0.5 * progress);

    // Penalize wasted residual more strongly as the stream progresses.
    score += 30.0 * coupling;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= 12.0 * (1.0 - prn).powi(3);

    // Lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as f64 / cap;
        score -= 20.0 * (1.0 - nxt) * (1.0 + 0.5 * progress);
    } else if next_item_size > post_residual {
        score += 8.0 * (1.0 - prn);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Penalize proliferating bins mildly.
    score += (open_bins_count as f64).ln() * 3.0;

    // Deviation from mean residual: prefer bins near the mean to keep balance.
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bins attractive only early or for large items.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score -= 10.0 * early * early;
        score += 15.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "harmonic"
    // divisors of capacity (50, 33, 25, 20, 10...) since future items can
    // tile them exactly. Penalize odd/awkward residuals.
    let pr = post_residual;
    let harmonic_bonus: f64 = match pr {
        0 => -30.0,                      // perfect fit
        10 | 20 | 25 | 50 => -12.0,      // exact divisors of 100
        33 | 34 | 40 | 30 => -8.0,
        _ => {
            if pr % 10 == 0 { -4.0 }
            else if pr % 2 == 0 { 0.0 }
            else { 3.0 }                 // odd residual: harder to fill
        }
    };
    score += harmonic_bonus;

    // Dead-space penalty: residuals below the minimum item size are pure waste,
    // but a perfect fit (0) is ideal.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / post.max(1.0);
            score -= 10.0 * frac;
        } else {
            // next item won't fit here; slightly penalize tight residuals
            score += 2.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad.
    if bin_residual == bin_capacity {
        // new bin starts full; base score high, reduced if many open bins already
        score = cap * 0.9 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
    }

    // Progress modulation: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post / cap) * 5.0;

    // Prefer tighter bins overall (best-fit flavor via mean residual coupling).
    score -= (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (min item size 1, but typical items are larger).
    // Penalize post_residual in the "awkward" small range heavily.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Worst dead space: too small for anything useful.
            score += 25.0;
        } else if post_residual <= 20 {
            score += 12.0;
        } else if post_residual <= 35 {
            score += 5.0;
        } else {
            // Large residual is still valuable space; reward it slightly.
            score -= 4.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins;
    // favor filling existing bins when the item fits reasonably well.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (chaining placements). Otherwise penalize leaving a gap the
    // next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual is far below the
    // mean, we are compacting well; reward mildly.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate logic: opening a fresh bin should only win when the
    // current item would leave bad dead space elsewhere. The new-bin call has
    // post_residual = capacity - item_size (large), so it already scores low;
    // add a mild penalty so we prefer decent fits in open bins, but let the
    // dead-space penalties above dominate for poor fits.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (fewer remaining items to fill new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Partial lookahead match: next item fits into post residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 / (1.0 + slack)).min(15.0);
    }
    // Penalize post_residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward exact fills of the bin (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; placing here
    // when it fits well is valuable, but wasting a small residual is costly.
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.4 * (mean_residual - res);
    } else {
        score -= 0.15 * (res - mean_residual);
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Default mild penalty so an existing decent fit wins.
        score = 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Empty bin perfectly suits a large next item if current item is small.
            if item_size <= 30 && next_item_size >= 60 {
                score -= 10.0;
            }
        }
        if fitting_bins_count == 1 {
            // Even a last-chance bin beats opening a new one.
            score += 5.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, tighten placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: relative leftover after placement.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item can use the leftover, this placement is good.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            // Leftover likely wasted relative to the upcoming item.
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Global state coupling: when open bins are already loose, prefer consolidating
    // into tighter-than-average bins.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0).min(2.0);
        }
    }

    // Early in the stream, be more willing to open new bins (build a diverse pool);
    // late in the stream, pack tightly into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, adjusted by horizon and crowding.
        score += 15.0;
        score -= 20.0 * (1.0 - t);
        score += 6.0 * (open_bins_count as f64).ln().max(0.0);
        // If no open bin fits, the new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild preference for fewer open bins as the stream matures.
        score += 3.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize wasted space quadratically, scaled by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a cubic term
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (consolidating larger spaces)
    score += 3.0 * (pr - mean_residual) / cap;

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it slightly worse than a decent fit
    if bin_residual == bin_capacity {
        score += 15.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of the post residual: rewards residuals that are
    // "friendly" multiples (likely to be exactly filled by future items).
    let pr = post_residual;
    if pr > 0 {
        // Perfect-fill bonus: residual exactly divisible into small useful chunks
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 2.5; }
        // Dead-space penalty: tiny, awkward residuals (1..9) are almost unusable
        if pr < 10 { score += 12.0; }
        // Quotient classes: residual in a high integer-division band is flexible
        let q = pr / 10;
        score -= (q as f64) * 0.8;
    } else {
        // Perfect fill: strongly reward exhausting the bin
        score -= 25.0;
    }

    // --- Coupling with lookahead item: harmonic match between next_item_size
    // and post_residual (exact division or shared divisor classes).
    if next_item_size > 0 && next_item_size <= pr {
        let n = next_item_size;
        if pr % n == 0 { score -= 8.0; }                 // next item could exactly fill
        else if n % 2 == 0 && pr % 2 == 0 { score -= 2.0; }
        else if n % 5 == 0 && pr % 5 == 0 { score -= 2.0; }
        if pr - n < 10 { score += 3.0; }                 // would leave new dead space
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this residual at all: mild penalty
        score += 4.0;
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin (new-bin candidate gets no such bonus).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // --- New-bin candidate handling: an empty bin should only win when the
    // item fits poorly everywhere else. Penalize it by the fraction of the
    // capacity consumed, so tight fits in existing bins always win.
    if bin_residual == bin_capacity {
        score += (item_size as f64 / cap) * 15.0;
        score += open_bins_count as f64 * 0.5;           // prefer reusing open bins
    } else {
        // Reward tighter fits in open bins relative to mean residual
        let frac = post / cap;
        if frac < (mean_residual / cap) { score -= 1.5; }
    }

    // --- Late-stream consolidation: as the stream progresses, favor filling
    // existing bins rather than spreading across many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.3;

    // Small tie-breaker: prefer bins whose residual is closest to item size
    score += ((bin_residual as f64) - (item_size as f64)) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item (1..10)
    // are unusable waste. Penalize the "just above threshold" gap hard.
    let min_size = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward proportional to how well the NEXT item fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        // Penalize large leftover relative to item size (wasteful placement).
        score += post_residual as f64 * 0.05;
    }
    let _ = min_size;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when nothing fits well (residual too small
    // for item everywhere else). Make empty bin moderately costly so it loses to
    // any decent fit but wins over terrible fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, new bins are cheap; late, prefer consolidating.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If lookahead item is huge, a fresh bin is more valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect chain fit (post_residual == next_item_size) heavily rewarded
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 > nxt {
            // residual can still host next item: reward closeness to exact fit
            score -= 25.0 * (1.0 - diff / 100.0);
        } else {
            // dead space relative to next item: penalize proportionally
            score += 10.0 * (diff / nxt).min(2.0);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins tightly overall (small post_residual relative to capacity)
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Early in stream: keep bins flexible (mild penalty on very tight leftovers)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && progress < 0.5 {
        score += 5.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless nothing decent exists
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if next item is large and current bins are fragmented, allow it
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: penalize bins whose post-residual can't fit the next item
    // (dead space for the future), reward bins that still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // If next item fits exactly in the post-residual, big reward.
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many bins are open or stream is long.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 80.0 * (1.0 - progress);
        // If few fitting bins, opening a new bin is less costly.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Penalize opening new bins when mean residual is large (bins are mostly empty).
        if mean_residual > item_size as f64 {
            score += 30.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.7 {
            score += 25.0 * progress;
        }
    }

    // Mild penalty for very fragmented residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for bins with residuals close to item size (best-fit flavor).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear polynomial coupling
    let mut score = pr as f64;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * fill * (1.0 - progress);
    score += 30.0 * poly;

    // Penalize dead space that can't fit typical future items (smooth sigmoid-ish on residual)
    let dead = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at half-empty
    score += 8.0 * dead * (0.5 + progress);

    // Reward near-perfect fit strongly
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = (next_item_size as f64) / cap;
        score -= 25.0 * tight * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasting space mildly
        score += 10.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins: prefer consolidating into existing bins
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 15.0 * crowd * fill;

    // New empty bin candidate: penalize unless item is large or fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 70.0 - 40.0 * fill - 60.0 * scarcity - 20.0 * progress;
    }

    // Slight tie-break toward bins with residual close to mean (keeps distribution balanced)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are rewarded (waste is bounded by class width).
    let class_width = 10u32;
    let residue_class = post_residual % class_width; // 0..9
    let class_index = post_residual / class_width;   // 0..10

    // Reward tight fits: post_residual in low classes gets a discount.
    score -= (class_width - residue_class) as f64 * 0.35;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= class_width {
        score -= 8.0;
    }

    // Penalize large dead space classes, especially "awkward" residues
    // that few item sizes (1..100) can fill later.
    let awkward = ((post_residual % 7) == 1) || ((post_residual % 7) == 3);
    if post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.4;
        if awkward {
            score += 6.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely into this bin: reward proportionally.
            let fill_after = (post_residual - next_item_size) % class_width;
            score -= 12.0 + (class_width - fill_after) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize if this bin would be left
            // with a hard-to-use residue class.
            let gap = next_item_size - post_residual;
            if gap <= class_width {
                score += 4.0; // near miss, mildly bad
            }
            if post_residual > 30 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual,
    // which already scores poorly; add a mild opening cost so we only
    // open when no open bin is reasonably tight.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with residuals below the current mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Slight preference to keep the number of open bins moderate.
    if open_bins_count > 8 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // Gaps below ~20 are hard to fill with typical items (>=1 but often larger).
    if post_residual > 0 {
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 6.0; // strong penalty for tiny gaps
        } else if post_residual < 35 {
            score += (35 - post_residual) as f64 * 1.5; // moderate penalty
        } else {
            score -= 4.0; // generous leftover is reusable
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Exact match with next item lookahead: keep room for the incoming item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // this bin can't host the next item; slightly penalize blocking
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize more when many bins open or late in stream
        score += (open_bins_count as f64) * 2.5 + progress * 20.0;
        // but if no other bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // mild reward for consolidating into fewer bins
        score -= (open_bins_count as f64).sqrt() * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is near mean (balance)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let chain = (item_size + next_item_size) as f64;
        let diff = bin_residual as f64 - chain;
        if diff >= 0.0 && diff <= 10.0 {
            score -= 150.0; // perfect 2-item chain
        } else if diff < 0.0 {
            score += 30.0 + (-diff); // chain would overflow; penalize
        } else {
            score += diff * 0.3; // larger leftover after chain, mild penalty
        }
        // Exact match of post_residual to next item
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64 * 2.0);
        // If lookahead chains perfectly into a fresh bin, allow it.
        if next_item_size > 0 && bin_capacity as f64 - (item_size + next_item_size) as f64 <= 5.0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score -= 40.0 * (1.0 - fit_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0; // dead space blocks the next item
        } else if post_residual >= next_item_size && next_item_size >= item_size / 2 {
            score -= 15.0; // residual is usable by the upcoming item
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins can fit and mean residual is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming a fresh bin.
        score += 20.0;
        if fitting_bins_count > 0 {
            // An open bin exists that fits; only open a new bin if fits are poor.
            score += 30.0 + mean_residual * 0.3;
        }
        // Early in the stream, opening bins is cheaper (keeps options open).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If the next item is large, a fresh bin preserves flexibility.
        if next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Mild penalty for spreading across many bins when residuals are fragmented.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Favor bins whose residual deviates below the mean (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Time-horizon modulation: as stream nears end, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals more later);
    // later, tighter packing matters more.
    let progress_coupling = pr * progress * (1.0 - progress) * 4.0;
    score += 0.5 * progress_coupling;

    // Dead-space penalty: smooth polynomial in normalized residual
    let dead = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 30.0 * dead * (0.5 + progress);

    // Last-chance bonus: strongly reward using a bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let gap = ((next_item_size as f64) - pr).abs();
        if fits_next {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (gap / cap);
        }
    }

    // Mean-residual coupling: penalize when this bin's residual deviates badly from the mean
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / (cap * cap) * 100.0;

    // Congestion pressure: many open bins -> favor consolidation (higher score for new bins)
    score += 0.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity
    let post = post_residual;
    let class = post % 10;
    // Dead-space classes: residuals in {1..9} are nearly unusable (items >=1 but small)
    if post > 0 && post < 10 {
        score += 40.0; // dead space penalty
    } else if class == 0 {
        score -= 12.0; // perfectly divisible residual, reusable by decade-sized items
    } else if post >= 10 && post <= 20 {
        score -= 6.0; // small residual still usable by small items
    }

    // Integer division thresholds: post_residual / 25 (quarter-capacity classes)
    let quarter = post / 25;
    match quarter {
        0 => score += 8.0,               // < 25 left: poor future utility
        1 => score -= 4.0,               // 25..49
        2 => score -= 8.0,               // 50..74: sweet spot
        _ => score -= 2.0,               // 75+: fine but maybe wasteful now
    }

    // Coupling with next item (lookahead): can next item fit into post_residual?
    if next_item_size > 0 {
        if post >= next_item_size {
            // perfect pairing: post_residual exactly matches next item or leaves good class
            let after_next = post - next_item_size;
            if after_next == 0 {
                score -= 20.0; // chain both items perfectly
            } else if after_next % 10 == 0 {
                score -= 10.0;
            } else if after_next < 10 {
                score += 5.0;
            }
        } else {
            // next item won't fit here; residual must hold later unknown items
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        // new bin: score = post_residual = capacity - item; penalize slightly so
        // it's chosen only when existing bins create worse dead space
        score += 10.0;
        // favor opening new bin for large items that leave a good harmonic class
        if post % 10 == 0 && post >= 20 {
            score -= 14.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post as f64 / bin_capacity as f64));

    // Mean residual coupling: if this bin is far below mean residual, it's a laggard — use it
    let dev = mean_residual - post as f64;
    if dev > 15.0 {
        score -= 6.0;
    } else if dev < -15.0 {
        score += 6.0;
    }

    // Many open bins: prefer filling existing ones over opening more
    if open_bins_count > 4 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable gap)
    // is heavily penalized, scaled by how small the gap is relative to the smallest
    // plausible item (1..100 interface, so treat ~1..15 as nearly unusable).
    let dead_zone: f64 = 15.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_zone {
        let severity = 1.0 - (post_residual as f64 / dead_zone);
        score += 40.0 * severity * severity;
    }

    // Perfect fit bonus: zero waste is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-but-usable fit reward: reward small positive residuals that remain usable.
    if post_residual > 0 && post_residual <= 30 {
        score -= 8.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Last-chance pressure: if this is the only bin that fits, opening a new bin
    // wastes the residual here; prefer using this bin unless dead space is huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins
    // (penalize opening new bins); with few open bins, new bins are cheaper.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize more when many bins are already open.
        score += 6.0 + 4.0 * bin_pressure;
        // But if the current item is large and would leave a bad gap elsewhere,
        // a fresh bin is attractive: reward slightly for large items.
        if item_size >= 70 {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward slightly more when open_bins_count is high.
        score -= 2.0 * bin_pressure;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item fits in post_residual, mild bonus; if it would be blocked, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean (already
    // tightly packed), using it further is fine; if far above mean (loose bin),
    // leaving it for other items may be better — mild penalty for using loose bins.
    let residual_f = bin_residual as f64;
    if residual_f < bin_capacity as f64 {
        if residual_f > mean_residual + 10.0 {
            score += 3.0;
        } else if residual_f < mean_residual - 10.0 {
            score -= 2.0;
        }
    }

    // Stream progression: early in the stream, be slightly more willing to open
    // new bins; late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can still fit next item comfortably
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize if it creates dead space
    else if next_item_size > 0 {
        score += 10.0 + (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Reward tight fits relative to mean residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize deviation from mean residual (avoid fragmenting uniform bins)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or no good bin exists
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 45.0 - 30.0 * poor_fit + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is exactly consumed or nearly consumed.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight * tight).max(0.0) * (1.0 - tight);

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize leaving moderate residual
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are used only when needed.
        score += 45.0;
        // If few bins fit, new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins slightly less.
        score -= 10.0 * progress;
        // If mean residual across open bins is small, opening new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with residual close to item (minimize waste) among open bins.
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
        // Slight preference for bins with residual below mean (denser bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    if open_bins_count > 4 {
        if !is_new_bin {
            score -= 2.0;
        } else {
            score += 2.0 * (open_bins_count as f64).ln();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (minimize post_residual strongly).
    // Late: residual waste matters even more, but keep smoothness.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let coupling = 1.0 + 2.0 * progress + 3.0 * prog2 + 1.5 * prog3;
    score += 0.35 * (pr * pr) / cap * coupling * 0.1;

    // Penalize very small unusable remainders (dead space) smoothly.
    let dead = 1.0 - (pr / cap).min(1.0);
    score += 20.0 * dead * dead * dead;

    // Reward last-chance bins (avoid opening new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
        } else {
            score += 2.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64 / cap).powi(2);
        let mean_gap = (mean_residual - item_size as f64).abs() / cap;
        score = cap * (1.0 - 0.8 * fit_quality) + 15.0 * mean_gap + 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (small, common sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly for unusable leftovers (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 * (10.0 - pr);
    }

    // Harmonic reward: leftover that is a divisor-friendly chunk (multiple of 10
    // or 25) can host many future item sizes; reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Modulo-4 class of post_residual: mid-range leftovers (10..=50) are the
    // most reusable; penalize very large leftovers less than mid leftovers.
    if post_residual > 50 {
        score -= 1.5; // big residual bins are flexible, keep them attractive
    } else if post_residual > 0 {
        // mid-range leftover: mildly penalize to prefer tight fits
        score += 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 1.0 + (next_item_size as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large and open-bin fits would create tiny dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 6.0 + 10.0 * (1.0 - progress);
        // opening a bin is more acceptable when item is large (>= 60)
        let size_bonus = if item_size >= 60 { -4.0 } else { 0.0 };
        // if open bins have lots of mean residual, discourage new bin
        let mean_pull = (mean_residual / cap) * 5.0;
        score += base + size_bonus + mean_pull;
    }

    // Tight-fit reward: exact fills are perfect.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward using a bin whose residual matches the next item well (lookahead).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate: penalize mildly, but allow it when mean residual is low
    // (existing bins are too full to be useful) or fit would leave dead space.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 0.0 };
        let _ = dead_space_penalty;
        score += 15.0 - mean_residual * 0.2;
    } else {
        // Prefer bins tighter than the average residual (best-fit flavor).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Bonus for exact two-item fill.
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        score += 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        if next_item_size > 0 && item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Time horizon: later in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Mild penalty for scattering across many open bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: smooth polynomial coupling of post_residual with progress.
    // Tight fits matter more as the stream progresses (less slack to waste later).
    let tightness = 1.0 - (post / cap);
    score -= 45.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that is too small for typical future items:
    // small but nonzero post_residual is wasted. Smooth penalty via exp-like term.
    let dead = if post > 0.0 { (1.0 - post / cap).max(0.0) } else { 0.0 };
    score += 12.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 18.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual when many bins are open (balance residuals),
    // with smooth coupling to progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (0.5 + progress);

    // Mild preference for reusing existing bins over opening new ones, stronger early.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else {
        // Harmonic-class penalty: post_residual mod small moduli reveals
        // "dead space" classes that rarely combine with future items.
        let pr = post_residual;
        let class_penalty = match pr % 10 {
            0 => -20.0,           // round residual, highly reusable
            1 | 2 | 3 => 15.0,    // awkward slivers
            4 | 5 | 6 => 5.0,
            7 | 8 | 9 => 10.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Integer-division thresholds: large leftover space is fine,
        // medium leftover space is the danger zone.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr > half {
            score -= 10.0;
        } else if pr > quarter {
            score += 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward heavily; if it nearly fits, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins
    // would leave very awkward residuals or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (post_residual % 10 >= 1 && post_residual % 10 <= 3) as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let base = 300.0
            - 60.0 * awkward
            - 40.0 * (item_size as f64 / bin_capacity as f64)
            - 20.0 * progress
            - 10.0 * pressure;
        // A fresh bin's raw score is its full capacity; shift it so that
        // it only wins when existing options are truly bad.
        score = base + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
    } else {
        // Mild preference for fuller bins among open candidates.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Slight tie-breaker toward bins below mean residual (keep spread balanced).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any item (1..=100)
    // are wasted. Penalize gaps in the "unusable" zone heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Small gaps that only tiny items can use — moderate penalty,
        // scaled by how small the gap is relative to capacity.
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fit for the lookahead item: strongly reward leaving exactly
    // next_item_size free.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else. Penalize the empty-bin call
    // (bin_residual == bin_capacity) unless open-bin pressure is low or the
    // fit is very bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Extra cost grows with number of open bins (fragmentation pressure).
        score += open_bins_count as f64 * 2.0;
        // If this bin is a last chance, opening new is very unattractive.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If the mean residual across open bins is large, there is slack
        // available elsewhere — discourage new bins.
        score += mean_residual * 0.3;
    } else {
        // Reward using bins that are already fairly full (low residual).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, tighten up: dead space matters more since
    // remaining opportunities to fill gaps are fewer.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits after current placement -> strong reward.
            let gap = post - nxt;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain fit bonus
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit -> penalize slightly, keep residual for others.
            score += 8.0 * ((nxt - post) / bin_capacity as f64);
        }
    }

    // Prefer leaving residuals that are broadly usable (near mean residual).
    let post = post_residual as f64;
    score += 0.5 * (post - mean_residual).abs();

    // Penalize tiny dead space that is hard to reuse.
    if post > 0.0 && post < 10.0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in stream: keep bins tight; late: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 20.0; // large items start fresh bins anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual as u32) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more when many open bins exist with slack.
        score += 20.0 + 0.5 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Late in stream, prefer filling existing bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Global slack pressure: if mean residual is large, prefer using slack-heavy bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Mild preference to balance bin count growth over time.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more
    // aggressively, since leftover space becomes less likely to be used.
    let progress_weight = 0.35 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= progress_weight * (cap - post) / cap;

    // Quadratic dead-space penalty: residuals that are too small to hold any
    // plausible item (10..80) are dead weight; penalize the "unusable window"
    // smoothly via a bump around the small-residual regime.
    let dead = (post / cap).powi(2);
    score += 12.0 * dead * (1.0 - post / cap);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward;
    // if next item leaves a tiny sliver, penalize mildly.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= 2.0 * ((mean_residual - post) / cap);

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score = cap - item_size as f64 + 8.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual small relative to item size.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic class logic: dead space that is unusable for typical items.
    // Class the post_residual by modulo bands against the capacity.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        // Too small for any item (min size 1..100 but typically >=10): penalty.
        score += (10.0 - dead) * 8.0;
    }

    // Next-item coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward if next item fits with small leftover (chained packing).
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap <= 10.0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: mild penalty for leaving large residual
            // that could have hosted the next item.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow.min(50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits
    // are bad. Make an empty bin attractive only for large items or when
    // residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / bin_capacity as f64;
        // Base penalty so open bins with decent fits win.
        score += 40.0 + 80.0 * (1.0 - progress);
        // If open bins are nearly full (low mean residual), opening is fine.
        score -= 120.0 * (1.0 - tightness);
        // Large items justify fresh bins.
        if item_size >= 60 {
            score -= 50.0;
        }
        if post_residual > 40 {
            score += 30.0; // fresh bin wasted on small item
        }
    }

    // Prefer filling bins that are already more depleted (small residual).
    score += 0.2 * (bin_residual as f64 - post_residual as f64).signum().max(0.0) * 0.0;
    score += (bin_residual as f64) * 0.05;

    // Slight preference for bins below mean residual (more packed).
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Congestion: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Harmonic modulo class bonus on post_residual (divisibility classes of 100).
    let pr = post_residual;
    if pr > 0 && (100 % pr == 0 || pr % 10 == 0) {
        score -= 25.0; // residual aligns with common size classes
    }
    if pr >= 50 && pr <= 60 {
        score -= 20.0; // half-capacity class is reusable
    }
    if pr >= 80 && pr < 90 {
        score += 10.0; // awkward large leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: post_residual in [1, 9] is unusable for
    // minimum-size items (sizes >= 10 in classic streams, but be safe with 1..9).
    if !is_new_bin {
        if post_residual > 0 && post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 4.0; // hard dead-space penalty
        }
        // Gap just below a mid-size threshold is semi-dead: [10,24] hard to reuse.
        if post_residual >= 10 && post_residual < 25 {
            score += 12.0 + 0.5 * (25 - post_residual) as f64;
        }
    }

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 && !is_new_bin {
        score -= 30.0;
    }

    // Perfect-fit lookahead: if the next item exactly matches post_residual,
    // this bin becomes ideal; if next item cannot fit, residual is likely dead.
    if next_item_size > 0 && !is_new_bin {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: only fitting bin — strongly prefer using it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 40.0;
    }
    // But if the fit is terrible (large dead space), let new-bin win.
    if !is_new_bin && fitting_bins_count == 1 && post_residual >= 25 {
        score += 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open,
    // so the empty-bin candidate loses unless its score is genuinely low.
    if is_new_bin {
        score -= 5.0; // slight base preference for consolidation when tight fits exist
        score += open_bins_count as f64 * 6.0;
        // Early in stream, opening bins is cheaper (future items can fill them).
        score -= (1.0 - progress) * 25.0;
        // If next item is large and no open bin can host both, new bin is fine.
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 10.0;
        }
    } else {
        // Prefer filling bins with low residual overall (consolidation).
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Mild tightness coupling: favor bins whose residual was small before placement.
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
