pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // If next item would fit the residual BEFORE placement but not after, penalize.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (empty-bin candidate gets a discount early, penalty late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
        score += 15.0 * progress;
    }

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage filling existing ones.
    if bin_residual != bin_capacity {
        score -= 0.3 * mean_residual;
    } else {
        score += 0.3 * mean_residual;
    }
    if open_bins_count > 3 && bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    // Penalize leaving exactly dead space that few future items can use
    // (small residuals < 10 are wasted space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild preference for bins with less residual among equal post-residuals.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: squared post-residual penalizes dead space quadratically.
    let mut score = norm_post * norm_post * cap;

    // Smooth cubic coupling of post-residual with stream progress:
    // late in the stream, waste matters more.
    score += 12.0 * norm_post * norm_post * norm_post * (progress * (1.0 - progress) * 4.0 + 0.5) * cap;

    // Reward tight fits: subtract when post-residual is small relative to item size.
    let item_f = item_size as f64;
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (item_f / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates below the mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * ((next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mildly penalize leaving awkward space.
        score += 4.0 * norm_post;
    }

    // Smooth new-bin incentive: prefer opening a fresh bin when this bin's
    // post-residual would be very small but hard to use, via smooth sigmoid-like term.
    let unusable = 1.0 / (1.0 + (norm_post * 10.0 - 3.0).exp());
    score += 10.0 * unusable * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division.
    // Residuals are grouped into classes of width 10 (capacity fractions).
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post_residual nonlinearly (quadratic waste penalty).
    score += (post_residual as f64) * (post_residual as f64) * 0.01;

    // Harmonic class bonus: post_residual divisible by common item sizes (10,20,25,50)
    // suggests the leftover remains reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 15.0; }
        if post_residual % 20 == 0 { score -= 10.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 50 == 0 { score -= 12.0; }
    }

    // Penalize dead space: leftover smaller than the minimum item size (1..100 unknown,
    // use a conservative threshold tied to item class).
    let min_usable = item_class.max(1) * 10;
    if post_residual > 0 && post_residual < min_usable {
        score += 40.0;
    }

    // Lookahead coupling: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item can also fit here: moderate reward proportional to slack
        score -= ((post_residual - next_item_size) as f64).min(30.0) * 0.5;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item won't fit leftover but fits another bin: mild penalty
        score += 5.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize so it is chosen only for bad fits elsewhere,
        // scaled by how many open bins already exist.
        score += 60.0 + (open_bins_count as f64) * 2.0;
        // But if current item is large relative to capacity, new bin is attractive.
        if item_size * 2 >= bin_capacity {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, favor compacting into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already tight — prefer using it (keeps large residuals open for big items).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

