    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward if the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item close this bin
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it uses leftover space
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * usage;
            // extra reward for near-exact match
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            if gap <= 5.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit in this bin's leftover: penalize dead space
            score += 8.0;
            // extra penalty if leftover is small enough to be wasted entirely
            if post_residual < 10 {
                score += 12.0;
            }
        }
    } else {
        // last item: strongly prefer the bin with least leftover
        score -= 40.0;
    }

    // Compare residual against mean across open bins.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual * 1.3 {
        // roomy bin: mildly discourage wasting it on small items
        score += (residual_f - mean_residual) * 0.15;
    } else if residual_f < mean_residual * 0.7 {
        // tight bin: encourage using it before it becomes dead space
        score -= 6.0;
    }

    // Last-chance bonus: only one bin fits this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer keeping the number of open bins low early on; opening new bins
    // is penalized via the new-bin candidate's post_residual being large,
    // but give a mild late-stream pressure to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: high post_residual already penalizes it; add
        // extra penalty unless no open bin fits well
        score += 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Scale by progress: later in stream, tighten packing more aggressively.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
