    // late in stream, avoid opening new bins even more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    // Prefer bins whose residual is close to item_size (best-fit flavor).
    score += 0.08 * (bin_residual - item_size) as f64;

    // Slight preference to keep number of open bins small.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, scaled non-linearly
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap; // normalized post residual
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range waste smoothly
    score += poly * cap * (0.4 + 0.6 * progress);

    // Reward tight fits more strongly as the stream advances
    score -= (1.0 - x).powi(3) * (item_size as f64 / cap) * 12.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (nxt / cap) * (1.0 - (pr - nxt).abs() / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference to consolidate into bins below mean residual
    score += (pr - mean_residual) * 0.05;

    // New-bin candidate: make empty bin moderately attractive only when it beats waste
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod capacity fractions.
    // Dead space = post_residual smaller than the smallest plausible item (1..100 unknown,
    // but tiny slivers below ~10 are usually unusable).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // penalize creating unusable sliver
    }

    // Class of post_residual modulo 25 (quarter-capacity harmonics).
    let r25 = post_residual % 25;
    score -= (25 - r25) as f64 * 0.5; // prefer residuals aligned to quarter classes

    // Integer-division thresholds: how many "next item" copies fit in the leftover.
    if next_item_size > 0 && post_residual > 0 {
        let copies = post_residual / next_item_size;
        if copies >= 1 {
            score -= 25.0 + 10.0 * copies as f64; // leftover can host upcoming item(s)
        } else {
            score += 20.0; // next item won't fit in leftover: dead space risk
        }
        // Harmonic coupling: next_item_size divides post_residual cleanly
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let crowded = open_bins_count as f64 * 8.0;
        let poor_fit = (bin_residual - item_size.min(bin_residual)) as f64;
        score = 30.0 + crowded * progress - poor_fit * 0.2;
        if next_item_size > 0 && next_item_size > post_residual && post_residual == 0 {
            score -= 10.0; // fresh bin guarantees room for lookahead
        }
        // Avoid opening new bins when an existing bin gives a near-perfect fit.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 500.0;
        }
    }

    // Mild preference for filling bins that are already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fitting tightly relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when it enables a good future fit,
    // otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0; // opening a bin sets up a near-perfect next fit
        } else {
            score += 15.0;
        }
    }

    // Lookahead coupling: penalize leaving a gap slightly larger than next item (wasteful).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 12.0;
    }

    // Late in stream, tighten up: dead space matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly/nicely into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(40.0); // exact match gets biggest bonus
    } else if next_item_size > post_residual {
        // Next item cannot follow here; penalize proportional to wasted potential.
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Penalize tiny dead space (unusable残) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tighter existing fits relative to mean residual.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if item is large or stream is young.
        let large_item_bonus = (item_size as f64 - 40.0) * 0.5;
        score -= 15.0 + large_item_bonus.max(0.0) - progress * 10.0;
    } else {
        // Existing bin: mild bonus for high utilization.
        score -= (bin_capacity - post_residual) as f64 * 0.05;
    }

    // Slight penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 15.0 + 2.0 * crowding * scarcity;

        // Late in the stream, opening new bins is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;

        // But allow new bin if item is large and would leave a very awkward residual elsewhere.
        if item_size >= bin_capacity / 2 && next_item_size > post_residual.max(1) {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (spread load evenly).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight bias toward filling fuller bins (best-fit flavor).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly penalize small residuals (keep space flexible).
    // Late in the stream: reward tight fits (small post_residual) more aggressively.
    let early_w = (1.0 - progress) * (1.0 - progress);
    let late_w = progress * progress;

    // Quadratic dead-space penalty, modulated by progress.
    score += 0.8 * norm_pr * norm_pr * cap * (0.3 + late_w);

    // Cubic term: strongly punish near-full-but-unusable residuals late.
    score += 0.5 * norm_pr * norm_pr * norm_pr * cap * late_w;

    // Smooth interaction: if the next item fits the post_residual, reward this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            let tight = 1.0 - (gap / cap);
            score -= 12.0 * tight * tight * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 3.0 * (-gap / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // Prefer bins that are scarcer in capacity among many candidates.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0) * early_w;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    let mean_term = mean_residual - pr as f64;
    score += 0.05 * mean_term * (0.5 + 0.5 * progress);

    // Mild penalty for proliferating open bins early on.
    score += 0.3 * (open_bins_count as f64) * early_w * norm_pr;

    // New-bin candidate handling: keep it competitive only for tight fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "dead zones"
    // (small residuals that few future items can use) are penalized.
    let dead_zone = post_residual < 10;
    if dead_zone {
        score += 25.0;
    }

    // Modulo-class reward: residuals divisible by common item granularities
    // (10, 20, 25) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
    } else {
        // Perfect closure is ideal.
        score -= 40.0;
    }

    // Fractional capacity classes: how full the bin becomes.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac > 0.9 { score -= 15.0; }
    else if fill_frac > 0.75 { score -= 8.0; }
    else if fill_frac < 0.5 { score += 10.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot use post_residual at all, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit
    // would be poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 18.0 * pressure;
        if post_residual < item_size as f64 * 0.5 {
            score -= 20.0; // fresh bin keeps lots of room
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps too small for the lookahead item when lookahead exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage proliferating bins unless needed.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely better
    // than a poor fit. Base penalty, reduced when all fits are tight/dead.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the best alternative would leave a tiny dead gap, allow new bin:
        // signal via mean_residual being low (bins mostly full) and many bins.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Slight preference for filling fuller bins (small residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
