pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 0.5 * progress);

    // Penalize dead space: residuals too small for any plausible item (items >= 1,
    // but small residuals below typical item sizes are wasted).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * fill;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state: many open bins with large mean residual -> encourage consolidation
    // into existing bins rather than opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate handling: it starts with a high base score so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; late, prefer filling.
        score -= (1.0 - progress) * 20.0;
        // If current item is huge relative to capacity, new bin is more acceptable.
        score -= item_size as f64 * 0.2;
        // If next item is also large, a fresh bin may serve both.
        if next_item_size >= item_size {
            score -= 8.0;
        }
        // Many fitting bins means no reason to open a new one.
        score += fitting_bins_count as f64 * 5.0;
    }

    // Mild preference for bins whose residual is close to item size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let prog2 = progress * progress;
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 25.0 * norm_pr * (1.0 - norm_pr) * progress * (1.0 + prog2);

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 18.0 * (0.5 + progress);
    }

    // Penalize deviating from mean residual (keep bins balanced)
    score += 4.0 * ((pr - mean_residual).abs() / cap) * (1.0 + progress);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > post_residual {
        score += 6.0 * progress;
    }

    // New-bin candidate: prefer it only when post_residual is large and stream is early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 20.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: split into capacity fractions.
    // Class boundaries at C/4, C/2, 3C/4 — residuals below C/4 are "dead space".
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    if post_residual == 0 {
        // Perfect fit: strongly favored.
        score -= 200.0;
    } else if post_residual < quarter {
        // Dead-space class: penalize proportionally; tiny residuals are worthless.
        score += (quarter - post_residual) as f64 * 1.5 + 30.0;
    } else if post_residual < half {
        // Second class: moderately useful space.
        score += 5.0;
    } else if post_residual <= three_quarter {
        // Third class: healthy residual, mild reward.
        score -= 10.0;
    } else {
        // Near-empty bin: keep it flexible.
        score -= 5.0;
    }

    // Lookahead compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward, scaled by how snug the chain is.
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack.min(40)) as f64 * 0.5;
        } else if next_item_size <= bin_capacity && post_residual < next_item_size {
            // Next item won't fit here: leftover space becomes dead for the lookahead.
            let waste = next_item_size - post_residual;
            if waste < quarter {
                score += waste as f64 * 0.8;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < quarter && post_residual > 0 {
            score += 15.0; // but a bad fit here still hurts
        }
    }

    // Many open bins: prefer consolidating into existing space rather than spreading.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20)) as f64 * 1.2;
    }

    // Mean residual coupling: a bin far below mean residual is a "ragged" bin;
    // filling ragged bins evens out the portfolio.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Stream progression: early on, keep bins flexible (favor large residuals);
    // late in the stream, prioritize closing bins out (favor small residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;
    score -= (1.0 - progress) * 8.0;

    // New-bin candidate: only attractive when this item would leave a truly
    // unusable sliver in every open bin, or no bins fit.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if post_residual < quarter {
            // New bin leaves 3/4 free — good if existing fit is bad.
            score -= 20.0;
        } else {
            score += 60.0; // prefer using an existing bin with decent fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of many open bins,
    // but make the empty-bin candidate less attractive when few bins are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: if next item exactly matches post_residual,
    // this bin is a perfect chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportional to leftover dead space after chain
            let chain_left = post_residual - next_item_size;
            score -= 20.0 - (chain_left as f64).min(20.0);
        } else {
            // next item does not fit: penalize leaving residual smaller than next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual against mean residual: bins with residual below mean
    // (tighter bins) are better targets; above-mean waste is penalized.
    let res = post_residual as f64;
    score += (res - mean_residual) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize new-bin candidate unless open bins are nearly saturated
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let saturation = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * saturation - 10.0 * progress;
        // But open a new bin if item is huge and no bin fits well
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference to fill bins with many open bins (consolidation pressure)
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (low post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= (slack_after_next as f64 / bin_capacity as f64) * 25.0;
        } else {
            // Next item won't fit here; penalize leaving awkward medium gaps.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += (next_item_size as f64 - waste) * 0.6;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many fitting bins: slight penalty for consuming scarce residual elsewhere.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Global state coupling: prefer filling bins when mean residual is low (stream nearing saturation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r_norm = mean_residual / bin_capacity as f64;
    score -= (1.0 - mean_r_norm) * progress * 15.0;

    // Late in the stream, be more aggressive about using open bins vs. opening new ones.
    if progress > 0.5 && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        let open_pressure = open_bins_count as f64 * 0.4;
        score += 20.0 + open_pressure - poor_fit * 12.0 - progress * 10.0;
    }

    // Discourage leaving dead space in the 1..10 unusable range.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: non-linear penalty on wasted space relative to capacity
    let waste_ratio = pr / cap;
    score += waste_ratio * waste_ratio * cap * 0.5;

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible; later, squeeze bins harder.
    let flexibility = pr * (1.0 - progress * progress);
    let squeeze = pr * progress * progress * 0.8;
    score += flexibility * 0.3 - squeeze;

    // Penalize bins whose residual deviates strongly from the mean (imbalance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item could exactly fill post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (next_item_size as f64 - pr).abs() / cap;
        score -= 15.0 * (1.0 - perfect) * (1.0 - perfect);
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use: mild penalty growing with progress
        score += 4.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        let new_bin_cost = 30.0 - 20.0 * fragmentation * fragmentation - 15.0 * progress;
        score += new_bin_cost.max(-5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong reward for tight fits (harmonic classes of post_residual).
    // Class 0: perfect fit
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 150.0;
    } else if post_residual <= 40 {
        score -= 40.0;
    } else if post_residual <= 60 {
        score -= 10.0;
    } else {
        // large leftover: dead-space risk
        score += 30.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual,
    // penalize otherwise (chained placement potential).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin: valuable
            let chain_quality = (post_residual - next_item_size) as f64;
            score -= 80.0 - chain_quality * 0.5;
        } else {
            // next item won't fit here: leftover becomes dead space
            score += 60.0;
            // extra penalty proportional to unusable gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize opening a new bin when others fit,
    // unless this bin is the only fitting one or item is large.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count > 0 {
            score += 250.0 - pressure * 100.0;
        } else {
            score -= 100.0;
        }
        // mild discount late in the stream when many bins open
        score -= (open_bins_count as f64).sqrt() * 5.0;
    }

    // Modulo / integer-division thresholds on post_residual:
    // leftover values that are classic "hard residues" (e.g. 51..=59, leaving
    // nothing placeable for min items) get extra dead-space penalty.
    let hard = post_residual / 10; // integer division class
    if hard >= 5 && hard <= 5 && post_residual % 10 != 0 {
        score += 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins
    // get filled first), gently.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Stream progression: early on, be pickier about tight fits; late, just fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            // Unusable sliver: almost pure dead space.
            score += 60.0;
        } else if pr < 25 {
            // Only very small items (rare) can use this.
            score += 25.0;
        } else if pr < 45 {
            // Moderately risky gap.
            score += 8.0;
        } else {
            // Healthy residual, mild bonus for keeping usable space.
            score -= 5.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin residual (fractional fill).
    let fill_fraction = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_fraction;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        // Existing bin: reward more when many bins are open.
        score -= 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize proportionally to open bins so we only
        // open a new bin when no decent fit exists.
        score += 5.0 * open_bins_count as f64;
        // Allow new bin only if current item leaves a large residual or few bins open.
        if post_residual < 30 && open_bins_count > 2 {
            score += 30.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (consolidate the fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == pr {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item still fits: mild reward.
        score -= 5.0;
    } else if next_item_size > 0 && pr > 0 && next_item_size > pr {
        // This placement strands a gap smaller than the next item.
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: quadratic waste penalty (dead space is superlinear bad).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Perfect/near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Lookahead chaining: if the next item fits into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely; reward proportionally to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.15 * nest;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would have fit now but not after placement: mild penalty.
            score += 4.0;
        }
        // If next item is large and this bin keeps a medium residual, slight bonus
        // (keeps flexible space for big items elsewhere? no—penalize blocking).
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 3.0; // tiny dead space that blocks next item
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity identifies it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so open bins with decent fits win.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Progression: late in stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // But allow opening a new bin for very large items that would leave
        // unusable slivers in existing bins (post_residual small => big item).
        let big_item_bonus = if item_size >= 60 { (item_size - 60) as f64 * 1.2 } else { 0.0 };
        score -= big_item_bonus;
        // If many bins are open and mean residual is fragmented, new bin is fine.
        if mean_residual > 25.0 && open_bins_count > 3 {
            score -= 10.0;
        }
        // Last item: no lookahead value; closing with new bin is pointless.
        if next_item_size == 0 {
            score += 50.0;
        }
    } else {
        // Existing bin: mild reward when its residual is close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: many open bins -> favor filling existing ones harder.
    score -= 0.3 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth stream-progress coupling: tighten packing later in the stream
    let progress_coupling = 1.0 + 0.5 * progress * progress;
    score *= progress_coupling;

    // Penalize dead space relative to mean residual state (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if gap <= cap {
            let kernel = (1.0 - gap / cap).powi(3);
            score -= 6.0 * kernel;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for bin proliferation pressure
    score += 0.05 * open_bins_count as f64 * (0.5 + fill);

    // New-bin candidate: penalize slightly unless current residual is very tight
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // modulo buckets relative to capacity. Residuals that are "harmonic"
    // multiples of small divisors (e.g. multiples of 10, 25, 50) are more
    // likely to be filled by future items, so reward them (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Harmonic reward: post_residual divisible by common item sizes
    // (10, 20, 25, 50) is likely reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
        // Small dead-space classes (1..10) are hard to fill: penalize.
        if post_residual < 10 { score += 8.0; }
    } else {
        // Perfect fit is ideal.
        score -= 12.0;
    }

    // Non-linear waste term: dead space grows quadratically in the mid range.
    let waste = (frac * (1.0 - frac)).min(0.25); // peaks at frac=0.5
    score += waste * 16.0;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residual: mild reward
            let chain = post_residual - next_item_size;
            score -= 4.0;
            if chain % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here; penalize bins whose residual is
            // just barely too small (near-miss waste).
            let miss = next_item_size - post_residual;
            if miss <= 10 { score += 3.0 + miss as f64 * 0.3; }
        }
    } else {
        // Last item: prefer tightest fit, no lookahead needed.
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin has baseline score = capacity.
    // Make it attractive only when current bin fits are poor (high frac waste).
    if bin_residual == bin_capacity {
        // Neutral baseline with slight pressure to reuse open bins early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + progress * 10.0 + open_bins_count as f64 * 0.5;
        // If mean residual across open bins is large, prefer reusing them:
        score -= mean_residual * 0.05;
    }

    // Mild global pressure: many open bins -> encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item (<=10)
    // are pure waste; penalize them extra hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Gaps too small for the next item are also low utility.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (make the empty-bin candidate less attractive).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    } else {
        // Mild preference for tighter existing bins as bin count grows.
        score += 0.05 * open_bins_count as f64;
    }

    // Relative tightness coupling: prefer bins whose post-residual deviates
    // favorably from the mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Early in the stream, be slightly more willing to fill existing bins well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.35 * next_item_size as f64;
        } else {
            // Dead space penalty scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.25 * miss;
        }
        // Perfect 2-step chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is near the mean
    // (keeps residuals balanced), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins could still hold the item well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 40.0 * (1.0 - progress);
        // Still allow new bin if lookahead chain is impossible elsewhere (approximated
        // by large next item not fitting a fresh bin's typical residual).
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    }

    // Tight fit reward: small post-residual waste overall.
    if post_residual < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space relative to the smallest plausible item (1..100 range),
    // but only lightly so near-perfect fits still win.
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += 2.0 * (1.0 - waste / bin_capacity as f64).ln().abs().min(3.0);
    } else {
        score -= 8.0; // perfect fill
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is highly desirable (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * next_fit;
        } else {
            // Next item won't fit here anyway; slight penalty if we leave a large gap.
            score += 0.02 * post_residual as f64;
        }
    }

    // Global state: when mean residual across open bins is high, prefer using
    // existing space rather than opening new bins.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.05 * residual_gap;

    // Time horizon: early in the stream, be more conservative about filling bins
    // tightly (keep flexibility); late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.03 * post_residual as f64;
    score -= progress * 3.0 * fit_ratio;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it progressively with open bin count.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to mean residual, new bin is attractive.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 4.0;
        }
        // If next item is small, a fresh bin gives it room too.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 2.0;
        }
    }

    // Mild diversity term: with many open bins, prefer consolidating into bins
    // whose residual is below average (shrinking the tail).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = fit_norm * fit_norm * (1.0 + 2.0 * progress) - fit_norm * (0.5 + 1.5 * p2) + 0.25 * p3;
    score += 40.0 * coupling;

    // Penalize tight fits more strongly later in the stream
    let tightness = 1.0 - fit_norm;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Reward filling bins that are the last chance for this item
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post-residual still fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual, but not zero-waste extremes)
    if post_residual > 0 {
        score -= 8.0 * (1.0 - (post_residual as f64) / cap).powi(6);
    } else {
        score -= 20.0; // perfect fill
    }

    // Harmonic class penalty: post_residual classes modulo 10.
    // Residuals in [1,9] are nearly dead space; [10,19] can host small items.
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + cls; // unusable dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 2.0; // useful small-item slot
    } else if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0; // harmonically divisible residual, reusable
    }

    // Lookahead: reward if next item fits exactly-ish into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap).powi(3);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += (over / 10.0).floor() * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with below-mean residual (consolidate waste)
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // New empty bin candidate: neutral-ish baseline so it only wins over poor fits
    if bin_residual == bin_capacity {
        score = 55.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score = 0.0;
        }
    }

    // Early stream: be slightly conservative about fragmenting many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap is heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (assume ~1, but
    // practically gaps below ~10-15 are hard to reuse). Penalize quadratically in the dead zone.
    let dead_threshold = 12.0_f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 2.0;
    }
    // Zero residual is a perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect fit, very desirable
    }

    // Reward bins whose residual is close to the item (tight fit), regardless of exact zero.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Open-bins pressure: when many bins are open, prefer consolidating into existing ones;
    // penalize the new-bin candidate (bin_residual == bin_capacity) progressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 55.0 + pressure * 3.0;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless it would create severe dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // If next item would leave this bin's leftover dead anyway, mild penalty for wasting a good bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < dead_threshold {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - tightness / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 0.5 * post_residual as f64;
        }
        // Perfect 2-chain: current leftover exactly consumed by next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Relative residual coupling: prefer bins tighter than the mean
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when good fits exist among many open bins
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // a fresh bin still serves the next item well
        }
    }

    // Early stream: slightly discourage hoarding many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual is much worse than the average open-bin residual
    // (prefer packing into already-fragmented bins, keep clean bins for future items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.35 * residual_gap.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 40.0;
    }

    // Dead-space penalty: post residual that no future small item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item is larger than post residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 0.2 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    // Time horizon: early in the stream, be conservative with open bins
    // (favor consolidation); late in the stream, allow more new bins since
    // leftover capacity is less likely to be useful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate handling: empty bin should only win when the current fit
    // is bad (large post residual) or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        if fitting_bins_count >= 1 && !bad_fit {
            score += 45.0; // discourage opening a new bin when a decent fit exists
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // still prefer new bin over nothing, but mildly
        }
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - pr_norm;
    score -= (6.0 + 10.0 * progress) * tight * tight;

    // Penalize dead space below the smallest plausible item
    let dead = (item_size as f64 - pr).max(0.0) / cap;
    score += 25.0 * dead * dead;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer bins below mean residual slightly (balance spreading)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Lookahead: reward residual that can still host next item
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress);
        } else {
            score += 3.0 * (pr - next_item_size as f64).abs() / cap;
        }
    }

    // New-bin candidate: discourage early, allow when stream is advanced
    if bin_residual as f64 == cap {
        score += 10.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land in "usable" classes.
    // Class 0: post_residual == 0 (perfect fill) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals divisible by 10 are still reusable by typical items.
        let m10 = post_residual % 10;
        score += (m10 as f64) * 2.5; // penalize off-class dead space

        // Integer-division thresholds: classify residual into harmonic bands.
        let band = post_residual / 10; // 0..=10
        match band {
            0 => score += 40.0,          // tiny sliver: nearly dead space
            1 => score += 15.0,
            2 => score += 5.0,
            3 | 4 => score -= 5.0,       // sweet spot: fits small/medium items
            5 | 6 => score -= 10.0,      // prime reusable zone
            _ => score -= 3.0,           // large residual, fine
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if post_residual % next_item_size.max(1) == 0 {
            score -= 15.0; // harmonic divisibility: perfect future fill
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mildly penalize leaving awkward gaps.
        score += (post_residual.min(next_item_size) as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fits (already via post_residual).
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: neutral-ish baseline, only attractive when
    // current open bins would create bad fits (high mean residual spread).
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / bin_capacity as f64) * 100.0;
        // A fresh bin is good if item is large (leaves small post residual)
        // and existing bins are on average loose (wasteful to cram).
        let open_pressure = if open_bins_count > 0 {
            mean_residual / (open_bins_count.max(1) as f64)
        } else {
            0.0
        };
        score = tightness - open_pressure * 0.4 + 10.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Mild penalty for proliferating bins when a good fit exists elsewhere.
    if open_bins_count > 8 && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (<= ~10) are pure waste. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Residuals below the known minimum item size are unusable dead space.
    if post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + next_item_size as f64 * 0.2;
    }
    // If next item almost fits (small gap), mildly penalize creating a near-miss.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * (1.0 - tightness));

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0 + open_bins_count as f64 * 1.5;
        // If this is the only fitting option, opening new is fine.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 20.0;
    }

    // Mild preference for bins with below-average residual (keeps large gaps free).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Exact fit for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after the hypothetical next placement.
            let after_next = post - nxt;
            // Reward tight two-item packing; penalize growing leftovers.
            score -= 25.0 * (1.0 - after_next / bin_capacity as f64).min(1.0);
            score += 0.4 * after_next;
        } else {
            // Next item won't fit here: penalize dead space relative to mean residual.
            score += 0.3 * (nxt - post);
            score += 0.2 * (mean_residual - post).max(0.0);
        }

        // Lookahead coupling with mean residual: bins deviating far below mean
        // are less attractive unless they give an exact lookahead match.
        let deviation = (post - mean_residual).abs();
        score += 0.05 * deviation;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (good fresh utilization) and existing fit is poor.
    if bin_residual == bin_capacity {
        let utilization = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * utilization;
        // Penalize opening new bins when plenty of fitting bins exist.
        score += 6.0 * (fitting_bins_count as f64).min(4.0);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: best-fit term, normalized residual, non-linearly sharpened.
    let norm_pr = pr / cap;
    let mut score = norm_pr.powf(1.5 + 2.0 * progress) * cap;

    // Smooth coupling: residual quality vs stream progress — later in the
    // stream, tight fits matter more (dead space is costlier).
    score += (norm_pr * norm_pr) * (10.0 + 40.0 * progress);

    // Penalize bins whose residual is far from the mean (fragmentation signal),
    // smoothly scaled by how much the item consumes of the bin.
    let fill = item_size as f64 / cap;
    score += ((bin_residual as f64 - mean_residual).abs() / cap) * (1.0 - fill) * 8.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).powf(3.0) * (15.0 + 25.0 * (1.0 - progress));
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize, more so early when open bins are cheap to reuse.
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let class = post_residual % 10;
    // Residuals that pair badly with the 10..80 range get penalized.
    if class == 1 || class == 9 {
        score += 6.0; // dead space of 1 or 9 is nearly unusable
    } else if class == 3 || class == 7 {
        score += 3.0;
    } else if class == 5 {
        score += 1.5; // half-class: pairs with 5/15/... but rare sizes
    } else {
        score -= 2.0; // even / decade classes are reusable
    }

    // Integer-division threshold: small post_residual means bin is "closed well".
    if post_residual <= bin_capacity / 10 {
        score -= 8.0;
    } else if post_residual <= bin_capacity / 5 {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item exactly fills to a decade boundary
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here; bin will strand space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when current fit is poor and
    // many bins are already open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fit && open_bins_count > 2 {
            score -= 9.0 + 5.0 * progress;
        } else {
            score += 15.0; // keep filling open bins early
        }
    }

    // Mild pull toward bins below mean residual (balance residuals).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - pr) / 10.0; // hard-to-fill gap
        }
    } else {
        score -= 40.0; // perfect fit: fully close the bin
    }

    // Reward filling a bin that is the last chance for this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // this placement strands the lookahead item
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins whose residual deviates from mean (targeted placement).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    } else {
        // New-bin candidate: only attractive when nothing fits well.
        score += 35.0 + 5.0 * open_bins_count as f64 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is fine; large dead space penalized super-linearly.
    let pr = post_residual as f64;
    score += 0.05 * pr * pr / bin_capacity as f64;

    // Aggressive 2-step lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow: reward proportional to how snugly it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 + (slack_after_next as f64) * 0.2;
            if slack_after_next == 0 {
                score -= 200.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here: penalize, worse if gap is tiny (unusable).
            score += 40.0;
            if post_residual < next_item_size && post_residual < 10 {
                score += 50.0; // tiny dead space, unusable for typical items
            }
        }
    }

    // Compare post_residual against mean residual of open bins.
    if pr < mean_residual * 0.5 {
        score -= 10.0; // leaving this bin tighter than average is good
    } else if pr > mean_residual * 1.5 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin fits well (poor fit here) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64 && post_residual < 10;
        if poor_fit || fitting_bins_count == 0 {
            score -= 120.0; // open a new bin rather than fragment
        } else {
            score += 150.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Slight bias toward filling bins as the stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 5.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small dead space that likely nothing can use (items >= 1, but
    // residuals below the minimum item size are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // Strong bonus when post-residual AND bin fit both current and next item
        // (chain-friendly bin).
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 4.0 * (0.5 + progress);
    }

    // Relative fill: prefer bins that are already well-filled.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio;

    // New-bin candidate: only attractive when no open bin fits well
    // (poor fits exist) or mean residual is very low.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let low_residual_pressure = if mean_residual < item_size as f64 * 0.6 { 15.0 } else { -25.0 };
        score += 30.0 + poor_fit_pressure + low_residual_pressure - 10.0 * progress;
        // Late in the stream, opening fresh bins is safer for future items.
        if progress > 0.7 && mean_residual < 40.0 {
            score -= 12.0;
        }
    }

    // Mild bonus for exact complement with mean residual structure.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual penalized more as stream progresses
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 2.5 * norm_pr * (1.0 - progress) * progress;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: smooth interaction between post_residual and next item fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 - gap / cap;
        score -= 5.0 * fit_quality * fit_quality * (1.0 - progress);
        score += 3.0 * (gap / cap) * progress;
    }

    // Last-chance bin: strong smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln_1p() * norm_pr;
    }

    // Mean residual deviation coupling (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Mild penalty for opening new bins when many are open, smoothed by progress
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * (1.0 - progress)
            + 2.0 * (open_bins_count as f64).ln_1p();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how divisible / "reusable" the leftover is.
    let pr = post_residual;
    let pr_mod_10 = (pr % 10) as f64;
    score += pr_mod_10 * 0.8;                       // dead space not on a 10-grid is penalized

    // Perfect fit: zero leftover is gold.
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic thresholds: leftover that exactly admits common item classes (10..80 in steps)
    // is more valuable than arbitrary leftovers.
    let harmonic = |r: u32| -> f64 {
        // residual divisible by 10 => likely reusable by grid-distributed items
        if r > 0 && r % 10 == 0 { -8.0 } else { 0.0 }
    };
    score += harmonic(pr);

    // Fraction-of-capacity coupling: leftover in (0,10] is nearly dead space.
    if pr > 0 && pr <= 10 {
        score += 25.0;
    }
    // Leftover in the awkward 71..=99 band wastes most of a bin's capacity.
    if pr >= 71 {
        score += (pr as f64 - 70.0) * 0.5;
    }

    // Integer-division class of next item vs post residual: lookahead compatibility.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            // next item fits here afterwards: strong reward, scaled by how well it divides
            score -= 15.0 + (pr - nx) as f64 * -0.3; // prefer exact-ish follow-up
            if (pr - nx) <= 5 { score -= 10.0; }
        } else {
            // next item won't fit after this placement; penalize if it fits the bin now
            if nx <= bin_residual {
                score += 6.0;
            }
        }
        // harmonic class match: leftover equals a multiple related to next item
        if pr >= nx && pr % nx.max(1) == 0 && pr > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity.
    // Prefer it only when current placement would leave a bad class of leftover
    // or when the stream is early and consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: slightly favor reusing; late stream: opening fresh bins for big items ok
        score += 5.0 * (1.0 - progress);
        if item_size >= 70 {
            score -= 10.0; // big item: fresh bin is natural
        }
    }

    // Mean residual coupling: if the fleet average residual is high, discourage
    // leaving this bin far from the mean (keeps bin classes harmonized).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Modulo-4 class of item size: items on coarse grids pack better into
    // residuals on the same grid; reward alignment.
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if item_class == pr_class && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly/nearly host the next item (perfect chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain match: post_residual == next_item_size is ideal.
        score -= 30.0 * (1.0 - slack / (next_item_size as f64).max(1.0));
        // Bonus for exact match.
        if slack == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small to host the next item: penalize dead space,
        // scaled by how "wasted" the leftover is relative to capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste;
    }

    // Compare post_residual relative to mean residual: prefer bins that
    // become tighter than average (reducing fragmentation across the fleet).
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score += 0.5 * (post_residual as f64 - mean_post);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize selecting an empty new bin unless current bins have poor fits.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += scarcity + 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight progression term: later in the stream, be more conservative
    // with residual space (dead space matters more near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space (wasted slivers are hard to reuse)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bonus: only bin that fits -> strong reward to use it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 15.0;
        } else if (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) {
            score -= 8.0;
        } else {
            // next item won't fit here; mildly penalize leaving awkward residual
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or this is a poor fit elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin
        score += 18.0;
        // Attractive if many bins are nearly full (low mean residual)
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 30.0 * mean_fill;
        // Attractive late in the stream when consolidation matters less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // Less attractive if several bins already fit the item
        score += 6.0 * (fitting_bins_count as f64).min(4.0);
        // Perfect item for a fresh bin (large item on empty bin)
        if item_size >= bin_capacity * 9 / 10 {
            score -= 20.0;
        }
    } else {
        // Prefer fuller bins (smaller residual) among open bins
        score += 0.08 * (bin_residual as f64 - mean_residual);
        // Mildly discourage scattering across too many open bins early
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 8 && progress < 0.5 {
            score += 2.0;
        }
    }

    // Slight preference for bins whose residual stays reusable (>= next item or >= 10)
    if post_residual >= 10 && (next_item_size == 0 || post_residual >= next_item_size) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let poly = pn * pn * (1.0 - progress) + pn * progress * (1.0 - pn);
    score += 12.0 * poly - 4.0 * pn * pn * progress;

    // Reward tight fits more strongly as stream advances.
    score -= (1.0 - pn) * (1.0 - pn) * (1.0 + 3.0 * progress) * 6.0;

    // Penalize bins far from mean residual (fragmentation signal).
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that exactly wastes next item's fit.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.3 * (1.0 + progress);
    } else if next_item_size > 0 {
        score -= 2.0;
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * progress * progress - (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod 10 buckets.
    // Residuals in {0} are perfect; small residuals (1..10) are dead space.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;
    let fill = (bin_residual as f64) / cap; // how full the bin already is

    // Reward tight fits: lower score for small post_residual.
    score -= (cap - post as f64) * 0.15;

    // Harmonic class penalty: dead space that no future item (>=1) can use.
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    } else if post == 0 {
        score -= 40.0; // perfect closure
    }

    // Modulo-10 class coupling with next item: if next item exactly fills
    // post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // fraction of next item that fits; reward high utilization
            let frac = (next_item_size as f64) / (post_residual as f64);
            score -= 20.0 * frac;
        } else {
            // next item cannot fit here: penalize leaving a residue
            // that is in a "bad harmonic class" relative to next item
            let gap = (next_item_size - post_residual as u32) as f64;
            score += 5.0 + gap * 0.1;
        }
    } else {
        // last item: prefer closing bins perfectly
        score += post as f64 * 0.5;
    }

    // Integer division threshold: post_residual / 10 class.
    // Bins with post_residual in [10, 20) still fit the smallest items well;
    // penalize larger leftovers more mildly.
    let class = post / 10;
    score += class as f64 * 2.0;

    // Encourage using nearly-full bins (avoid spreading across many bins).
    score -= fill * fill * 15.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large or few bins fit it.
    if bin_residual == bin_capacity {
        let item_frac = (item_size as f64) / cap;
        let pressure = if fitting_bins_count > 0 { 0.0 } else { 50.0 };
        score = 100.0 - item_frac * 30.0 + pressure
            + (open_bins_count as f64) * 1.0
            - (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
    }

    // Mean residual context: when average residual is small, tighten more.
    score += (mean_residual - post as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        // Dead space becomes more costly as it approaches the threshold.
        score += 60.0 * (dead_threshold as f64 - post_residual as f64 + 1.0) / (dead_threshold as f64 + 1.0);
    }

    // Perfect fit reward: strong subtraction for near-zero waste.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post
    // residual, this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= dead_threshold {
            // Chaining would create new dead space — penalize mildly.
            score += 20.0;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // crowded or the fit would be terrible.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 4.0);
        score += 55.0 - 30.0 * crowding.min(2.0);
        // Opening a new bin is fine if the best alternative wastes a lot.
        if post_residual == bin_capacity as u32 - item_size.min(bin_capacity) {
            score += 5.0;
        }
    }

    // Open-bin count pressure: many open bins with large mean residual
    // suggests we should consolidate — favor bins below mean residual.
    if bin_residual as f64 > mean_residual {
        score += 8.0;
    } else {
        score -= 5.0;
    }

    // Slight pressure to reduce the number of open bins over the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Early stream: be a bit more tolerant of opening bins (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: dead space below next item size is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0; // perfect 2-step chain: next item exactly fills this bin
    }

    // Penalize residual that is too small to ever be useful (dead space)
    if post_residual > 0 {
        let min_useful = 10.0; // smallest plausible item
        if (post_residual as f64) < min_useful {
            score += 50.0;
        }
        // Small unusable-ish residuals are worse than large residuals of same waste
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        score -= 40.0; // perfect fill of current item
    }

    // Compare against mean residual: placing into a bin far below mean residual
    // concentrates waste; prefer bins with residual close to or above mean.
    let res_f = bin_residual as f64;
    score += 0.5 * (res_f - mean_residual).abs();
    if res_f > mean_residual + 20.0 {
        score -= 5.0; // big bins can absorb without creating tiny slivers
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // no open bin fits well, or stream is early (many items remain).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0; // default penalty for opening a new bin
        // Large items keep future flexibility; opening a bin for big items is ok.
        if item_size >= 60 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size && progress < 0.5 {
            score -= 15.0; // fresh bin helps upcoming large items early on
        }
        if progress > 0.8 {
            score += 20.0; // late stream: consolidate instead of opening
        }
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize large leftover space relative to bin capacity (wasteful placement)
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * post_frac * post_frac;

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize creating residual that the next item cannot use if it's small dead space
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins among many open bins (mild best-fit reinforcement)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Time horizon: as stream progresses, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    // Global residual pressure: if mean residual is high, tolerate spreading;
    // if mean residual is low, favor tight fits even more
    score += 0.1 * (mean_residual - post_residual as f64);

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But opening a new bin is attractive if it gives a good home to the next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized residual
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_post).powi(3) * 12.0 * (0.5 + progress);

    // Interaction: post_residual coupled with mean residual deviation
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more late (prefer packing into open bins)
    if bin_residual == bin_capacity {
        let base = 20.0 + 30.0 * progress * progress;
        // But if next item could combine with this item's residual, ease the penalty
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 <= post {
            -10.0
        } else {
            0.0
        };
        score += base + lookahead_bonus;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).sqrt() * 0.5 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into deciles of capacity.
    let harmonic_class = (post_residual * 10) / bin_capacity; // 0..=9
    let harmonic_penalty: f64 = match harmonic_class {
        0 => -30.0, // near-perfect fit
        1 => -18.0,
        2 => -8.0,
        3 => 2.0,
        4 => 6.0,
        5 => 10.0,
        6 => 12.0,
        7 => 14.0,
        8 => 15.0,
        _ => 16.0,
    };
    score += harmonic_penalty;

    // Reward tight fits via integer-division threshold on residual.
    let fit_tightness = bin_residual.saturating_sub(item_size);
    if fit_tightness <= 5 {
        score -= 20.0;
    } else if fit_tightness <= 10 {
        score -= 10.0;
    }

    // Dead-space coupling: post_residual that cannot host the lookahead item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize more when the wasted gap is small (harmonic classes of waste).
            let waste_class = (post_residual * 8) / bin_capacity;
            score += 4.0 + (waste_class as f64) * 1.5;
        } else if post_residual >= next_item_size {
            score -= 6.0; // bin stays usable for the next item
        }
    } else {
        // Last item: minimize post_residual aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin gets a baseline cost that open bins can beat.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 22.0;
        // If mean residual is large, prefer reusing open bins.
        new_bin_cost += (mean_residual / bin_capacity as f64) * 12.0;
        // Late in the stream, avoid spawning bins unnecessarily.
        new_bin_cost += progress * 6.0;
        // If many bins can fit, definitely don't open a new one.
        if fitting_bins_count > 2 {
            new_bin_cost += 15.0;
        }
        score += new_bin_cost;
    } else {
        // Mild bonus for keeping bin population stable.
        score -= 2.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (i.e., tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Modular threshold: residuals that are exact multiples of 5 leave "harmonious" gaps.
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for typical future items are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += 40.0 * (dead_threshold - post_residual as f64);
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Penalty if the leftover residual can't fit the lookahead item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packs)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Progress coupling: tighten standards as the stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else if fit_ratio < 0.05 {
        score -= 200.0;
    } else if fit_ratio < 0.15 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too; penalize leftover waste after hypothetical chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste.min(60.0);
        } else {
            // Next item does NOT fit here: dead space risk, penalize.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving a residual far below mean means this bin becomes hard to reuse.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score += (0.5 - rel) * 50.0; // bin becomes an outlier of tiny space
        } else if rel > 1.5 {
            score -= (rel - 1.5) * 10.0; // keeping large usable residual is fine
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly so tight fits
    // in existing bins win, but keep it competitive vs. bad fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheap/flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit core with slight superlinear penalty on wasted space.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * frac * frac;

    // Reward tight fits (small post residual) proportionally to fullness.
    let fullness = 1.0 - frac;
    score -= 4.0 * fullness * fullness;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize leaving tiny unusable residuals (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Global state coupling: when open bins are on average empty-ish, prefer filling
    // existing bins over opening new ones; when residuals are fragmented, allow new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: price of a new bin grows with open bin count and mean residual.
        score = 100.0 + 2.0 * open_bins_count as f64 - 0.5 * mean_residual;
        // If many bins can fit the item, discourage opening a new one.
        score += 8.0 * fitting_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If next item is large and this item is small, opening fresh bin may help.
        if next_item_size >= item_size.saturating_mul(2) && next_item_size > 0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward when mean residual is high (use up slack).
        score -= 0.05 * mean_residual;
        // Time-decay: early in stream, be pickier (leave room); later, pack greedily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 25.0 * norm_pr * progress * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (1.0 - nxt / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when bin residual deviates from mean residual (diversity shaping)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer consolidating into fewer bins
    score += 2.0 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill, strong reward
    } else {
        // classify residual into harmonic bands: tiny / small / medium / large
        let pr_frac = pr as f64 / cap;
        if pr_frac < 0.10 {
            score += 8.0; // dead space penalty
        } else if pr_frac < 0.25 {
            score += 2.0;
        } else if pr_frac < 0.50 {
            score -= 3.0;
        } else {
            score -= 6.0;
        }
        // modulo arithmetic: residuals divisible by common small item sizes stay usable
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 1.5; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 2.0; }
    }

    // Next-item lookahead: does the next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chain continuation reward
            // tighter chain is better
            let slack = (pr - next_item_size) as f64;
            score -= (1.0 - slack / cap) * 6.0;
        } else {
            score += 4.0; // next item won't chain here
            // harmonic class of next item vs residual gap
            let gap = (next_item_size - pr) as i64;
            if gap <= 10 { score += 3.0; } // near miss, wasted slot
        }
        // if next item is large and this bin barely fits current item, prefer elsewhere
        if next_item_size > 60 && pr < 20 {
            score += 5.0;
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin: baseline attractiveness = capacity minus item
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // room for the lookahead too
        }
        // early in stream, new bins are cheap; late, consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // many open bins: discourage opening more
        score += (open_bins_count as f64) * 0.8;
        // if only one fitting bin exists, strongly prefer using it
        if fitting_bins_count >= 1 {
            score += 8.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (fill emptier bins less,
    // keep balanced residuals for future flexibility)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    // Mild preference to use bins with fewer alternatives
    if fitting_bins_count > 3 {
        score += 1.0; // many options, less critical to use this one
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are "dead space" -> heavy penalty.
    let dead_threshold = 12u32; // below this, gaps are nearly unusable
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 40.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Penalize creating gaps that are dead relative to the lookahead item:
    // if next item can't use the leftover gap, that space is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap remains reusable by the next item: reward.
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins gets penalized via new-bin handling.
    let pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + pressure * 12.0;
        // Slightly cheaper to open a bin early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    } else {
        // Existing bin: mild reward scaled by how full the bin already is.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used * 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, use it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins with residuals below the mean (tighter bins), spreading
    // items across bins to keep residuals balanced and usable.
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item will fit here: reward proportionally to how snugly
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 + (slack_after_next as f64).min(20.0);
        } else {
            // Next item won't fit: penalize leftover dead space
            score += (post_residual as f64).min(30.0);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 25.0 + (item_size as f64) * 0.5;
        // If item nearly fills a fresh bin, opening is fine
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.2;

    // Penalize very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Reward when this bin can also host the lookahead item afterwards (perfect pair).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // Penalize leaving residual that exactly blocks the next item's useful range.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.10 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is tiny.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; more so late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 10.0 * progress;
        // But if all open bins would leave large dead space, opening is attractive.
        let best_existing_waste = if fitting_bins_count > 0 {
            (bin_residual - item_size).min(100)
        } else {
            100
        };
        if best_existing_waste > 40 {
            score -= 0.15 * (best_existing_waste - 40) as f64;
        }
        // If next item pairs well with the fresh bin after this item, slight bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Slight preference for filling bins that are already low on residual,
    // consolidating waste into fewer bins.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving many nearly-empty bins scattered.
    if open_bins_count > 3 && bin_residual as f64 > mean_residual + 30.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Reward tight fits: small post_residual relative to capacity, scaled by progress
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small unusable residuals (dead space), smoothly via cubic
    let dead = pr / cap;
    score += 8.0 * dead * dead * dead;

    // Non-linear coupling with mean residual: prefer bins close to mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        if pr >= nx {
            score -= 5.0 * (1.0 - fit_gap / cap).max(0.0);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Mild preference to fill existing bins as stream progresses (avoid bin proliferation)
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress) * (pr / cap);

    // Smooth polynomial stream-progress shaping of the base residual
    let poly = 1.0 - 1.5 * progress + 0.75 * progress * progress;
    score *= poly.max(0.25);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Dead-space classes: leftovers that are hard to reuse get penalized.
    // Small leftovers (1..=5) are nearly dead unless they are exact future fits.
    if post_residual <= 5 {
        score += 30.0;
    }

    // Harmonic quarters: leftover in (0, 25] is low utility, (25, 50] medium,
    // (50, 75] good, (75, 100) excellent.
    if frac <= 0.25 {
        score += 10.0 * (0.25 - frac) / 0.25;
    } else if frac <= 0.5 {
        score -= 5.0 * (frac - 0.25) / 0.25;
    } else {
        score -= 12.0 * (frac - 0.5) / 0.5;
    }

    // Modulo harmonic structure: leftover divisible by common item sizes (10, 20, 25, 50)
    // is reusable; reward those classes.
    let reusable = |r: u32| -> bool {
        r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0
    };
    if reusable(post_residual) {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            // Reward chain fits that keep residual in good harmonic classes.
            if reusable(nr) {
                score -= 10.0;
            }
            if nr == 0 {
                score -= 40.0;
            } else if nr <= 5 {
                score += 20.0; // chain would create dead space
            }
        } else {
            // Next item cannot follow here; leftover likely terminal.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late-stream pressure: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Prefer filling bins below mean residual (keeps bin set balanced).
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: neutral-ish score so it's chosen only when no open bin
    // offers a good harmonic fit. Base on capacity minus small bias.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 8.0;
        // Late stream: opening new bins is cheaper than dead space.
        if progress > 0.7 {
            score -= 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to
    // hold any plausible future item (unusable gap). Items are >= 1, but gaps
    // below a small threshold waste capacity almost surely.
    let dead_threshold = 4.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // unusable sliver: very bad
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: excellent
    }

    // Non-linear penalty on small-but-not-zero gaps (classic wasted space).
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += (12.0 - post_residual as f64) * 2.5;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap the next item cannot use (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing
    // bins (low post_residual) to consolidate; when few bins are open, mild.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Progress coupling: late in the stream, be stricter about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.08;

    // New-bin candidate: empty bin has full residual; make it attractive only
    // when current bin fit is poor (large post_residual or dead gap).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 > 15.0) || ((post_residual as f64) < dead_threshold);
        if poor_fit {
            score -= 20.0; // open a fresh bin instead of fragmenting
        } else {
            score += 30.0; // keep using existing bins on good fits
        }
    }

    // Slight preference toward bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chaining with next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 12.0 * tightness * tightness;
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 4.0 * (post / bin_capacity as f64);
        }
        // exact match bonus: next item fills bin perfectly
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // last item: minimize waste directly
        score = post_residual as f64 * 2.0;
    }

    // Relative-to-mean coupling: prefer bins with residuals near the mean
    // (keeps bin population homogeneous, avoids stranding outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size > bin_capacity / 2 { 6.0 } else { 0.0 };
        let no_alternative = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 + 8.0 * progress - large_item_bonus - no_alternative;
    }

    // Mild preference to fill emptier bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Tight-fit reward: small post residual is good.
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin, more strongly when other bins fit
        // and when we're late in the stream (consolidation matters more).
        let fit_pressure = fitting_bins_count as f64;
        score += 60.0 + 25.0 * fit_pressure + 40.0 * t + 0.5 * open_bins_count as f64;
        // If the item perfectly fills a fresh bin, allow it.
        if post_residual == 0 {
            score -= 200.0;
        }
        // If next item would perfectly fill the remainder, mildly favor new bin.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        }
        return score;
    }

    // Tightness reward: reward filling the bin nearly exactly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward residuals that the next item can still use,
    // penalize residuals that become dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: leave exactly what the next item needs.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item fits in leftover: partial reward proportional to use.
            let use_frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * use_frac;
        } else {
            // Leftover too small for next item: penalize dead space,
            // scaled by how small the leftover is.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0 + 30.0 * t;
    }

    // Penalize bins whose residual is far below the mean residual
    // (wasting a relatively full bin on a loose fit), unless tight fit.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.08 * dev;
    } else {
        score += 0.04 * dev; // negative dev => small reward
    }

    // Late-stream consolidation: mildly favor bins that are already
    // partially filled to close them out.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * t;

    // Small penalty for many open bins to encourage reuse.
    score += 0.3 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Non-linear coupling: quadratic penalty on wasted residual, softened by progress
    score += 0.35 * (fit_frac * fit_frac) * cap * (1.0 - 0.5 * progress);

    // Reward near-perfect fits with a smooth bell-shaped term
    let tightness = (pr as f64 - 0.0).exp() * (-(fit_frac * 12.0).powi(2)).exp();
    score -= 8.0 * tightness;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (-(gap / 20.0).powi(2)).exp();
    } else if next_item_size > post_residual {
        score += 1.5 * progress;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; favor filling existing bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless residuals are very tight
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * progress);
        // Allow new bin when mean residual is very small (nothing fits well)
        score -= (mean_residual / cap).max(0.0) * 20.0;
    }

    // Smooth interaction with mean residual: prefer bins below mean residual (more filled)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit style tightness, scaled
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: reward residuals in "reusable" classes.
    // Residuals divisible by 10 (or small enough to be filled by min item 1) are more useful.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit is excellent
    } else if pr < 10 {
        // dead space below minimum item size is nearly useless -> penalize
        score += 8.0;
    } else {
        // modulo classes: residuals that are multiples of common item sizes stay reusable
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 2.0; }
        // harmonic fraction: reward residual close to a capacity fraction that future items fill
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.4 { score += 6.0 * frac; } // large leftover = wasteful
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 5.0 + (pr - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here; slightly penalize hoarding space
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        // opening new bins early is cheap; late in stream prefer consolidation
        score = bin_capacity as f64 * (0.9 - 0.3 * progress);
        if fitting_bins_count == 0 { score -= 40.0; } // must open a bin
        if mean_residual < item_size as f64 { score -= 10.0; } // nothing useful fits anywhere
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Tie-break by open bin count: fewer bins better
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Strict dead-space avoidance ----
    // A gap is "unusable" if it is small: nothing typical (>=10) fits,
    // or only a narrow range of items could ever use it.
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Tiny slivers are almost certainly dead space: heavy penalty.
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Near-perfect fit reward (leave gaps that are still broadly usable).
    if post_residual >= 1 && post_residual <= 10 {
        score -= 12.0;
    }

    // ---- Coupling with lookahead ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: reward chain packing.
            score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Placing here strands the next item: penalize proportionally
            // to how much the next item overshoots the residual.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoiding a new bin is valuable.
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: prefer tighter fits via relative fill.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill_ratio;
    }

    // ---- Open-bin pressure ----
    // More open bins -> favor consolidating into existing bins,
    // penalize leaving moderate residuals scattered around.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) unless it is a perfect fit.
    if post_residual > 0 {
        score += 0.3 * ((post_residual as f64 - mean_residual).abs());
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 25.0 + 1.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is riskier (waste is locked in).
        new_bin_score += 20.0 * progress;
        // If the next item is small, a fresh bin can absorb both: soften cost.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 8.0;
        }
        // If no open bin fits at all (this call would be the only candidate),
        // fitting_bins_count reflects that; opening is mandatory-ish.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect fit: next item fits leaving minimal slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: post_residual too small for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with residual below mean (denser bins), penalize above mean
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Last-chance bin: strongly reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New empty bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened unless necessary
        score = bin_capacity as f64;
        if next_item_size > 0 && post_residual == bin_capacity - next_item_size {
            score -= 45.0; // next item pairs perfectly with a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // As stream progresses, mildly discourage proliferation of open bins
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (< 10 units dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for a combined near-perfect two-item packing.
            let combo = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * combo;
        } else {
            // Post residual can't hold next item: mild penalty scaled by wasted potential.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer using existing bins over opening new ones as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 8.0 + 10.0 * progress + 0.6 * open_bins_count as f64;
        // But if no existing bin fits well (item much larger than mean residual), ease opening.
        if (item_size as f64) > mean_residual + 5.0 {
            score -= 14.0;
        }
    } else {
        // Reward placing into bins whose residual is close to the global mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight preference for fuller bins when few bins are open (consolidation).
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(10) as f64) / 10.0;
    }

    // Late-stream pressure: avoid leaving many half-empty bins at the end.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits: quadratic coupling of fill level with stream progress.
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Penalize dead space that nothing can use (post_residual < 10 typically unusable),
    // expressed smoothly via a sigmoid-like term instead of a hard cutoff.
    let pr = post_residual as f64;
    let dead = 1.0 / (1.0 + (pr / 8.0).exp());
    score += 25.0 * dead * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
        // Perfect two-item packing bonus
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score -= 4.0 * (open_bins_count as f64).ln().max(0.0) * fill;

    // Penalize bins far from the mean residual (encourage balanced packing),
    // with a smooth cubic coupling to progress.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap * (0.3 + 0.7 * progress);

    // New-bin candidate: keep it competitive only when it truly beats tight fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..10) are excellent; large leftovers are waste.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold, classes 0..=10
    score += (class as f64) * 6.0;

    // Perfect fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Reward residual that is a harmonic fraction of capacity (25/50/75 style),
    // since future items in 1..100 often match such divisors.
    if pr > 0 && bin_capacity % pr == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is already low:
    // encourage tight packing by favoring bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless all else is bad.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 1.5;
        // Early in the stream, opening bins is cheaper; late stream, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for very large item relative to residual (tight squeeze risk).
    if item_size > bin_residual {
        score += 1000.0; // should not happen for fitting bins, safety
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: small unusable gaps are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect lookahead fit bonus: residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Lookahead can fit into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size <= bin_capacity && post_residual < next_item_size {
        // Next item cannot use this gap: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Prefer tighter bins (smaller residual before placement) mildly.
    score += (bin_residual as f64) * 0.1;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.2;
    }

    // Late-stream tightening: as stream progresses, avoid leaving loose gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mean residual coupling: penalize bins far below mean residual (wasteful picks).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff); // strong reward when next item fits perfectly
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-item packing of this bin
        }
        // Penalize post_residual that is too small to be useful for next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // Last item: minimize residual as much as possible
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize large dead space that nothing can use later (min item size 1..100 unknown; use 10 heuristic)
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny unusable sliver — good, it's "filled"
    }
    if post_residual >= 60 {
        score += 8.0; // large leftover — keep flexible, mild penalty
    }

    // New-bin candidate: neutral-ish baseline; open new bin only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && item_size as f64 > mean_residual * 0.9 && fitting_bins_count > 0 {
            score += 10.0; // poor fits everywhere, prefer fresh bin
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small unusable dead space (residual below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward placements that leave room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins when fit is poor);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into existing bins rather than opening new ones.
    if open_bins_count > 1 {
        score -= 0.5 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // New-bin candidate: penalize opening a new bin unless the fit into open bins is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with a non-linear (quadratic) waste term.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: waste matters more as the stream progresses.
    score += 40.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits with a smooth saturating-like polynomial of fill ratio.
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill * fill;

    // Lookahead: reward bins whose post-residual matches the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 25.0 * (-diff * diff * 8.0).exp() * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin, modulated smoothly.
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are high.
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // Mean residual coupling: penalize bins far from the fleet mean (smooth quadratic).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "useful"
    // divisibility classes (multiples of common item sizes) are worth keeping.
    let pr = post_residual;
    let useful = |r: u32| -> f64 {
        if r == 0 { return -8.0; } // perfect close
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if r % m == 0 { h += 2.5; }
        }
        if r <= 10 { h += 1.5; } // small dead space is tolerable
        h
    };
    score -= useful(pr);

    // Penalize residuals in awkward classes (prime-ish / odd slivers)
    if pr > 10 && pr < 20 && pr % 10 != 0 { score += 3.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 4.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here: residual likely wasted
            score += 2.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented (high mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 30.0 * frag - 10.0 * progress;
        // if next item is huge, fresh bin is attractive
        if next_item_size >= 60 { score -= 8.0; }
    }

    // Slight preference for tighter bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Mild tie-break noise-free deterministic jitter by harmonic class
    score -= ((pr % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (1..100 range, but small gaps < 10 are
    // almost certainly dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Moderate penalty for gaps that can only fit tiny items (10..=20),
    // scaled by how close they are to being useless.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0 + (20 - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward fits that leave room for the known next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.2;
    }
    // Penalize if post_residual is a tempting but insufficient gap for next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: baseline cost grows with number of open bins.
        score += 15.0 + pressure * 3.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
    }

    // Prefer bins whose residual is closest to item (tightness tie-break).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 200.0 / (1.0 + diff as f64);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 50.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mild penalty for opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin useful if next item is big
        }
    }

    // Progression: later in stream, slightly prefer consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize dead space: residuals too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 30.0 * (1.0 - leftover as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here after placement; slight penalty.
        score += 8.0;
    }

    // Perfect closure bonus: filling bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // with residuals below mean (compact them), penalize bins above mean.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // When few bins fit the item, discourage wasting a scarce candidate on a loose fit.
    if fitting_bins_count <= 2 && fit_ratio > 0.4 {
        score += 15.0 * fit_ratio;
    }

    // New-bin candidate: keep it competitive only when current fit is poor
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / 20.0).min(1.0);
        score = 30.0 + fit_ratio * 20.0 - openness * 25.0 + progress * 15.0;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when only one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.5 * t * t);

    // Quadratic penalty on large residuals, modulated by progress
    score += cap * (x * x) * (0.8 + 1.2 * t);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= cap * (1.0 - x) * (1.0 - x) * (0.5 + 1.5 * t);

    // Penalize bins with residual far above mean (dead space divergence)
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * t;
    }

    // Lookahead coupling: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - next_item_size as f64).max(0.0);
        score -= fits_next * (gap * 0.6 + 5.0) * (0.5 + t);
        // penalize leaving residual that almost-but-not-quite fits next item
        let almost = ((next_item_size as f64) - pr) / cap;
        if almost > 0.0 && almost < 0.15 {
            score += 20.0 * (0.15 - almost) / 0.15;
        }
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - t) - (open_bins_count as f64).min(10.0);
        // new bin is attractive if item is large relative to capacity
        score -= (item_size as f64 / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity fractions (1/2, 1/3, 1/4) — residuals landing exactly on these
    // class boundaries are highly reusable, so reward them strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual == bin_capacity / 2 {
            score -= 12.0;
        } else if post_residual == bin_capacity / 3 {
            score -= 9.0;
        } else if post_residual == bin_capacity / 4 {
            score -= 6.0;
        }
        // Integer-division threshold: leftover in the lowest harmonic band
        // (<= 10) is near-dead space; penalize proportionally.
        if post_residual <= bin_capacity / 10 {
            score += 8.0 * (1.0 - pr / cap);
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 25.0;
    }

    // Modulo coupling: if next item divides evenly into post_residual
    // (post_residual % next == 0), this placement sets up a perfect chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
        // If next item fits exactly, huge reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this leftover: leftover likely becomes dead.
        score += 4.0 * (pr / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // existing bins would leave very poor residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap - item_size as f64; // residual of new bin after placement
        // Early stream: prefer filling existing bins; penalize new bins.
        score += 20.0 * (1.0 - progress);
        // If many bins are open with slack, opening another is wasteful.
        score += 2.0 * open_bins_count as f64;
        // If the new bin would be exactly half-used, that's a decent class.
        if item_size == bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mild pressure to prefer tighter existing bins relative to mean slack.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize medium dead space quadratically.
    if post_residual >= 10 && post_residual < 25 {
        score += (post_residual as f64 - 9.0) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // Opening a bin is acceptable if it enables a good future fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead coupling: favor bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }
    // Penalize leaving a gap just under the next item size (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Stream progression: later in stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            // Perfect chain: next item exactly fills post_residual -> big reward.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Proportional reward for tight chain fit.
                let chain_util = next_item_size as f64 / post_residual as f64;
                score -= 40.0 * chain_util;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted chain opportunity.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    } else {
        // Last item: strongly reward tight fits (small post_residual).
        score += 0.0;
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins can fit reasonably well,
    // unless post_residual would be very small (tight fit) there.
    if bin_residual == bin_capacity {
        // New-bin candidate: base preference against opening unless existing fits are bad.
        score += 15.0;
        // If next item is large relative to a fresh bin's usefulness, slight adjustment.
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small penalty for very small unusable post_residual that's not zero (dead space),
    // but zero residual is a perfect fit and should be heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 10 {
        score += 8.0; // awkward sliver of dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
