pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let npr = (post_residual as f64) / cap.max(1.0);
    let fit = if fitting_bins_count == 0 { 1.0 } else { fitting_bins_count as f64 };
    let scarcity = 1.0 / fit;
    let next = next_item_size as f64 / cap;
    // smooth polynomial coupling of post residual with progress
    let poly = (1.0 - progress) * (1.0 - progress);
    // penalize large post residual early (waste), reward tight fits late
    score += 6.0 * npr * npr * poly;
    score -= 3.0 * npr * progress;
    // last-chance bonus
    score -= 4.0 * (fitting_bins_count == 1) as i32 as f64;
    // lookahead: reward if next item fits residual
    if next > 0.0 && next <= pr {
        score -= 2.5 * next * (1.0 - poly);
    } else if next > pr {
        score += 1.5 * poly;
    }
    // mean residual coupling: penalize deviating far from mean
    score += 0.8 * ((post_residual as f64 - mean_residual) / cap).abs();
    // mild scarcity penalty
    score += 0.5 * scarcity * npr;
    // new-bin candidate: prefer keeping item in open bins unless residual very tight
    if bin_residual == bin_capacity {
        score += 1.2 + 2.0 * progress * (1.0 - item_size as f64 / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets
    // using integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual <= 10 is a "dead sliver" (unusable for
    // typical items) -> reward closing the bin tightly.
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 40 {
        score -= 5.0;
    } else {
        // Large post residual: penalize extra, quadratically.
        score += (post * post) / (cap * 2.0);
    }

    // Modulo arithmetic on post_residual relative to common item sizes:
    // if the leftover is exactly reusable by a "harmonic" small class
    // (multiples of 10/20/25), the space stays usable -> reward.
    let harmonic_reuse = post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0;
    if harmonic_reuse && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a chain fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Next item cannot use leftover: penalize proportional to gap.
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item is large and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 50.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 120.0;
        }
        // If mean residual across open bins can absorb the item comfortably,
        // discourage the new bin.
        if mean_residual > item_size as f64 * 1.5 {
            score += 60.0;
        }
        // Late in the stream with few open bins, opening fresh is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && open_bins_count < 3 {
            score -= 40.0;
        }
    }

    // Slight preference for fuller bins (lower residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

