    if post_residual < 10 {
        score -= 40.0; // perfect fill, treat as zero waste
    } else if post_residual < item_size {
        // gap can't fit the current item again; mild penalty scaled by gap size
        score += 0.5 * post_residual as f64;
    }

    // Exact-fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the resulting gap, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 6.0; // blocks the next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin, but less when it would be nearly full or few bins fit
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * pressure;
        if post_residual < 10 {
            score -= 50.0; // opening a bin that gets filled almost exactly is great
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= (post_residual as f64) * 0.8 - (leftover as f64) * 0.6;
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.4;
        }
    }

    // Relative residual coupling: prefer bins tighter than the mean.
    let dev = mean_residual - (post_residual as f64);
    score -= dev * 0.5;

    // Penalize very loose bins (wasting space in a roomy bin).
    if post_residual as f64 > mean_residual * 1.5 && post_residual > 20 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
