        score += 25.0;
        if item_size >= 60 {
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in the stream, tighten up: discourage opening bins / big leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good; large post_residual is wasted space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = if post_residual == next_item_size { 20.0 } else { 8.0 };
        score -= exact;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; mild penalty for leaving awkward residue.
        score += 3.0;
    }

    // Prefer using existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Compare against mean residual: bins with residual far below mean are scarcer, favor filling them.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.15;
    }

    // Avoid leaving residuals that are too small to be useful for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = post / cap;

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = 60.0 * fit_norm.powf(1.7) + 15.0 * fit_norm;

    // Perfect-fill reward (smooth, no piecewise)
    score -= 25.0 * (-fit_norm * 40.0).exp();

    // Stream-progress coupling: later in the stream, tighten more aggressively
    score += 20.0 * progress * fit_norm * fit_norm;

    // Interaction between post_residual and mean residual: penalize bins that
    // are much tighter than average (waste) or much looser (hoarding space)
    let mean_norm = mean_residual / cap;
    let dev = fit_norm - mean_norm;
    score += 10.0 * dev * dev;

    // Lookahead: reward if next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - ((post - nxt) / cap)) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - fit_norm);
    }

    // New-bin candidate: penalize mildly, less so when many bins are open
    // and residuals are loose (fragmentation pressure)
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).ln() * mean_norm;
        score += 25.0 - 10.0 * fragmentation.min(2.0);
    }

    // Slight penalty for very many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64).powf(0.8);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of 10 are "usable slots"
    let harmonic = (post_residual % 10) as f64;
    // Penalize post-residuals whose residue makes them awkward (dead space far from a round slot)
    if post_residual > 0 {
        let awkward = (harmonic - 5.0).abs() / 5.0; // 0 when residue=0 or 10, 1 when residue=5
        score += awkward * 8.0;
    }

    // Reward exact fits and near-exact fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic pairing: does post_residual form a good slot for the lookahead item?
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_leftover = post_residual - next_item_size;
        score -= 15.0 + (pair_leftover % 10) as f64 * 0.8;
    } else if next_item_size > 0 {
        // lookahead cannot use this bin's remainder: dead space risk
        score += (next_item_size as f64) * 0.15;
    }

    // Integer-division threshold classes on post_residual
    let slot_class = post_residual / 10; // 0..10
    // Larger slot classes (more room) are mildly preferable for future big items
    score -= slot_class as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        // Prefer opening a new bin when mean residual across open bins is small
        // (open bins are nearly full) or when no bin fits well
        score -= mean_residual * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in the stream, avoid opening new bins more aggressively
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Mild pressure against accumulating many open bins with large mean residual
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (typical items are >= 10, but small items 1..10 exist) are
    // heavily penalized as unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving residuals that the lookahead item can exactly use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize residuals the next item cannot use (wasted space from lookahead view).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (penalize opening new bins implicitly by rewarding reuse).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with below-mean residual (keeps large residuals available
    // for future large items).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is attractive only when
    // remaining open space is fragmented/low; otherwise penalize it so we
    // consolidate into existing bins.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        if mean_fill > 0.35 {
            score += 25.0 + 40.0 * mean_fill;
        } else {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize large post-residuals that are too small for typical future items,
    // but reward residuals that can still host a decent item.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // dead space penalty
    } else if pr >= 20.0 && pr <= 60.0 {
        score -= 4.0; // usable space
    }

    // Lookahead: reward if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            // next item won't fit here; mild penalty if this wastes the chain
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: neutral baseline, penalized when many open bins
    // exist with adequate mean residual (fragmentation avoidance).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9
            + 2.0 * open_bins_count as f64
            - 10.0 * progress
            + if mean_residual > item_size as f64 { 8.0 } else { -4.0 };
    } else {
        // Slight preference for fuller bins among open ones.
        score += 0.15 * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Global state: when many bins are open and mean residual is low, prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual < 25.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Time horizon: early in the stream, be more willing to open bins (cheap);
    // late in the stream, squeeze everything in.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: post residual (tighter fit -> lower score)
    let mut score = pr;

    // Non-linear coupling of residual with stream progress:
    // later in the stream, small residuals are more valuable (encourage tight packing early-mid)
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Polynomial interaction: penalize residuals that are too small to be useful later
    let useless = if next_item_size > 0 && pr < next_item_size {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };
    score += 20.0 * useless * (1.0 + progress);

    // Reward bins whose post residual matches the next item well (smooth kernel)
    let match_term = if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        d * d
    } else {
        0.0
    };
    score -= 8.0 * (1.0 - match_term.min(1.0));

    // Smooth penalty for opening new bins when many bins fit (coupled with progress)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (1.0 - progress * 0.5);

    // Mild penalty proportional to open bins count, smoothed by mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // Encourage large item placement into fuller bins (smooth quadratic)
    score -= 5.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: make it moderately attractive only when residuals are poor
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 12.0 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into buckets of 10.
    let bucket = post_residual / 10;
    score += (bucket as f64) * 0.7; // mild penalty scaled by dead-space class

    // Perfect/near-perfect fit reward: post_residual in {0,1,2,5,10}
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual == 5 {
        score -= 25.0;
    } else if post_residual == 10 {
        score -= 15.0;
    }

    // Modulo harmony: post_residual divisible by next_item_size means lookahead fits exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual % next_item_size == 0 {
                score -= 30.0;
            }
            // lookahead can fit here: reward proportional to how much it consumes
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else {
            // lookahead cannot fit: penalize small residuals that become dead space
            if post_residual < next_item_size {
                score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
        }
    }

    // Integer-division threshold on bin_residual: bins below half-full are flexible.
    if bin_residual * 2 >= bin_capacity {
        score -= 6.0;
    }

    // Capacity fraction coupling: reward filling toward harmonic fractions of capacity.
    let used = bin_capacity - bin_residual + item_size;
    let frac100 = used * 100 / bin_capacity; // percent used, integer division
    if frac100 >= 90 {
        score -= 18.0;
    } else if frac100 >= 75 {
        score -= 10.0;
    } else if frac100 >= 50 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless existing
    // bins are crowded and this item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else {
            // open new bin if item is big and mean residual is small
            let big = item_size as f64 / bin_capacity as f64;
            let crowded = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
            score -= 45.0 * big * crowded;
            if fitting_bins_count == 0 {
                score -= 80.0;
            }
        }
    }

    // Stream progression: late in the stream, tighten packing (favor tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: avoid leaving residual far from the mean (outlier gaps).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // Dead space = post_residual that is too small to hold any plausible future item.
    // Thresholds calibrated around minimum item size (1) and common small sizes.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 5 {
        // Nearly dead space: heavy penalty (unusable sliver).
        score += 45.0;
    } else if post_residual <= 10 {
        // Small gap: moderate penalty.
        score += 20.0;
    } else if post_residual <= 25 {
        // Medium gap: mild penalty, still usable for small items.
        score += 5.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        // Gap that leaves near-dead space after the next item fits: mild penalty.
        score += 8.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize opening new bins / spreading items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.15;

    // Mean residual coupling: if this bin's residual is far below the mean
    // (i.e., it's already tight), reward using it; if it's much larger than
    // mean, using it leaves the emptier bins stranded -> penalize slightly.
    let this_residual = post_residual as f64;
    if this_residual < mean_residual {
        score -= (mean_residual - this_residual).min(50.0) * 0.25;
    } else {
        score += (this_residual - mean_residual).min(50.0) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer
    // it when no open bin offers a decent fit — i.e., when the best possible
    // post_residual in an existing bin would be a dead-space sliver.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (proliferation).
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a new bin is reasonable: reduce penalty.
        if mean_residual < 8.0 {
            score -= 25.0;
        }
        // If current item is large relative to capacity, new bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Tightness reward: the fuller the bin gets (small post_residual relative
    // to capacity), the better — best-fit flavor with strict dead-space bias.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Small non-linear coupling: penalize quadratic dead space for gaps in the
    // awkward 1..15 range to make the heuristic strictly avoid unusable gaps.
    if post_residual >= 1 && post_residual <= 15 {
        score += ((15 - post_residual) as f64).powi(2) * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits: mild bonus proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 60.0 - (after_next as f64) * 0.5;
        } else {
            // next item doesn't fit: penalize small post residuals that waste space
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.8;
        }
    }

    // Penalize post residuals that are too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Late in stream: encourage closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual with a super-linear penalty.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small unusable residuals (< next item size and < 10).
    if post_residual > 0 && post_residual < next_item_size.max(10) {
        score += 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_fit;
    }
    // If next item won't fit here, mild penalty for wasting the slot.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: many open bins -> prefer filling existing ones (penalize new bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Global residual state: if mean residual is high, tighten packing more aggressively.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: early on, be more selective (larger residuals tolerated); late, pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild penalty on large residuals (keep space flexible).
    // Later: strong reward for tight fits (waste becomes permanent).
    let tight = (pr / cap).powi(2);
    score += 40.0 * progress * tight;
    score -= 25.0 * (1.0 - progress) * (1.0 - tight);

    // Reward exact / near-exact fits with smooth exponential shaping.
    score -= 30.0 * (-(pr / cap) * 8.0).exp();

    // Fragmentation pressure: if this bin's residual is far below mean,
    // it is hard to fill later -> favor using it now.
    let frag = (mean_residual - pr) / cap;
    if frag > 0.0 {
        score -= 20.0 * frag * (1.0 + progress);
    } else {
        score += 10.0 * (-frag) * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that barely fails the next item,
    // reward leaving room for it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - ((pr - nx) / cap)) * (1.0 - progress);
        } else {
            let gap = nx - pr;
            score += 15.0 * (gap / cap) * (1.0 - (gap / cap));
        }
    }

    // New-bin candidate: prefer keeping open bins lean early; allow opening
    // a fresh bin late when it would have huge usable residual.
    if bin_residual == bin_capacity {
        score = 45.0 * (1.0 - progress) + 0.5 * pr + 8.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" residue classes modulo common item sizes (capacity fractions).
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by 10 are most reusable; penalize awkward ones.
        let class = match pr % 10 {
            0 => -8.0,
            5 => -3.0,
            2 | 8 => 2.0,
            _ => 4.0,
        };
        score += class;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use this residual: mild penalty proportional to waste.
            score += (next_item_size - pr).min(pr) as f64 * 0.15;
        }
    }

    // Integer-division thresholds on post_residual: small leftovers are dead space.
    if pr > 0 && pr < 10 {
        score += 12.0 * (10 - pr) as f64 / 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
        // But if the item is huge and mean residual is low, new bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Tightness bonus: prefer bins whose fill ratio after placement is high.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mild stream-progression pressure to consolidate late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps after placement are nearly unusable.
    // Penalize post_residual that falls into a "dead zone" (too small for typical items).
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // The smaller and more useless the gap, the worse.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward bins whose residual is well matched to the item (tight fit ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean, it's a
    // laggard bin; prefer filling it rather than leaving many stragglers.
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.5;
    } else {
        score += (residual - mean_residual) * 0.2;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this gap -> dead space for the lookahead
            score += (post_residual as f64) * 0.4;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly, but relax that penalty
    // when existing residuals are all poor (large mean residual relative to item).
    if bin_residual == bin_capacity {
        let poor_fit = (residual - item_size as f64) / bin_capacity as f64;
        let base = 30.0 + 40.0 * (1.0 - poor_fit.clamp(0.0, 1.0));
        score += base;
        // Late in the stream, opening fresh bins is more wasteful.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by init.
    // Normalize tightness relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item exactly/well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: item + next item fill bin completely.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill now.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, mild competition pressure: prefer the best fit harder.
        score -= 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize leaving dead space too small for the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Late-stream consolidation: near the end, favor closing out bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Prefer filling nearly-full bins over opening new bins: make empty new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}
